        let known = placement_digest("distributed", 48, &shards());
        let mut anonymous = shards();
        anonymous[0].hw = None;
        assert_ne!(
            known,
            placement_digest("distributed", 48, &anonymous),
            "absence of a fingerprint must not hash like the presence of one"
        );
    }

