    #[test]
    fn key_changes_when_ctx_changes() {
        let small = MeasurementKey::for_plan(
            HostIdentity::from_live_mesh(Some(42)).unwrap(),
            model_fingerprint(&sizes(), 48),
            placement_digest("distributed", 48, &shards()),
            8_192,
            LinkClass::Direct,
