    #[test]
    fn model_fingerprint_is_quant_sensitive() {
        let mut requantised = sizes();
        requantised[0].2 = 1_500;
        assert_ne!(
            model_fingerprint(&sizes(), 48),
            model_fingerprint(&requantised, 48)
        );
