    // --- the hypothetical bar --------------------------------------------

    #[test]
    fn an_unidentified_host_yields_no_identity() {
        assert!(
            HostIdentity::from_live_mesh(None).is_none(),
            "without a host fingerprint there is no key, so `--devices` cannot match a record"
        );
