        assert_eq!(back.verdict, r.verdict);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn bench flywheel run …` — the Fidelity-Flywheel loop's READ side.
//!
//! Drives an autonomously-generated probe set (I1 corpus self-supervision)
//! through the SAME live chat path the chaos bench uses (`run_live`, sealed to
//! one corpus), classifies each answer with the shared forced-choice judges,
//! verifies it against the probe's witness with the pure
//! `DeterministicVerifier`, scores the two red-lines (reusing the chaos scorer
//! of record), and captures every failure as a durable regression case.
//!
//! This is generator-agnostic by construction: it asks a
//! [`sovereign_eval::flywheel::Generator`] for probes and treats them
//! uniformly, so I2–I5 reuse this orchestrator unchanged — they only change
//! which generator is selected.
//!
//! The WRITE side (proposing + gating a scaffolding change) is
//! `bench_cmd::promote`; this command measures, captures, and reports.

use std::path::PathBuf;
use std::sync::Arc;

use sovereign_core::traits::InferenceProvider;
use sovereign_eval::chaos_monkey::{score, AgentAction, CalibrationReport, Gates, QuestionType};
use sovereign_eval::flywheel::generators::corpus::{AbsentSource, CorpusGenerator};
use sovereign_eval::flywheel::{
    by_id, generator_ids, validate_fairness, DeterministicVerifier, Observation, Probe,
    RegressionBank, RegressionCase, Verdict,
};
use sovereign_inference::remote::RemoteApiProvider;

use crate::bench_cmd::live_runner::{classify_abstain, classify_caveat, run_live};
use crate::chat_cmd::bootstrap::build_session;
use crate::chat_cmd::config::parse_globals;
use sovereign_cli_shared::help::{self, Help, HelpSection};

const HELP: Help = Help {
    command: "svrn bench flywheel",
    summary: "Fidelity-Flywheel read side: generate probes from a corpus, run them through the live chat path, verify groundedness/abstention, capture failures as regression cases.",
    sections: &[
        HelpSection::Usage(
            "svrn bench flywheel run --corpus <id> [--mine-path <dir>] [--absent-bank <bank.toml>] [--withheld-path <dir>] [--n N] [--seed N] [--judge-model <stem>] [--out <jsonl>] [--regressions <jsonl>] [--no-capture]",
        ),
        HelpSection::Subcommands(&[(
            "run",
            "Generate I1 probes (Present mined from --mine-path's atlas/atoms.json; Absent from --absent-bank or --withheld-path), run each through the live path sealed to --corpus, verify + score the two red-lines, capture failures.",
        )]),
        HelpSection::Notes(
            "Present probes need an ENRICHED corpus root (--mine-path with atlas/atoms.json); a corpus with no enrichment yields no Present probes. Absent probes come from a curated bank (--absent-bank) or a withheld, enriched-but-unindexed slice (--withheld-path). The verifier is pure and reuses the chaos two-red-line scorer; failures are captured to sovereign/bench/flywheel/regressions/<corpus>.jsonl (fairness-validated, deduped).",
        ),
    ],
};

const PROVIDER_CTX: u32 = 8192;

pub async fn cmd_flywheel(args: &[String]) -> i32 {
    if args.is_empty() || matches!(args[0].as_str(), "--help" | "-h" | "help") {
        help::print(&HELP);
        return if args.is_empty() { 2 } else { 0 };
    }
    match args[0].as_str() {
        "run" => run(&args[1..]).await,
        "redteam" => super::redteam::cmd_redteam(&args[1..]).await,
        other => {
            eprintln!("error: unknown flywheel subcommand `{other}`");
            help::print(&HELP);
            2
        }
    }
}

struct Args {
    generator: String,
    corpus: String,
    mine_path: Option<PathBuf>,
    absent_bank: Option<PathBuf>,
    withheld_path: Option<PathBuf>,
    n: usize,
    seed: u64,
    judge_model: String,
    base_url: String,
    out: PathBuf,
    regressions: Option<PathBuf>,
    capture: bool,
}

fn parse_args(rest: &[String]) -> Result<Args, String> {
    let mut generator = "i1_corpus".to_string();
    let mut corpus: Option<String> = None;
    let mut mine_path: Option<PathBuf> = None;
    let mut absent_bank: Option<PathBuf> = None;
    let mut withheld_path: Option<PathBuf> = None;
    let mut n = 12usize;
    let mut seed = 0u64;
    let mut judge_model = "fast".to_string();
    let mut base_url = "http://localhost:9741".to_string();
    let mut out = PathBuf::from("target/flywheel/results.jsonl");
    let mut regressions: Option<PathBuf> = None;
    let mut capture = true;

    let mut i = 0;
    macro_rules! val {
        ($l:expr) => {{
            i += 1;
            rest.get(i)
                .cloned()
                .ok_or_else(|| format!("{} requires a value", $l))?
        }};
    }
    while i < rest.len() {
        match rest[i].as_str() {
            "--generator" => generator = val!("--generator"),
            "--corpus" => corpus = Some(val!("--corpus")),
            "--mine-path" => mine_path = Some(PathBuf::from(val!("--mine-path"))),
            "--absent-bank" => absent_bank = Some(PathBuf::from(val!("--absent-bank"))),
            "--withheld-path" => withheld_path = Some(PathBuf::from(val!("--withheld-path"))),
            "--n" => n = val!("--n").parse().map_err(|_| "--n must be a usize")?,
            "--seed" => seed = val!("--seed").parse().map_err(|_| "--seed must be a u64")?,
            "--judge-model" => judge_model = val!("--judge-model"),
            "--base-url" => base_url = val!("--base-url"),
            "--out" => out = PathBuf::from(val!("--out")),
            "--regressions" => regressions = Some(PathBuf::from(val!("--regressions"))),
            "--no-capture" => capture = false,
            other => return Err(format!("unknown flag `{other}`")),
        }
        i += 1;
    }
    Ok(Args {
        generator,
        corpus: corpus.ok_or("--corpus is required (the corpus id to seal retrieval to)")?,
        mine_path,
        absent_bank,
        withheld_path,
        n,
        seed,
        judge_model,
        base_url,
        out,
        regressions,
        capture,
    })
}

async fn run(rest: &[String]) -> i32 {
    let (mut globals, rest) = match parse_globals(rest) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("error: {e}");
            return 2;
        }
    };
    if globals.temperature.is_none() {
        globals.temperature = Some(0.0);
    }
    let args = match parse_args(&rest) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {e}");
            help::print(&HELP);
            return 2;
        }
    };

    // ── Build the probe set ──
    // The generic registry produces a default-configured generator; I1's
    // absent source is set from the flags (the registry default is None).
    let probes = if args.generator == "i1_corpus" {
        let absent = if let Some(w) = args.withheld_path.clone() {
            AbsentSource::HeldOutSlice { withheld: w }
        } else if let Some(b) = args.absent_bank.clone() {
            AbsentSource::CuratedBank(b)
        } else {
            AbsentSource::None
        };
        let generator = CorpusGenerator { absent };
        use sovereign_eval::flywheel::Generator as _;
        generator.generate(args.n, args.seed, args.mine_path.as_deref())
    } else {
        match by_id(&args.generator) {
            Some(g) => g.generate(args.n, args.seed, args.mine_path.as_deref()),
            None => {
                eprintln!(
                    "error: unknown --generator `{}`. Registered: {}",
                    args.generator,
                    generator_ids().join(", ")
                );
                return 2;
            }
        }
    };

    if probes.is_empty() {
        eprintln!(
            "error: generator `{}` produced no probes.\n  \
             For I1 Present probes, pass --mine-path <enriched-corpus-root> (needs atlas/atoms.json).\n  \
             For Absent probes, pass --absent-bank <bank.toml> or --withheld-path <dir>.",
            args.generator
        );
        return 1;
    }
    // Defense-in-depth: the fairness contract is enforced at generation, but
    // re-check here so an unfair probe can never reach the model (or capture).
    if let Some(bad) = probes.iter().find_map(|p| validate_fairness(p).err()) {
        eprintln!("error: generator emitted an unfair probe: {bad}");
        return 1;
    }
    let n_answerable = probes.iter().filter(|p| p.qtype.is_answerable()).count();
    let n_absent = probes.len() - n_answerable;
    eprintln!(
        "[flywheel] generator={} corpus={} probes={} (answerable={}, absent={})",
        args.generator,
        args.corpus,
        probes.len(),
        n_answerable,
        n_absent,
    );

    // ── Live session + judge ──
    let session = match build_session(&globals).await {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: could not build chat session: {e}");
            return 1;
        }
    };
    let v1 = format!("{}/v1", args.base_url.trim_end_matches('/'));
    let judge: Arc<dyn InferenceProvider> = Arc::new(RemoteApiProvider::new(
        &v1,
        None,
        &args.judge_model,
        PROVIDER_CTX,
    ));
    let model_id = globals
        .chat_model
        .clone()
        .unwrap_or_else(|| "primary".to_string());

    // ── Run + verify each probe ──
    let verifier = DeterministicVerifier;
    let mut verdicts: Vec<Verdict> = Vec::with_capacity(probes.len());
    for (pi, probe) in probes.iter().enumerate() {
        let verdict = run_and_verify(
            &session,
            judge.as_ref(),
            &args.judge_model,
            &args.corpus,
            &model_id,
            &verifier,
            probe,
        )
        .await;
        eprintln!(
            "  [{:>2}/{}] {:<20} act={:<9} {}",
            pi + 1,
            probes.len(),
            probe.qtype.label(),
            format!("{:?}", verdict.row.agent_action),
            match &verdict.failure {
                None => "PASS".to_string(),
                Some(f) => format!("FAIL {f:?}"),
            },
        );
        verdicts.push(verdict);
    }

    // ── Score + glassbox ──
    let rows: Vec<_> = verdicts.iter().map(|v| v.row.clone()).collect();
    if let Err(e) = write_jsonl(&args.out, &verdicts) {
        eprintln!("error: could not write {:?}: {e}", args.out);
        return 1;
    }
    let report = score(&rows);
    let gates = Gates::default();
    let verdict = report.verdict(&gates);
    print_summary(&report, &verdicts);

    // ── Capture failures as regression cases ──
    if args.capture {
        let path = args.regressions.clone().unwrap_or_else(|| {
            PathBuf::from(format!(
                "sovereign/bench/flywheel/regressions/{}.jsonl",
                args.corpus
            ))
        });
        let captured_at = chrono::Utc::now().to_rfc3339();
        let source_run = format!("flywheel:{}:seed{}", args.corpus, args.seed);
        let mut newly = 0usize;
        for (probe, v) in probes.iter().zip(&verdicts) {
            let Some(failure) = v.failure else { continue };
            let case = RegressionCase {
                id: format!("{}-{}", source_run, probe.id),
                probe: probe.clone(),
                failure,
                determinism: v.determinism,
                captured_answer_excerpt: v.row.answer_excerpt.clone(),
                captured_chunks: Vec::new(),
                corpus: args.corpus.clone(),
                model_id: model_id.clone(),
                captured_at: captured_at.clone(),
                source_run: source_run.clone(),
            };
            match RegressionBank::capture(&path, &case) {
                Ok(true) => newly += 1,
                Ok(false) => {}
                Err(e) => eprintln!("  [capture] skipped {}: {e}", probe.id),
            }
        }
        eprintln!("[capture] {newly} new regression case(s) → {path:?}");
    }

    eprintln!("[out] wrote {} verdicts → {:?}", verdicts.len(), args.out);
    if verdict.overall_pass {
        0
    } else {
        1
    }
}

/// One probe → live answer → observation (judge classification) → verdict.
async fn run_and_verify(
    session: &crate::chat_cmd::bootstrap::ChatSession,
    judge: &dyn InferenceProvider,
    judge_model: &str,
    corpus: &str,
    model_id: &str,
    verifier: &DeterministicVerifier,
    probe: &Probe,
) -> Verdict {
    let live = run_live(session, corpus, &probe.query).await;
    let visible = live.visible;
    let chunks = live.retrieved_chunk_texts;

    let action = match classify_abstain(judge, judge_model, &visible).await {
        Some(true) => AgentAction::Abstained,
        Some(false) => AgentAction::Answered,
        None => {
            if visible.trim().len() < 24 {
                AgentAction::Abstained
            } else {
                AgentAction::Answered
            }
        }
    };

    // Provenance caveat — only for out-of-domain answers (mirrors chaos).
    let caveat_present =
        if probe.qtype == QuestionType::AbsentOutOfDomain && action == AgentAction::Answered {
            Some(
                classify_caveat(judge, judge_model, &visible)
                    .await
                    .unwrap_or(false),
            )
        } else {
            None
        };

    let obs = Observation {
        action,
        answer: &visible,
        chunks: &chunks,
        caveat_present,
    };
    verifier.verify(probe, &obs, model_id, corpus)
}

fn write_jsonl(path: &std::path::Path, verdicts: &[Verdict]) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let mut f = std::fs::File::create(path)?;
    use std::io::Write as _;
    for v in verdicts {
        let line = serde_json::to_string(v)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e.to_string()))?;
        writeln!(f, "{line}")?;
    }
    Ok(())
}

fn print_summary(report: &CalibrationReport, verdicts: &[Verdict]) {
    let c = &report.counts;
    println!("\n── fidelity flywheel: grounded calibration (I1) ──");
    println!(
        "  competence-when-present : {:.2}   [correct {}/{}, timid {}]",
        report.competence, c.answerable_correct, c.answerable, c.answerable_abstained,
    );
    eprintln!(
        "  honesty-when-absent     : {:.2}   [honest {}/{}, HALLUCINATED {}]",
        report.honesty, c.absent_honest, c.absent, c.absent_hallucinated,
    );
    // Failure-class tally (the taxonomy glassbox).
    let mut tally: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for v in verdicts {
        if let Some(f) = v.failure {
            *tally.entry(format!("{f:?}")).or_default() += 1;
        }
    }
    if tally.is_empty() {
        eprintln!("  failures: none");
    } else {
        let parts: Vec<String> = tally.iter().map(|(k, n)| format!("{k}={n}")).collect();
        eprintln!("  failures by class: {}", parts.join(" "));
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Lane baselines — promote an *absolute-verdict* bench into a
//! *baseline-relative* CI gate.
//!
//! Some benches return an **absolute** verdict that is a true finding for the
//! current system, not a regression signal: chaos-monkey is designed to break
//! the present agent (NO-GO), and mechanism-fidelity returns NO-GO for any
//! model that isn't mechanism-faithful. Gating CI on their pass/fail would
//! pin the build permanently red. The fix is to gate on **change vs a captured
//! baseline** instead: fail only when a headline metric moves in the wrong
//! direction by more than its tolerance.
//!
//! This module is the small, pure, self-describing primitive that makes that
//! uniform across lanes. A [`LaneBaseline`] is a flat bag of named
//! [`LaneMetric`]s; each metric carries its own [`Direction`] (which way is
//! "worse") and `tolerance` (how much movement is noise), so the baseline JSON
//! is legible on its own — a reader can see exactly what would count as a
//! regression without consulting code. [`diff`] applies those per-metric rules;
//! the comparison logic lives in one place and is reused by every lane adapter
//! in [`super::gate`].

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

/// A slot alias, not a concrete model — the historical placeholder a
/// baseline recorded before resolution existed. We refuse to attribute
/// a baseline to one of these: an alias is not a model.
pub(crate) fn is_alias_marker(s: &str) -> bool {
    let s = s.trim().trim_start_matches("commonwealth/");
    matches!(s, "primary" | "fast" | "embed" | "code" | "reasoning")
}

/// Which direction of movement counts as a **regression** for a metric.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Direction {
    /// Bigger is better (competence, honesty, judge coverage, first-failure
    /// turn). A *drop* past tolerance is a regression.
    HigherIsBetter,
    /// Smaller is better (hallucination rate, latency). A *rise* past
    /// tolerance is a regression.
    LowerIsBetter,
    /// A witness that must stay near zero (the mechanism-fidelity control
    /// Δ̄ — "the scoring join is intact"). Drift *away from zero* in either
    /// sign, past tolerance, is a regression. Compared on absolute value.
    NearZero,
}

/// One headline scalar in a lane baseline, fully self-describing: the value,
/// which way is worse, and how much movement is noise.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct LaneMetric {
    pub value: f64,
    pub direction: Direction,
    /// Movement strictly within ±tolerance is treated as noise (not a
    /// regression and not an improvement). Chosen per metric by the adapter
    /// — e.g. coarser for small-n fractions (one-item GPU-nondeterminism
    /// flips), tight for the deterministic control witness.
    pub tolerance: f64,
}

impl LaneMetric {
    pub fn higher_is_better(value: f64, tolerance: f64) -> Self {
        Self {
            value,
            direction: Direction::HigherIsBetter,
            tolerance,
        }
    }
    pub fn lower_is_better(value: f64, tolerance: f64) -> Self {
        Self {
            value,
            direction: Direction::LowerIsBetter,
            tolerance,
        }
    }
    pub fn near_zero(value: f64, tolerance: f64) -> Self {
        Self {
            value,
            direction: Direction::NearZero,
            tolerance,
        }
    }
}

/// A captured set of headline metrics for one lane — the on-disk baseline
/// (serialised to `<bench_root>/<group>/baselines/<id>/latest.json`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LaneBaseline {
    pub lane: String,
    /// When this baseline was captured (RFC-3339). Provenance only.
    pub captured_at: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub corpus: Option<String>,
    /// Legacy / legible model field — the concrete GGUF stem when
    /// known (was historically the slot alias `"primary"`, which is
    /// why `model_attribution` now carries the real provenance).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model: Option<String>,
    /// Structured, human-readable model provenance: the concrete stem
    /// plus manifest-derived `base_name`/`family`/`quant`. Populated by
    /// [`Self::attribute`] from the resolved model stem. `None` on
    /// legacy baselines and when slot resolution failed at capture
    /// time — the report rollup buckets those as "unattributed".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub model_attribution: Option<sovereign_core::models_manifest::ModelAttribution>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
    pub metrics: BTreeMap<String, LaneMetric>,
}

impl LaneBaseline {
    pub fn new(lane: impl Into<String>, captured_at: impl Into<String>) -> Self {
        Self {
            lane: lane.into(),
            captured_at: captured_at.into(),
            corpus: None,
            model: None,
            model_attribution: None,
            note: None,
            metrics: BTreeMap::new(),
        }
    }

    /// Attribute this baseline to the concrete model that produced it,
    /// given the model stem recorded on the run's transcript rows (or
    /// any concrete GGUF stem). Sets both the legible `model` field
    /// (the stem) and the structured `model_attribution`, enriched
    /// deterministically from the bundled manifest — no daemon needed,
    /// so the gate re-score path attributes correctly from the
    /// transcript alone.
    ///
    /// A `None` or alias-shaped stem (`"primary"`/`"fast"` — the legacy
    /// unresolved marker) leaves attribution empty rather than
    /// recording the alias as if it were a model.
    pub fn attribute(&mut self, model_stem: Option<&str>) {
        let Some(stem) = model_stem.filter(|s| !s.is_empty() && !is_alias_marker(s)) else {
            return;
        };
        self.model = Some(stem.to_string());
        self.model_attribution =
            Some(sovereign_core::models_manifest::DEFAULT_MANIFEST.attribution_for_file(stem));
    }
    pub fn with(mut self, name: impl Into<String>, metric: LaneMetric) -> Self {
        self.metrics.insert(name.into(), metric);
        self
    }
}

/// How a single metric moved between baseline and current.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Movement {
    Regressed,
    Improved,
    Unchanged,
}

/// Per-metric comparison outcome — the glassbox row.
#[derive(Debug, Clone)]
pub struct MetricDelta {
    pub name: String,
    pub baseline: f64,
    pub current: f64,
    /// Signed `current − baseline` (raw, for display). The regression
    /// decision uses `direction`-aware comparison, not this raw sign.
    pub delta: f64,
    pub tolerance: f64,
    pub direction: Direction,
    pub movement: Movement,
}

/// The result of comparing a current run against a baseline.
#[derive(Debug, Clone, Default)]
pub struct LaneDiff {
    /// True when there was no baseline to compare against — first run.
    pub first_run: bool,
    pub deltas: Vec<MetricDelta>,
    /// Metrics present in the baseline but absent from the current run
    /// (schema drift / a metric stopped being emitted). Reported, not gated.
    pub missing: Vec<String>,
}

impl LaneDiff {
    pub fn regressions(&self) -> impl Iterator<Item = &MetricDelta> {
        self.deltas
            .iter()
            .filter(|d| d.movement == Movement::Regressed)
    }
    pub fn improvements(&self) -> impl Iterator<Item = &MetricDelta> {
        self.deltas
            .iter()
            .filter(|d| d.movement == Movement::Improved)
    }
    pub fn n_regressed(&self) -> usize {
        self.regressions().count()
    }
}

/// Classify one metric's movement, honouring its direction + tolerance.
///
/// A non-finite *current* value is always a regression: the bench produced an
/// undefined metric (e.g. an empty population → NaN), which we can never
/// certify as "no worse than baseline".
fn classify(prev: f64, cur: &LaneMetric) -> Movement {
    if !cur.value.is_finite() {
        return Movement::Regressed;
    }
    let tol = cur.tolerance.abs();
    match cur.direction {
        Direction::HigherIsBetter => {
            if cur.value < prev - tol {
                Movement::Regressed
            } else if cur.value > prev + tol {
                Movement::Improved
            } else {
                Movement::Unchanged
            }
        }
        Direction::LowerIsBetter => {
            if cur.value > prev + tol {
                Movement::Regressed
            } else if cur.value < prev - tol {
                Movement::Improved
            } else {
                Movement::Unchanged
            }
        }
        Direction::NearZero => {
            let (pa, ca) = (prev.abs(), cur.value.abs());
            if ca > pa + tol {
                Movement::Regressed
            } else if ca < pa - tol {
                Movement::Improved
            } else {
                Movement::Unchanged
            }
        }
    }
}

/// Compare a `current` run against an optional `baseline`. The **current**
/// metric is authoritative for direction + tolerance (it reflects the present
/// adapter's intent), so editing a tolerance takes effect immediately.
pub fn diff(baseline: Option<&LaneBaseline>, current: &LaneBaseline) -> LaneDiff {
    let Some(prev) = baseline else {
        return LaneDiff {
            first_run: true,
            deltas: Vec::new(),
            missing: Vec::new(),
        };
    };
    let mut deltas = Vec::new();
    for (name, cur) in &current.metrics {
        // A metric with no baseline counterpart is new — report it as an
        // unchanged row at its own value (informational; never a regression).
        let prev_val = prev.metrics.get(name).map(|m| m.value);
        let movement = match prev_val {
            Some(p) => classify(p, cur),
            None => Movement::Unchanged,
        };
        deltas.push(MetricDelta {
            name: name.clone(),
            baseline: prev_val.unwrap_or(f64::NAN),
            current: cur.value,
            delta: cur.value - prev_val.unwrap_or(cur.value),
            tolerance: cur.tolerance,
            direction: cur.direction,
            movement,
        });
    }
    let missing = prev
        .metrics
        .keys()
        .filter(|k| !current.metrics.contains_key(*k))
        .cloned()
        .collect();
    LaneDiff {
        first_run: false,
        deltas,
        missing,
    }
}

fn dir_glyph(d: Direction) -> &'static str {
    match d {
        Direction::HigherIsBetter => "↑",
        Direction::LowerIsBetter => "↓",
        Direction::NearZero => "≈0",
    }
}

/// Render a glassbox table of the diff and return the CI exit code.
///
/// - first run (no baseline) → `0`, with a clear "capture with
///   `--update-baseline`" line and a `first-run` marker the CI script reads as
///   a setup gap, not a pass-by-regression.
/// - any regression → `1`.
/// - otherwise → `0`.
///
/// Always prints an `N regressed` line so the CI runner's existing scoreboard
/// parser (shared with `bench all`) sees a consistent vocabulary.
pub fn render_and_exit_code(diff: &LaneDiff, lane: &str) -> i32 {
    println!("\n── lane gate: {lane} (baseline-relative) ──");
    if diff.first_run {
        println!("  no baseline yet — first-run. Capture one with --update-baseline.");
        eprintln!("  0 regressed (first-run)");
        return 0;
    }
    eprintln!(
        "  {:<28} {:>10} {:>10} {:>9} {:>8}  dir  status",
        "metric", "baseline", "current", "Δ", "tol"
    );
    for d in &diff.deltas {
        let status = match d.movement {
            Movement::Regressed => "REGRESSED",
            Movement::Improved => "improved",
            Movement::Unchanged => "ok",
        };
        eprintln!(
            "  {:<28} {:>10.4} {:>10.4} {:>+9.4} {:>8.4}  {:<3}  {}",
            d.name,
            d.baseline,
            d.current,
            d.delta,
            d.tolerance,
            dir_glyph(d.direction),
            status,
        );
    }
    for m in &diff.missing {
        eprintln!(
            "  {m:<28} {:>10} (in baseline, absent now — schema drift?)",
            "—"
        );
    }
    let n_reg = diff.n_regressed();
    let n_imp = diff.improvements().count();
    eprintln!(
        "  ── {} regressed · {} improved · {} ok ──",
        n_reg,
        n_imp,
        diff.deltas.len().saturating_sub(n_reg + n_imp),
    );
    if n_reg == 0 {
        eprintln!("  VERDICT: PASS ✓  — no metric regressed past tolerance vs baseline.");
        0
    } else {
        eprintln!("  VERDICT: FAIL ✗  — {n_reg} metric(s) regressed vs baseline.");
        1
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn base() -> LaneBaseline {
        LaneBaseline::new("chaos", "2026-06-07")
            .with("competence", LaneMetric::higher_is_better(0.57, 0.10))
            .with("honesty", LaneMetric::higher_is_better(0.36, 0.10))
            .with(
                "hallucination_rate",
                LaneMetric::lower_is_better(0.64, 0.10),
            )
            .with("control_delta", LaneMetric::near_zero(0.0, 0.05))
    }

    #[test]
    fn first_run_when_no_baseline() {
        let d = diff(None, &base());
        assert!(d.first_run);
        assert_eq!(d.n_regressed(), 0);
    }

    #[test]
    fn identical_run_has_no_regression() {
        let d = diff(Some(&base()), &base());
        assert!(!d.first_run);
        assert_eq!(d.n_regressed(), 0);
        assert_eq!(d.improvements().count(), 0);
    }

    #[test]
    fn higher_is_better_drop_past_tolerance_regresses() {
        // competence 0.57 → 0.40 (drop 0.17 > tol 0.10) is a regression.
        let cur = LaneBaseline::new("chaos", "now")
            .with("competence", LaneMetric::higher_is_better(0.40, 0.10));
        let prev = LaneBaseline::new("chaos", "old")
            .with("competence", LaneMetric::higher_is_better(0.57, 0.10));
        let d = diff(Some(&prev), &cur);
        assert_eq!(d.n_regressed(), 1);
    }

    #[test]
    fn one_item_flip_within_tolerance_is_noise() {
        // honesty 0.36 → 0.27 (one of 11 items flips ≈0.09 < tol 0.10): ok.
        let cur = LaneBaseline::new("chaos", "now")
            .with("honesty", LaneMetric::higher_is_better(0.27, 0.10));
        let prev = LaneBaseline::new("chaos", "old")
            .with("honesty", LaneMetric::higher_is_better(0.36, 0.10));
        let d = diff(Some(&prev), &cur);
        assert_eq!(
            d.n_regressed(),
            0,
            "single-item nondeterminism must not gate"
        );
    }

    #[test]
    fn lower_is_better_rise_regresses() {
        let cur = LaneBaseline::new("chaos", "now").with(
            "hallucination_rate",
            LaneMetric::lower_is_better(0.80, 0.10),
        );
        let prev = LaneBaseline::new("chaos", "old").with(
            "hallucination_rate",
            LaneMetric::lower_is_better(0.64, 0.10),
        );
        assert_eq!(diff(Some(&prev), &cur).n_regressed(), 1);
        // ...and a drop is an improvement, not a regression.
        let better = LaneBaseline::new("chaos", "now").with(
            "hallucination_rate",
            LaneMetric::lower_is_better(0.40, 0.10),
        );
        let d = diff(Some(&prev), &better);
        assert_eq!(d.n_regressed(), 0);
        assert_eq!(d.improvements().count(), 1);
    }

    #[test]
    fn near_zero_drift_either_sign_regresses() {
        let prev = LaneBaseline::new("mech", "old")
            .with("control_delta", LaneMetric::near_zero(0.00, 0.05));
        // +0.20 drift away from zero → regression (scoring join broke).
        let up = LaneBaseline::new("mech", "now")
            .with("control_delta", LaneMetric::near_zero(0.20, 0.05));
        assert_eq!(diff(Some(&prev), &up).n_regressed(), 1);
        // −0.20 drift is equally bad.
        let down = LaneBaseline::new("mech", "now")
            .with("control_delta", LaneMetric::near_zero(-0.20, 0.05));
        assert_eq!(diff(Some(&prev), &down).n_regressed(), 1);
        // staying near zero is fine.
        let flat = LaneBaseline::new("mech", "now")
            .with("control_delta", LaneMetric::near_zero(0.02, 0.05));
        assert_eq!(diff(Some(&prev), &flat).n_regressed(), 0);
    }

    #[test]
    fn nan_current_is_a_regression() {
        let prev = LaneBaseline::new("chaos", "old")
            .with("honesty", LaneMetric::higher_is_better(0.36, 0.10));
        let cur = LaneBaseline::new("chaos", "now")
            .with("honesty", LaneMetric::higher_is_better(f64::NAN, 0.10));
        assert_eq!(diff(Some(&prev), &cur).n_regressed(), 1);
    }

    #[test]
    fn missing_metric_is_reported_not_gated() {
        let prev = base();
        let cur = LaneBaseline::new("chaos", "now")
            .with("competence", LaneMetric::higher_is_better(0.57, 0.10));
        let d = diff(Some(&prev), &cur);
        assert_eq!(d.n_regressed(), 0);
        assert!(d.missing.contains(&"honesty".to_string()));
    }

    #[test]
    fn attribute_refuses_alias_and_accepts_concrete_stem() {
        // The alias placeholder must never become an attribution.
        let mut b = LaneBaseline::new("chaos-monkey", "now");
        b.attribute(Some("primary"));
        assert!(b.model.is_none(), "'primary' is a slot alias, not a model");
        assert!(b.model_attribution.is_none());

        b.attribute(Some("commonwealth/primary"));
        assert!(
            b.model_attribution.is_none(),
            "namespaced alias also refused"
        );

        // A concrete stem sets both the legible field and the structured
        // attribution, enriched from the bundled manifest.
        b.attribute(Some("Qwen3.5-4B-Q4_K_M"));
        assert_eq!(b.model.as_deref(), Some("Qwen3.5-4B-Q4_K_M"));
        let a = b.model_attribution.expect("concrete stem attributes");
        assert_eq!(a.base_name.as_deref(), Some("Qwen3.5-4B"));
        assert_eq!(a.quant.as_deref(), Some("Q4_K_M"));
    }

    #[test]
    fn is_alias_marker_matches_canonical_slots() {
        for a in ["primary", "fast", "embed", "code", "commonwealth/primary"] {
            assert!(is_alias_marker(a), "{a} is an alias");
        }
        assert!(
            !is_alias_marker("Qwen3.5-4B-Q4_K_M"),
            "a real stem is not an alias"
        );
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Unit tests for `mesh bench`'s pure core.
//!
//! The point of the seam is that all nine validity guards can be made to fire
//! here — with no daemon, no peer, no GPU and no model. A guard that cannot be
//! tested is a guard nobody knows still works, and the shell script this
//! command replaces had exactly that problem: its guards could only be
//! exercised by reproducing the failure they were written for.

use super::*;

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

/// An SSE content frame at `t` seconds, attributed to `model`.
fn content(t: f64, model: &str, piece: &str) -> Frame {
    Frame::from_line(
        t,
        &format!(
            r#"data: {{"model":"{model}","choices":[{{"index":0,"delta":{{"content":"{piece}"}},"finish_reason":null}}]}}"#
        ),
    )
}

/// The terminal frame, with an optional usage block.
fn finish(t: f64, model: &str, reason: &str, prompt_tokens: Option<u32>) -> Frame {
    let usage = match prompt_tokens {
        Some(p) => format!(r#","usage":{{"prompt_tokens":{p},"completion_tokens":1,"total_tokens":{}}}"#, p + 1),
        None => String::new(),
    };
    Frame::from_line(
        t,
        &format!(
            r#"data: {{"model":"{model}","choices":[{{"index":0,"delta":{{}},"finish_reason":"{reason}"}}]{usage}}}"#
        ),
    )
}

/// `n` content frames one `gap` apart starting at `t0`, then a terminal frame.
fn stream(n: u32, t0: f64, gap: f64, model: &str, reason: &str) -> Vec<Frame> {
    let mut f: Vec<Frame> = (0..n)
        .map(|i| content(t0 + gap * i as f64, model, "x"))
        .collect();
    f.push(finish(t0 + gap * n as f64, model, reason, Some(12)));
    f.push(Frame::from_line(t0 + gap * n as f64, "data: [DONE]"));
    f
}

/// A trial that passes every per-trial guard, at roughly `rate` tok/s.
fn good_trial(rate: f64) -> Trial {
    parse_trial(&stream(40, 0.5, 1.0 / rate, "primary-model", "stop"))
}

/// A guard input where every guard passes, so a test can break exactly one
/// thing and attribute the resulting problem to it.
struct Scenario {
    trials: Vec<Trial>,
    primary_model_id: String,
    primary_serving_before: bool,
    primary_serving_after: Option<bool>,
    canary_tokens: u32,
    placement_before: PlacementSnapshot,
    placement_after: Option<PlacementSnapshot>,
    peers_before: Vec<(String, bool)>,
    peers_after: Vec<(String, bool)>,
    host_alive_after: HostLiveness,
}

impl Scenario {
    fn clean() -> Self {
        let p = PlacementSnapshot {
            mode: "local".into(),
            total_blocks: 0,
            local_blocks: 0,
            workers: Vec::new(),
        };
        Self {
            trials: vec![good_trial(10.0), good_trial(10.2), good_trial(9.9)],
            primary_model_id: "primary-model".into(),
            primary_serving_before: true,
            primary_serving_after: Some(true),
            canary_tokens: 8,
            placement_before: p.clone(),
            placement_after: Some(p),
            peers_before: Vec::new(),
            peers_after: Vec::new(),
            host_alive_after: HostLiveness::Alive,
        }
    }

    fn judge(&self) -> Vec<String> {
        evaluate_guards(&GuardInput {
            trials: &self.trials,
            primary_model_id: &self.primary_model_id,
            primary_serving_before: self.primary_serving_before,
            primary_serving_after: self.primary_serving_after,
            canary_tokens: self.canary_tokens,
            placement_before: &self.placement_before,
            placement_after: self.placement_after.as_ref(),
            peers_before: &self.peers_before,
            peers_after: &self.peers_after,
            host_alive_after: self.host_alive_after,
        })
    }
}

/// Assert exactly one problem fired and that it mentions `needle`.
fn only_problem(problems: &[String], needle: &str) {
    assert_eq!(
        problems.len(),
        1,
        "expected exactly one problem, got {problems:#?}"
    );
    assert!(
        problems[0].contains(needle),
        "problem did not mention {needle:?}: {}",
        problems[0]
    );
}

