        );
        assert!(rendered.contains(&format!("(part 2/{})", chunks.len())));

        // A tiny spine is one chunk covering everything.
        let small = Spine {
            assistant_texts: vec!["short".into()],
            ..Default::default()
        };
        assert_eq!(chunk_ranges(&small, 48_000), vec![(0, 1)]);
