        assert_eq!(Pricing::for_model("claude-opus-4-8").input, 5.0);
        assert_eq!(Pricing::for_model("claude-sonnet-5").input, 3.0);
        assert_eq!(Pricing::for_model("claude-haiku-4-5").input, 1.0);
