// SPDX-License-Identifier: AGPL-3.0-or-later
//! Distributed-inference auto-warm orchestration — the HTTP layer.
//!
//! When a host decides to distribute a large primary across the mesh, it must
//! NOT stream each worker its weight share at load time (the host-side `send()`
//! deadlock above ~800 MB). Instead every worker pre-seeds its RPC tensor cache
//! with its shard, so the host's `-ot` load is all `SET_TENSOR_HASH` cache hits
//! and sends zero bulk weight bytes. This module is both ends of that handshake:
//!
//! - **Worker side** ([`MeshRpcShardWarmer`], the `POST /internal/rpc-warm`
//!   backend): given the host's plan + this node's `device_index`, warm exactly
//!   this node's shard — from the whole GGUF the node already holds / fetches
//!   (`#5a`), or by range-fetching only its tensors (`#5b`, [`warm_cache_from_ranges`]).
//! - **Host side** ([`install_rpc_warm_orchestrator`]): the seam
//!   `sovereign-inference` calls during a distributing load. It fans the warm
//!   request out to every worker and blocks until all report warm — then the load
//!   proceeds with overrides. This replaces the manual `SOVEREIGN_RPC_ASSUME_WARMED`.
//!
//! The host computes the plan ONCE (`sovereign-inference::plan_distribution`) and
//! ships it whole, so warm-time placement and load-time placement derive from the
//! identical assignment and cannot diverge — the plan-agreement invariant.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use async_trait::async_trait;
use serde::{Deserialize, Serialize};

use commonwealth_api::state::{AppState, RpcShardWarmer};
use sovereign_inference::embedded::{
    build_manifest, cache_file_name, tensor_device, warm_cache_for_device, Fnv1a, NodeShard,
    RpcWarmPlan,
};

use crate::daemon::EmbeddedDaemon;

fn is_private_v4(o: [u8; 4]) -> bool {
    o[0] == 10 || (o[0] == 172 && (16..=31).contains(&o[1])) || (o[0] == 192 && o[1] == 168)
}

/// Score how likely a worker at `worker_ip` can reach a host base (`http://IP:port`)
/// — higher is better. A mesh peer reaches us best on an address in ITS OWN
/// network: a Tailscale peer (CGNAT `100.x`) reaches our `100.x`, NOT a `192.168.x`
/// LAN we happen to share but can't route across (WiFi AP client isolation — the
/// exact failure the cross-machine test hit). `-1` for an unparseable base.
fn base_reachability_score(base: &str, worker_ip: Option<std::net::IpAddr>) -> i32 {
    let Some(worker_ip) = worker_ip else {
        return 0;
    };
    let host = base
        .strip_prefix("http://")
        .map(|s| s.split('/').next().unwrap_or(s))
        .and_then(|hp| hp.rsplit_once(':').map(|(h, _)| h))
        .unwrap_or("")
        .trim_start_matches('[')
        .trim_end_matches(']');
    let Ok(ip) = host.parse::<std::net::IpAddr>() else {
        return -1;
    };
    match (ip, worker_ip) {
        (std::net::IpAddr::V4(a), std::net::IpAddr::V4(w)) => {
            let (ao, wo) = (a.octets(), w.octets());
            if ao[0..2] == wo[0..2] {
                3 // same /16
            } else if ao[0] == wo[0] {
                2 // same /8 (e.g. both Tailscale CGNAT 100.x)
            } else if is_private_v4(ao) == is_private_v4(wo) {
                1 // same category (both private, or both not)
            } else {
                0 // a private LAN vs the worker's non-private network → try last
            }
        }
        (std::net::IpAddr::V6(_), std::net::IpAddr::V6(_)) => 1,
        _ => 0, // address-family mismatch
    }
}

/// Order a host's fetch bases so the one the worker is most likely to reach comes
/// first — so the worker hits a routable address immediately instead of burning
/// its connect budget on an unroutable shared-LAN IP. Stable within a score tier.
fn order_host_bases(bases: &[String], worker_ip: Option<std::net::IpAddr>) -> Vec<String> {
    let mut ranked: Vec<(i32, usize, &String)> = bases
        .iter()
        .enumerate()
        .map(|(i, b)| (base_reachability_score(b, worker_ip), i, b))
        .collect();
    ranked.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));
    ranked.into_iter().map(|(_, _, b)| b.clone()).collect()
}

/// Whether `worker_ip` (parsed from an RPC endpoint string) may be used to
/// hand-build a raw warm-URL fallback. A loopback `worker_ip` means the
/// endpoint is a bridge-local iroh tunnel (task 6) — the hand-built
/// `http://127.0.0.1:{internal_port}/internal/rpc-warm` would be THIS
/// host's own internal router, and the resulting self-warm reports success
/// while the real worker stays cold, resurrecting the upload deadlock the
/// warm exists to prevent. Never raw-fall-back to loopback. Unparseable
/// hosts (e.g. a hostname) keep the legacy raw fallback.
fn raw_warm_fallback_allowed(worker_ip: &str) -> bool {
    worker_ip
        .parse::<std::net::IpAddr>()
        .map(|ip| !ip.is_loopback())
        .unwrap_or(true)
}

/// Render an error plus its `source()` chain — reqwest's top-level Display is just
/// "error sending request for url (…)"; the actual cause (connection refused /
/// timed out / DNS) lives in the source chain. Glassbox: a warm failure must say
/// WHY so we don't guess.
fn error_chain(e: &dyn std::error::Error) -> String {
    let mut out = e.to_string();
    let mut src = e.source();
    while let Some(s) = src {
        out.push_str(" ← ");
        out.push_str(&s.to_string());
        src = s.source();
    }
    out
}

/// The cache dir the in-process RPC worker actually reads — must mirror
/// `model_slot::rpc_cache_dir` exactly, so the bytes we warm land where the
/// worker's RPC server looks for `SET_TENSOR_HASH` hits. `Err` when caching is
/// disabled (`off` / `0` / empty): warming into a stray dir would let the load
/// stream anyway and wedge, so we refuse — the host then loads local-only (never
/// wedge). `sovereign-inference`'s `default_cache_dir` doesn't model the disabled
/// case, which is why this lives here.
fn worker_cache_dir() -> Result<PathBuf, String> {
    match std::env::var("SOVEREIGN_RPC_CACHE_DIR") {
        Ok(v) => {
            let v = v.trim();
            if v.is_empty() || v.eq_ignore_ascii_case("off") || v == "0" {
                return Err(
                    "RPC tensor cache is disabled (SOVEREIGN_RPC_CACHE_DIR=off) — \
                            cannot auto-warm; the host will load local-only"
                        .to_string(),
                );
            }
            Ok(PathBuf::from(v))
        }
        Err(_) => std::env::var("HOME")
            .map(|h| Path::new(&h).join(".sovereign").join("rpc-cache"))
            .map_err(|_| "no HOME for the default RPC cache dir".to_string()),
    }
}

// ─── Wire types (the `/internal/rpc-warm` body) ──────────────────────────────

/// One tensor's location + identity for a byte-range fetch (`#5b`): where it
/// lives in the GGUF and the FNV-1a hash its cache file is named by. The host
/// derives these from `build_manifest` for exactly this worker's shard, so the
/// worker range-GETs only its `O(model/N)` bytes and never re-hashes the file.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct TensorRange {
    pub gguf_offset: u64,
    pub nbytes: u64,
    pub hash: u64,
}

/// How the worker obtains the bytes it warms.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "mode", rename_all = "snake_case")]
pub enum RpcWarmSource {
    /// `#5a` — warm from the whole GGUF: use the copy the node already holds (the
    /// route resolves it via the servable allowlist), else fetch it from one of
    /// `peer_bases` (a host internal-port base like `http://10.0.0.1:9742`). The
    /// worker discovers size + sha from the host's `/internal/v1/models/list`.
    WholeGguf {
        #[serde(default)]
        peer_bases: Vec<String>,
    },
    /// `#5b` — range-fetch only this shard's tensors. `source_urls` are full
    /// `/internal/v1/models/file/{name}` URLs (one per host base); the worker
    /// `Range`-GETs each tensor and verifies its hash. Never holds the whole GGUF.
    ByteRanges {
        source_urls: Vec<String>,
        tensors: Vec<TensorRange>,
    },
}

/// `POST /internal/rpc-warm` request. The host sends each worker the whole `plan`
/// + this worker's `device_index` (so warm placement == load placement) and a
/// `source` describing how to get its shard's bytes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RpcWarmShardRequest {
    pub model_id: String,
    pub device_index: usize,
    pub plan: Vec<NodeShard>,
    pub source: RpcWarmSource,
    /// Hex `NodeId` (`NodeId::to_hex`) of the HOST — the node about to
    /// distribute. Lets the worker resolve its fetch bases back to the host
    /// through its OWN mesh transport (an iroh bridge on an encrypted mesh),
    /// with the raw-IP bases in `source` retained as LAN fallback. `None`
    /// from older hosts — wire back-compat, raw bases only.
    #[serde(default)]
    pub host_node_id: Option<String>,
}

/// `POST /internal/rpc-warm` success body — what this worker warmed.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct RpcWarmShardResponse {
    pub model_id: String,
    pub device_index: usize,
    pub tensors_written: usize,
    pub tensors_already_present: usize,
    pub bytes_written: u64,
}

// ─── `#5b` worker primitive: warm a shard by HTTP byte-range ─────────────────

/// Counts from a byte-range warm run.
#[derive(Debug, Default, Clone)]
pub struct WarmRangeStats {
    pub written: usize,
    pub already_present: usize,
    pub bytes_written: u64,
}

/// Fetch exactly this shard's tensors by HTTP `Range` from one of `source_urls`
/// (the host's `serve_model_file`, which honors `Range`), verify each against its
/// expected FNV-1a hash, and write it as a cache file named by that hash —
/// byte-identical to what the local-GGUF warmer writes, so the host's later
/// `SET_TENSOR_HASH` is a hit. Streams each tensor (no whole-tensor buffer).
/// Idempotent (a present, right-sized file is left). This is the only warm path
/// that keeps a worker at `O(model/N)` on disk — the `500 GB × N-node` endgame.
///
/// `source_urls` are tried in order, sticking with the first that serves a range,
/// so a multi-homed host degrades gracefully.
pub async fn warm_cache_from_ranges(
    http: &reqwest::Client,
    source_urls: &[String],
    tensors: &[TensorRange],
    cache_dir: &Path,
) -> Result<WarmRangeStats, String> {
    use futures::StreamExt;
    use tokio::io::AsyncWriteExt;

    if source_urls.is_empty() {
        return Err("no source URL for byte-range warm".to_string());
    }
    std::fs::create_dir_all(cache_dir).map_err(|e| format!("create cache dir: {e}"))?;
    let mut stats = WarmRangeStats::default();
    // Sticky preferred source: once one serves a range, keep using it.
    let mut url_idx = 0usize;

    for t in tensors {
        let name = cache_file_name(t.hash);
        let cache_file = cache_dir.join(&name);
        // Idempotent: skip a present, correctly-sized entry.
        if let Ok(meta) = std::fs::metadata(&cache_file) {
            if meta.len() == t.nbytes {
                stats.already_present += 1;
                continue;
            }
        }

        let end = t.gguf_offset + t.nbytes - 1;
        let range = format!("bytes={}-{}", t.gguf_offset, end);

        // Try sources starting at the sticky index, wrapping once.
        let mut resp = None;
        let mut last_err = String::new();
        for step in 0..source_urls.len() {
            let i = (url_idx + step) % source_urls.len();
            match http
                .get(&source_urls[i])
                .header(reqwest::header::RANGE, range.as_str())
                .send()
                .await
            {
                Ok(r)
                    if r.status() == reqwest::StatusCode::PARTIAL_CONTENT
                        || r.status().is_success() =>
                {
                    url_idx = i;
                    resp = Some(r);
                    break;
                }
                Ok(r) => last_err = format!("{}: status {}", source_urls[i], r.status()),
                Err(e) => last_err = format!("{}: {e}", source_urls[i]),
            }
        }
        let resp =
            resp.ok_or_else(|| format!("range GET {name} failed on all sources: {last_err}"))?;

        // Stream → hash → temp file; verify both length and hash; atomic rename so
        // a torn write never looks like a valid cache entry.
        let tmp = cache_dir.join(format!(".{name}.{}.tmp", std::process::id()));
        let mut hasher = Fnv1a::new();
        let mut written: u64 = 0;
        {
            let mut out = tokio::fs::File::create(&tmp)
                .await
                .map_err(|e| format!("create {}: {e}", tmp.display()))?;
            let mut stream = resp.bytes_stream();
            while let Some(chunk) = stream.next().await {
                let chunk = chunk.map_err(|e| format!("range body {name}: {e}"))?;
                hasher.update(&chunk);
                out.write_all(&chunk)
                    .await
                    .map_err(|e| format!("write {name}: {e}"))?;
                written += chunk.len() as u64;
            }
            out.flush()
                .await
                .map_err(|e| format!("flush {name}: {e}"))?;
        }

        if written != t.nbytes {
            let _ = std::fs::remove_file(&tmp);
            return Err(format!(
                "range {name}: got {written} bytes, expected {} — host served the wrong range",
                t.nbytes
            ));
        }
        if hasher.finish() != t.hash {
            // The host's bytes don't hash to the cache key the host itself will
            // request — distributing now would miss + stream. Refuse.
            let _ = std::fs::remove_file(&tmp);
            return Err(format!(
                "range {name}: content hash mismatch — fetched bytes are not the expected tensor"
            ));
        }
        std::fs::rename(&tmp, &cache_file).map_err(|e| format!("rename {name}: {e}"))?;
        stats.written += 1;
        stats.bytes_written += written;
        tracing::debug!(tensor = %name, bytes = written, "rpc-warm: wrote cache entry from byte range");
    }
    Ok(stats)
}

// ─── Worker side: the `RpcShardWarmer` impl ──────────────────────────────────

/// Worker-side warmer wired into `AppState` by the daemon. Holds an HTTP client
/// and a directory to fetch a whole GGUF into when the node doesn't already hold
/// the model (the `#5a` fallback). The `#5b` path needs neither.
pub struct MeshRpcShardWarmer {
    http: reqwest::Client,
    /// Where a whole-GGUF fetch lands when the node lacks the model.
    fetch_dir: PathBuf,
}

impl MeshRpcShardWarmer {
    pub fn new() -> Self {
        let fetch_dir = std::env::var("SOVEREIGN_RPC_MODELS_DIR")
            .ok()
            .map(PathBuf::from)
            .or_else(|| {
                std::env::var("HOME")
                    .ok()
                    .map(|h| Path::new(&h).join(".sovereign").join("models"))
            })
            .unwrap_or_else(|| PathBuf::from(".sovereign/models"));
        // Short CONNECT timeout so an UNREACHABLE host base (e.g. a LAN IP the
        // host advertised that we can't route — WiFi client isolation) fails in
        // seconds and we fall through to the next base, instead of hanging on the
        // OS's multi-minute SYN-retry budget. The actual download has no timeout.
        let http = reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(10))
            .build()
            .unwrap_or_else(|_| reqwest::Client::new());
        Self { http, fetch_dir }
    }

    /// Resolve the GGUF to warm from for the whole-GGUF path: the local copy the
    /// route already found, else a previously-fetched copy, else fetch it from a
    /// host base. `#5b` (ByteRanges) never calls this.
    async fn resolve_whole_gguf(
        &self,
        model_id: &str,
        local_model_path: Option<PathBuf>,
        peer_bases: &[String],
    ) -> Result<PathBuf, String> {
        if let Some(p) = local_model_path {
            return Ok(p);
        }
        let already = self.fetch_dir.join(model_id);
        if already.is_file() {
            return Ok(already);
        }
        if peer_bases.is_empty() {
            return Err(format!(
                "node does not hold '{name}' and the warm request carried no host base to fetch from"
            ));
        }
        let mut last_err = "no host base reachable".to_string();
        for base in peer_bases {
            match crate::model_fetch::fetch_named_model_from_peer(
                &self.http,
                base,
                name,
                &self.fetch_dir,
                |_, _| {},
            )
            .await
            {
                Ok(p) => {
                    tracing::info!(model_id, base, "rpc-warm: fetched whole GGUF for warming");
                    return Ok(p);
                }
                Err(e) => {
                    last_err = format!("{base}: {e}");
                    tracing::warn!(base, error = %last_err, "rpc-warm: whole-GGUF fetch failed, trying next host base");
                }
            }
        }
        Err(format!("could not fetch '{model_id}': {last_err}"))
    }
}

impl Default for MeshRpcShardWarmer {
    fn default() -> Self {
        Self::new()
    }
}

/// Resolve the HOST's fetch bases through THIS node's own transport, given the
/// `host_node_id` hex the warm request carried. On an iroh-routed mesh the
/// raw-IP bases in the request may be unroutable from here (host on a
/// different network) — but the mesh transport already reaches the member as a
/// loopback bridge. Empty when the id is absent/unparseable (legacy host) or
/// the host isn't in our membership; the caller then uses raw bases alone.
async fn host_transport_bases(state: &AppState, host_node_id: Option<&str>) -> Vec<String> {
    let Some(id) = host_node_id.and_then(|h| commonwealth_core::ids::NodeId::from_hex(h)) else {
        return Vec::new();
    };
    let member = { state.inner.mesh.read().await.members.get(&id).cloned() };
    let Some(member) = member else {
        tracing::debug!(
            host = %id,
            "rpc-warm: host_node_id not in local membership; using raw bases only"
        );
        return Vec::new();
    };
    state
        .peer_transport()
        .endpoints(
            &commonwealth_transport::peer_contact(&member),
            commonwealth_transport::TrafficClass::ModelTransfer,
        )
        .await
        .into_iter()
        .map(|e| e.base_url)
        .collect()
}

/// Preferred-first merge without duplicates, order-preserving — transport
/// bases go ahead of the request's raw-IP bases, which stay as LAN fallback.
fn merge_bases(preferred: impl IntoIterator<Item = String>, rest: &[String]) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for b in preferred.into_iter().chain(rest.iter().cloned()) {
        if !out.contains(&b) {
            out.push(b);
        }
    }
    out
}

#[async_trait]
impl RpcShardWarmer for MeshRpcShardWarmer {
    async fn warm_shard(
        &self,
        request: serde_json::Value,
        local_model_path: Option<PathBuf>,
        state: AppState,
    ) -> Result<serde_json::Value, String> {
        let req: RpcWarmShardRequest =
            serde_json::from_value(request).map_err(|e| format!("malformed rpc-warm body: {e}"))?;
        let cache_dir = worker_cache_dir()?;
        std::fs::create_dir_all(&cache_dir).map_err(|e| format!("create cache dir: {e}"))?;

        let transport_bases = host_transport_bases(&state, req.host_node_id.as_deref()).await;

        tracing::info!(
            model_id = %req.model_id,
            device_index = req.device_index,
            mode = match &req.source { RpcWarmSource::WholeGguf { .. } => "whole_gguf", RpcWarmSource::ByteRanges { .. } => "byte_ranges" },
            transport_bases = transport_bases.len(),
            "rpc-warm: seeding this node's shard"
        );

        let resp = match &req.source {
            RpcWarmSource::ByteRanges {
                source_urls,
                tensors,
            } => {
                let urls = merge_bases(
                    transport_bases
                        .iter()
                        .map(|b| format!("{b}/internal/v1/models/file/{}", req.model_id)),
                    source_urls,
                );
                let stats = warm_cache_from_ranges(&self.http, &urls, tensors, &cache_dir).await?;
                RpcWarmShardResponse {
                    model_id: req.model_id.clone(),
                    device_index: req.device_index,
                    tensors_written: stats.written,
                    tensors_already_present: stats.already_present,
                    bytes_written: stats.bytes_written,
                }
            }
            RpcWarmSource::WholeGguf { peer_bases } => {
                let bases = merge_bases(transport_bases.iter().cloned(), peer_bases);
                let gguf = self
                    .resolve_whole_gguf(&req.model_id, local_model_path, &bases)
                    .await?;
                // `warm_cache_for_device` is synchronous file I/O — run it off the
                // reactor. It warms exactly this device's shard (its blocks + any
                // output head it owns), reading the same plan the host loads from.
                let plan = req.plan.clone();
                let device_index = req.device_index;
                let cache = cache_dir.clone();
                let stats = tokio::task::spawn_blocking(move || {
                    warm_cache_for_device(&gguf, &cache, &plan, device_index)
                })
                .await
                .map_err(|e| format!("warm task panicked: {e}"))?
                .map_err(|e| format!("warm: {e}"))?;
                RpcWarmShardResponse {
                    model_id: req.model_id.clone(),
                    device_index: req.device_index,
                    tensors_written: stats.written,
                    tensors_already_present: stats.already_present,
                    bytes_written: stats.bytes_written,
                }
            }
        };
        tracing::info!(
            model_id = %resp.model_id,
            device_index = resp.device_index,
            written = resp.tensors_written,
            already = resp.tensors_already_present,
            mb = resp.bytes_written / (1024 * 1024),
            "rpc-warm: shard warm complete"
        );
        serde_json::to_value(resp).map_err(|e| format!("serialize rpc-warm response: {e}"))
    }
}

// ─── Host side: the auto-warm orchestrator ───────────────────────────────────

/// Whether to ship each worker the whole GGUF (`#5a`) or only its tensors'
/// byte ranges (`#5b`). `SOVEREIGN_RPC_SHARD_FETCH=ranges` selects byte-range;
/// anything else (default) ships whole. Byte-range keeps each worker at
/// `O(model/N)` on disk but makes the host hash the whole GGUF to build the
/// manifest, so it's opt-in until a model can't fit one node's disk.
fn byte_range_mode() -> bool {
    std::env::var("SOVEREIGN_RPC_SHARD_FETCH")
        .map(|v| v.eq_ignore_ascii_case("ranges") || v.eq_ignore_ascii_case("byte_ranges"))
        .unwrap_or(false)
}

/// Install the host-side auto-warm orchestrator into `sovereign-inference`. Called
/// once at daemon startup (host role). During a distributing primary load,
/// `sovereign-inference` calls this with the plan; we fan the warm out to every
/// worker and block until all are warm — then the load proceeds with overrides.
///
/// Must be called from within the Tokio runtime (it captures the current
/// `Handle` to bridge the synchronous seam to async HTTP).
pub fn install_rpc_warm_orchestrator(daemon: Arc<EmbeddedDaemon>) {
    let handle = tokio::runtime::Handle::current();
    // Short CONNECT timeout so an unreachable worker fails in seconds (→ the host
    // falls back to local-only) rather than blocking the whole reload on the OS's
    // multi-minute SYN-retry budget. NO overall request timeout: a reachable
    // worker may legitimately take minutes (it fetches the GGUF before warming).
    let http = reqwest::Client::builder()
        .connect_timeout(std::time::Duration::from_secs(10))
        .build()
        .unwrap_or_else(|_| reqwest::Client::new());
    sovereign_inference::embedded::set_rpc_warm_orchestrator(move |plan: &RpcWarmPlan| {
        // The seam is synchronous and called from a blocking load thread; bridge
        // to async on the captured runtime handle.
        let owned = plan.clone();
        let daemon = Arc::clone(&daemon);
        let http = http.clone();
        handle.block_on(async move { orchestrate_warm(&daemon, &http, &owned).await })
    });
    tracing::info!("rpc-warm: auto-warm orchestrator installed (host role)");
}

/// Fan the warm request out to every worker in `plan.assignments` and wait for
/// all to report warm. Any failure → `Err` (the caller falls back to a local-only
/// load — never wedge). Glassbox: logs per-worker outcome.
async fn orchestrate_warm(
    daemon: &EmbeddedDaemon,
    http: &reqwest::Client,
    plan: &RpcWarmPlan,
) -> Result<(), String> {
    let model_id = plan
        .model_path
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| "model path has no file name".to_string())?
        .to_string();

    let (_client_port, internal_port) = daemon.resolved_ports().await;
    // The host's own reachable bases on the internal port — where workers fetch
    // the GGUF (or its ranges) back from.
    let host_bases: Vec<String> = crate::mesh_discovery::reachable_addresses(internal_port)
        .into_iter()
        .map(|a| format!("http://{a}"))
        .collect();
    if host_bases.is_empty() {
        return Err("host has no reachable internal-port address to serve the model from".into());
    }

    // For byte-range mode, build the manifest ONCE (hashes the whole GGUF) so each
    // worker can be handed exactly its tensors. Whole-GGUF mode skips this — the
    // workers hash their own shards in parallel.
    let manifest = if byte_range_mode() {
        let path = plan.model_path.clone();
        Some(
            tokio::task::spawn_blocking(move || build_manifest(&path))
                .await
                .map_err(|e| format!("manifest task panicked: {e}"))?
                .map_err(|e| format!("build manifest: {e}"))?,
        )
    } else {
        None
    };

    tracing::info!(
        model_id = %model_id,
        workers = plan.assignments.len(),
        mode = if manifest.is_some() { "byte_ranges" } else { "whole_gguf" },
        "rpc-warm orchestrator: seeding worker shards before distributed load"
    );

    // Host identity for the request: a worker that knows WHO we are resolves
    // its fetch bases back to us through ITS transport (iroh bridge), instead
    // of trusting the raw-IP bases alone.
    let host_node_id = daemon.self_node_id().await.map(|id| id.to_hex());

    let mut tasks = Vec::with_capacity(plan.assignments.len());
    for assignment in &plan.assignments {
        // Worker IP from its RPC endpoint (`ip:rpc_port`); its internal HTTP port
        // is assumed to match ours (the same assumption discovery already makes
        // for the client port).
        let worker_ip = assignment
            .endpoint
            .rsplit_once(':')
            .map(|(host, _)| host.to_string())
            .unwrap_or_else(|| assignment.endpoint.clone());

        // Warm-POST candidates, best first. When discovery recorded which mesh
        // member owns this endpoint, ask the transport for `ModelTransfer`
        // candidates — on an iroh-routed mesh the first is a loopback bridge
        // that tunnels to the peer (raw `:9742` is NOT reachable there; this
        // was the `auto-warm failed … Connection refused` blocker). The
        // hand-built raw URL stays as the final fallback and is the only
        // candidate for env-configured workers (no directory entry).
        let worker_node = daemon.rpc_endpoint_node(&assignment.endpoint);
        let mut candidates: Vec<(String, String, Option<commonwealth_transport::PeerEndpoint>)> =
            Vec::new();
        if let Some(node) = worker_node {
            for ep in daemon.model_transfer_endpoints(node).await {
                candidates.push((
                    format!("{}/internal/rpc-warm", ep.base_url),
                    ep.label.clone(),
                    Some(ep),
                ));
            }
        }
        if raw_warm_fallback_allowed(&worker_ip) {
            let raw_url = format!("http://{worker_ip}:{internal_port}/internal/rpc-warm");
            if !candidates.iter().any(|(u, _, _)| *u == raw_url) {
                candidates.push((
                    raw_url,
                    format!("raw:{worker_ip}:{internal_port}"),
                    None,
                ));
            }
        }

        // Hand THIS worker the bases it's most likely to reach first — its own
        // network before a shared-but-unroutable LAN (see order_host_bases). The
        // worker still tries them all, but the reachable one is first so it
        // doesn't burn its connect budget on a dead LAN IP.
        let ordered_bases = order_host_bases(&host_bases, worker_ip.parse().ok());

        let source = match &manifest {
            Some(m) => {
                let tensors: Vec<TensorRange> = m
                    .iter()
                    .filter(|e| {
                        e.cacheable
                            && tensor_device(&e.name, e.layer, &plan.plan)
                                == Some(assignment.device_index)
                    })
                    .map(|e| TensorRange {
                        gguf_offset: e.gguf_offset,
                        nbytes: e.nbytes,
                        hash: e.hash,
                    })
                    .collect();
                // A placed worker with ZERO cacheable tensors is a manifest
                // gap, not a warm — e.g. a split GGUF where build_manifest
                // read only the header shard (found live 2026-07-19: the
                // "warm" reported success with written=0 already=0 and the
                // load bulk-streamed 22GB into the upload deadlock). Fail
                // the warm so the caller falls back local-only. Never wedge.
                if tensors.is_empty() {
                    return Err(format!(
                        "worker {} (device {}) has 0 cacheable tensors in the manifest \
                         but is assigned blocks — manifest gap (split GGUF?); refusing \
                         an empty warm that would bulk-stream at load time",
                        assignment.endpoint, assignment.device_index
                    ));
                }
                let source_urls = ordered_bases
                    .iter()
                    .map(|b| format!("{b}/internal/v1/models/file/{model_id}"))
                    .collect();
                RpcWarmSource::ByteRanges {
                    source_urls,
                    tensors,
                }
            }
            None => RpcWarmSource::WholeGguf {
                peer_bases: ordered_bases,
            },
        };

        let body = RpcWarmShardRequest {
            model_id: model_id.clone(),
            device_index: assignment.device_index,
            plan: plan.plan.clone(),
            source,
            host_node_id: host_node_id.clone(),
        };
        let http = http.clone();
        let endpoint = assignment.endpoint.clone();
        tasks.push(async move {
            let label = format!("{endpoint} (device {})", body.device_index);
            // Try candidates in order; first success wins. Glassbox: every
            // attempt logs WHICH path (`via`) carried or failed it, so "which
            // transport actually warmed this worker?" is answerable from logs.
            let mut last_err = format!("{label}: no warm-POST candidate");
            for (url, via, ep) in &candidates {
                match http.post(url).json(&body).send().await {
                    Ok(r) if r.status().is_success() => {
                        let stats = r.json::<RpcWarmShardResponse>().await.unwrap_or_default();
                        tracing::info!(
                            worker = %label,
                            via = %via,
                            written = stats.tensors_written,
                            already = stats.tensors_already_present,
                            "rpc-warm: worker shard warm"
                        );
                        if let (Some(node), Some(ep)) = (worker_node, ep.as_ref()) {
                            daemon.note_model_transfer_success(node, ep).await;
                        }
                        return Ok(());
                    }
                    Ok(r) => {
                        let status = r.status();
                        let detail = r.text().await.unwrap_or_default();
                        last_err = format!("{label} via {via}: warm returned {status}: {detail}");
                        tracing::warn!(worker = %label, via = %via, status = %status, "rpc-warm: candidate answered with an error; trying next");
                    }
                    Err(e) => {
                        last_err =
                            format!("{label} via {via}: warm request failed: {}", error_chain(&e));
                        tracing::warn!(worker = %label, via = %via, "rpc-warm: candidate unreachable; trying next");
                    }
                }
            }
            Err(last_err)
        });
    }

    // All workers must warm before the load proceeds.
    let results = futures::future::join_all(tasks).await;
    let failures: Vec<String> = results.into_iter().filter_map(Result::err).collect();
    if failures.is_empty() {
        tracing::info!(model_id = %model_id, "rpc-warm orchestrator: all worker shards warm");
        Ok(())
    } else {
        Err(format!(
            "{} of {} worker(s) failed to warm: {}",
            failures.len(),
            plan.assignments.len(),
            failures.join("; ")
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::routing::get;
    use axum::Router;
    use std::net::SocketAddr;
    use tokio::net::TcpListener;

    /// Serve a fixed byte buffer with `Range` support, mirroring the production
    /// `serve_model_file` 206 path — enough to prove the warmer's round-trip
    /// without dragging in commonwealth-api (a circular dep for this crate).
    async fn spawn_range_server(data: Vec<u8>) -> (String, tokio::task::JoinHandle<()>) {
        let data = Arc::new(data);
        let handler = move |headers: axum::http::HeaderMap| {
            let data = Arc::clone(&data);
            async move {
                let size = data.len() as u64;
                if let Some((s, e)) = headers
                    .get(axum::http::header::RANGE)
                    .and_then(|v| v.to_str().ok())
                    .and_then(|h| {
                        let spec = h.trim().strip_prefix("bytes=")?;
                        let (a, b) = spec.split_once('-')?;
                        Some((a.parse::<u64>().ok()?, b.parse::<u64>().ok()?))
                    })
                {
                    let slice = data[s as usize..=(e as usize)].to_vec();
                    return (
                        axum::http::StatusCode::PARTIAL_CONTENT,
                        [(
                            axum::http::header::CONTENT_RANGE,
                            format!("bytes {s}-{e}/{size}"),
                        )],
                        slice,
                    )
                        .into_response();
                }
                (axum::http::StatusCode::OK, (*data).clone()).into_response()
            }
        };
        use axum::response::IntoResponse;
        let app = Router::new().route("/internal/v1/models/file/m.gguf", get(handler));
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr: SocketAddr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            axum::serve(listener, app).await.unwrap();
        });
        (
            format!("http://{addr}/internal/v1/models/file/m.gguf"),
            server,
        )
    }

    #[tokio::test]
    async fn warm_from_ranges_writes_hash_named_cache_files() {
        // A fake "GGUF": two distinct tensor regions in one buffer.
        let mut data = vec![0u8; 4096];
        for (i, b) in data.iter_mut().enumerate() {
            *b = (i % 251) as u8;
        }
        let (url, server) = spawn_range_server(data.clone()).await;

        // Two tensors at known offsets; compute their true FNV hashes.
        let mk = |off: usize, len: usize| {
            let mut h = Fnv1a::new();
            h.update(&data[off..off + len]);
            TensorRange {
                gguf_offset: off as u64,
                nbytes: len as u64,
                hash: h.finish(),
            }
        };
        let tensors = vec![mk(0, 1000), mk(1000, 2000)];

        let cache = tempfile::tempdir().unwrap();
        let http = reqwest::Client::new();
        let stats = warm_cache_from_ranges(&http, &[url.clone()], &tensors, cache.path())
            .await
            .expect("warm");
        assert_eq!(stats.written, 2);
        assert_eq!(stats.bytes_written, 3000);

        // Each cache file is named by its hash and holds the exact bytes.
        for t in &tensors {
            let f = cache.path().join(cache_file_name(t.hash));
            let got = std::fs::read(&f).unwrap();
            assert_eq!(got.len() as u64, t.nbytes);
            assert_eq!(
                &got[..],
                &data[t.gguf_offset as usize..(t.gguf_offset + t.nbytes) as usize]
            );
        }

        // Idempotent: a second run writes nothing new.
        let again = warm_cache_from_ranges(&http, &[url], &tensors, cache.path())
            .await
            .unwrap();
        assert_eq!(again.written, 0);
        assert_eq!(again.already_present, 2);

        server.abort();
    }

    #[tokio::test]
    async fn warm_from_ranges_rejects_a_hash_mismatch() {
        let data = vec![7u8; 2048];
        let (url, server) = spawn_range_server(data).await;
        // A tensor claiming a hash the bytes don't produce → must refuse (else the
        // host's SET_TENSOR_HASH would miss and stream → deadlock).
        let bad = vec![TensorRange {
            gguf_offset: 0,
            nbytes: 1000,
            hash: 0xdead_beef_dead_beef,
        }];
        let cache = tempfile::tempdir().unwrap();
        let http = reqwest::Client::new();
        let err = warm_cache_from_ranges(&http, &[url], &bad, cache.path())
            .await
            .unwrap_err();
        assert!(err.contains("hash mismatch"), "got: {err}");
        // No cache file left behind.
        assert_eq!(std::fs::read_dir(cache.path()).unwrap().count(), 0);
        server.abort();
    }

    #[test]
    fn request_round_trips_through_json() {
        let req = RpcWarmShardRequest {
            model_id: "m.gguf".into(),
            device_index: 1,
            plan: Vec::new(),
            source: RpcWarmSource::ByteRanges {
                source_urls: vec!["http://h/internal/v1/models/file/m.gguf".into()],
                tensors: vec![TensorRange {
                    gguf_offset: 10,
                    nbytes: 20,
                    hash: 30,
                }],
            },
            host_node_id: Some("0123456789abcdef0123456789abcdef".into()),
        };
        let v = serde_json::to_value(&req).unwrap();
        // The opaque-JSON seam in commonwealth-api reads `model_id` for path
        // resolution — it must be a top-level string.
        assert_eq!(v.get("model_id").and_then(|x| x.as_str()), Some("m.gguf"));
        let back: RpcWarmShardRequest = serde_json::from_value(v).unwrap();
        assert_eq!(back.device_index, 1);
        assert_eq!(
            back.host_node_id.as_deref(),
            Some("0123456789abcdef0123456789abcdef")
        );
        matches!(back.source, RpcWarmSource::ByteRanges { .. });
    }

    #[test]
    fn old_wire_body_without_host_node_id_still_parses() {
        // A pre-identity host omits the field entirely — a rolling-upgrade
        // worker must not reject the body.
        let v = serde_json::json!({
            "model_id": "m.gguf",
            "device_index": 0,
            "plan": [],
            "source": { "mode": "whole_gguf", "peer_bases": ["http://10.0.0.1:9742"] }
        });
        let req: RpcWarmShardRequest = serde_json::from_value(v).unwrap();
        assert_eq!(req.host_node_id, None);
    }

    #[test]
    fn raw_fallback_refused_for_loopback_worker() {
        // A loopback worker_ip means a bridge-local endpoint (task 6): the
        // hand-built raw URL would target OURSELF, and a self-warm reports
        // success while the real worker stays cold → upload deadlock.
        assert!(!raw_warm_fallback_allowed("127.0.0.1"));
        assert!(!raw_warm_fallback_allowed("::1"));
        // Real remote IPs and unparseable hostnames keep the legacy fallback.
        assert!(raw_warm_fallback_allowed("192.168.1.2"));
        assert!(raw_warm_fallback_allowed("100.104.36.28"));
        assert!(raw_warm_fallback_allowed("beefymac.local"));
    }

    #[test]
    fn merge_bases_prefers_transport_and_dedups() {
        let raw = vec![
            "http://192.168.1.19:9742".to_string(),
            "http://127.0.0.1:60001".to_string(),
        ];
        // The transport bridge duplicates one raw entry — it must lead the
        // merged order, appearing exactly once, with the rest behind it.
        let merged = merge_bases(["http://127.0.0.1:60001".to_string()], &raw);
        assert_eq!(
            merged,
            vec![
                "http://127.0.0.1:60001".to_string(),
                "http://192.168.1.19:9742".to_string(),
            ]
        );
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Daemon-backed Runtime bootstrap for `svrn chat`.
//!
//! Mirrors `sovereign-desktop::state::bootstrap` — same StateStore,
//! CorpusEngine, tools, mesh-knowledge wiring — but the
//! `InferenceProvider` is a `SplitInferenceProvider` that delegates
//! chat completions to the daemon's chat model and embeddings to the
//! daemon's embed model over HTTP. No embedded llama.cpp, no Tauri.
//!
//! Rationale
//! ---------
//! The desktop's Attach mode is the architectural template we want:
//! "the daemon already owns the model, talk to it over HTTP". The
//! desktop currently still loads local weights even in Attach mode
//! (historical quirk); this CLI does what Attach *should* do — pure
//! HTTP.
//!
//! The split-provider dance is required because `RemoteApiProvider`
//! uses a single `model_id` for both `/chat/completions` AND
//! `/embeddings`. Sending a chat model to the embeddings endpoint
//! returns non-embedding shapes (or errors). We keep two instances
//! and route by method.

use std::path::PathBuf;
use std::sync::Arc;
use std::time::Duration;

use async_trait::async_trait;

use sovereign_core::error::{Error, Result};
use sovereign_core::planner::LlmPlanner;
use sovereign_core::runtime::Runtime;
use sovereign_core::traits::{ApprovalChannel, InferenceProvider, StateStore};
use sovereign_core::types::*;
use sovereign_core::{SkillRegistry, ToolRegistry};
// Re-exported (not just `use`d) so the other CLI modules that referenced the
// formerly-local `chat_cmd::bootstrap::SplitInferenceProvider` (raptor,
// recipe_cmd) keep resolving after it was promoted to sovereign-inference.
pub use sovereign_inference::remote::SplitInferenceProvider;
use sovereign_store::sqlite::SqliteStateStore;
use sovereign_tools::shell::ShellTool;

use crate::chat_cmd::config::ChatGlobals;

/// Bundle of everything the chat subcommands need from bootstrap.
/// Carries `Arc<Runtime>` plus the handles required to persist turns
/// (the store) and browse prior conversations.
pub struct ChatSession {
    pub runtime: Arc<Runtime>,
    pub store: Arc<dyn StateStore>,
    pub corpus_engine: Arc<corpus_engine::CorpusEngine>,
    pub inference: Arc<dyn InferenceProvider>,
    pub daemon_base: String,
    /// Resolved embed model id (e.g. `Qwen3-Embedding-0.6B-Q8_0`).
    /// Surfaced so cache layers (atlas embeddings, future per-corpus
    /// vector caches) can key on the active model and invalidate when
    /// the operator swaps it.
    pub embed_model: String,
    /// The per-process atlas-grounding manager (the same Arc installed
    /// on `runtime` as its `AtlasContextProvider`). Exposed so a
    /// measurement harness can `warm_one(corpus)` its sealed corpus —
    /// `build_session` only loads already-cached atlases
    /// (`init_from_cache`), so a freshly-enriched corpus contributes 0
    /// contexts until something warms it. Warming this Arc is visible to
    /// `runtime` because they share it.
    pub atlas_mgr: Arc<sovereign_tools::atlas_context_manager::AtlasContextManager>,
}

/// Build a `Runtime` backed by the daemon over HTTP.
///
/// Fails fast if the daemon isn't answering — there's no recovery
/// path a retry could fix, and a partially-initialized Runtime
/// pointing at a dead endpoint would produce confusing errors deep
/// in retrieval. The caller should exit with a hint.
pub async fn build_session(globals: &ChatGlobals) -> Result<ChatSession> {
    build_session_with_skills(globals, SkillRegistry::new()).await
}

/// Build a daemon-backed `ChatSession` with a caller-supplied
/// `SkillRegistry`. The default `build_session` passes an empty
/// registry — chat-as-chat doesn't need skills loaded. The Tier-B
/// voice eval harness (`svrn voice eval`) supplies a registry
/// pre-populated with the relational skills (inner-work,
/// personal-assistant) and pre-activates the per-scenario one so
/// the runtime's `primary_skill_register()` resolves to
/// `Relational` and the witness-voice contract gets prepended.
pub async fn build_session_with_skills(
    globals: &ChatGlobals,
    skills: SkillRegistry,
) -> Result<ChatSession> {
    // 1. Probe the daemon before we touch anything else. A fast fail
    //    here prints a clean "start the daemon" message instead of
    //    the cryptic timeout from the first real request.
    let base = globals.daemon_base.clone();
    let v1 = format!("{base}/v1");
    probe_or_bail(&base).await?;

    // 2. Resolve model IDs. Preference order:
    //       a) explicit `--chat-model` / `--embed-model` flag,
    //       b) the daemon's `SetupConfig.models.*` filename stems
    //          — this is what the daemon actually loaded, and the
    //          daemon advertises those IDs on `/v1/models`,
    //       c) fallback: probe `/v1/models` and pick the first
    //          chat- and first embed-shaped entries.
    //    The historical (c)-only path picked non-deterministically
    //    between a locally-loaded `qwen-embedding-0.6b` (1024-dim)
    //    and a mesh-peer-advertised `Qwen3-Embedding-0.6B-Q8_0`
    //    whose dimensionality didn't match any installed corpus —
    //    silently downgrading every retrieval to FTS-only. Reading
    //    the config directly removes that race.
    let (chat_model, embed_model) = resolve_model_ids(&v1, globals).await?;
    eprintln!("Daemon: {base}");
    eprintln!("Chat model:  {chat_model}");
    eprintln!("Embed model: {embed_model}");

    // B:P9a — prefer the daemon's own OICP capabilities manifest for the chat
    // slot's context window (v0.4 §7) and the embed slot's query-instruction
    // prefix (§4), so `Runtime`'s budget-aware compaction sees the host's REAL
    // window (e.g. 32768) instead of the historical 8192 approximation. On a
    // v0.3 host that doesn't serve `/oicp/v1/capabilities`, fall back to 8192 +
    // the `DEFAULT_MANIFEST`-derived prefix (the prior behavior, bit-identical).
    let inference: Arc<dyn InferenceProvider> = Arc::new(
        match sovereign_inference::remote::fetch_manifest(&base, None).await {
            Some(manifest) => SplitInferenceProvider::from_manifest(
                &v1,
                &manifest,
                chat_model,
                embed_model.clone(),
            ),
            None => SplitInferenceProvider::new(
                &v1,
                chat_model,
                embed_model.clone(),
                8192,
                sovereign_core::models_manifest::DEFAULT_MANIFEST
                    .embed_query_instruction(&embed_model),
            ),
        },
    );

    // 3. Open the state store. Creating the data dir on the fly is
    //    safe — mirrors the desktop's behaviour and means a first
    //    `svrn chat` against a fresh home directory doesn't
    //    stumble on a missing folder.
    std::fs::create_dir_all(&globals.data_dir)
        .map_err(|e| Error::Serialization(format!("create {:?}: {e}", globals.data_dir)))?;
    let db_path = globals.data_dir.join("sovereign.db");
    eprintln!("Database:    {}", db_path.display());
    let store_concrete = Arc::new(
        SqliteStateStore::open(&db_path)
            .map_err(|e| Error::Serialization(format!("open db {:?}: {e}", db_path)))?,
    );
    let store: Arc<dyn StateStore> = store_concrete.clone();

    // 4. Build the CorpusEngine. The desktop (`state.rs:706-707`) and
    //    the legacy REPL (`main.rs:477-478`) both hardcode
    //    `~/.sovereign/{recipes,indexes}` regardless of
    //    `config.data.dir` — that field governs the state DB only,
    //    not corpus storage. Matching that convention means this CLI
    //    sees the same corpora the desktop just ingested.
    //
    //    If a user passed `--data-dir` explicitly they almost
    //    certainly meant to override BOTH paths; honour that by
    //    using `<data_dir>/indexes` when `--data-dir` was given.
    //    Otherwise stick to the hardcoded well-known path.
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("."));
    let dotsovereign = home.join(".sovereign");
    let (recipes_dir, indexes_dir): (PathBuf, PathBuf) = if globals.data_dir_explicit {
        (
            globals.data_dir.join("recipes"),
            globals.data_dir.join("indexes"),
        )
    } else {
        (dotsovereign.join("recipes"), dotsovereign.join("indexes"))
    };
    eprintln!("Indexes:     {}", indexes_dir.display());
    let embed_fn = sovereign_tools::corpus::inference_to_embed_fn(Arc::clone(&inference));
    let inference_fn = sovereign_tools::corpus::inference_to_inference_fn(Arc::clone(&inference));
    // The engine's `expected_embedding_model` flows into
    // `_corpus_meta.json` at ingest time and into shard-consistency
    // checks. The CLI doesn't ingest during chat, but if any tool
    // path later triggers an ingest (e.g. watcher-driven reindex
    // through the same engine), it must match what the desktop
    // would have written. We've already resolved `embed_model` from
    // SetupConfig above.
    let corpus_engine = Arc::new(
        corpus_engine::CorpusEngine::new(recipes_dir, indexes_dir.clone(), embed_fn)
            .with_embedding_model(&embed_model)
            .with_inference_fn(inference_fn),
    );
    log_installed_corpora(&corpus_engine).await;

    // 5. Skills — empty registry is fine for chat; the runtime uses
    //    them to prefix system prompts with skill descriptors, and
    //    the chat flow is identical under "no active skill".
    let skills = Arc::new(skills);

    // 6. Tools. Keep this list identical to the desktop bootstrap so
    //    the retrieval + tool-use path exercised here matches what
    //    the user sees in the GUI. Notably: `SearchTool::with_web`
    //    drives the "Searched ... web" sources in provenance.
    // Tier 4 — shared tool-result cache. Same shape as the
    // desktop bootstrap: per-conversation cache slices, 5-turn
    // TTL. Idempotent tools (knowledge_lookup, code-intel reads)
    // hit the cache when the model re-calls with the same args
    // within the window.
    let tool_cache = Arc::new(sovereign_core::tool_result_cache::ToolResultCache::new());
    let mut tools = ToolRegistry::new().with_cache(Arc::clone(&tool_cache));
    tools.register(Box::new(ShellTool));
    tools.register(Box::new(sovereign_tools::document::DocumentTool::new(
        Arc::clone(&store),
        Arc::clone(&inference),
    )));
    tools.register(Box::new(sovereign_tools::ClaimSearchTool::new(Arc::clone(
        &corpus_engine,
    ))));
    tools.register(Box::new(sovereign_tools::EpistemicLandscapeTool::new(
        Arc::clone(&corpus_engine),
    )));
    // Deterministic land-value-tax analytics over parcel corpora
    // (e.g. sf-assessor-roll) — pre-cited figures the ComplexTask
    // synthesizer quotes verbatim ("no confabulated numbers").
    tools.register(Box::new(
        sovereign_tools::parcel_analytics::ParcelAnalyticsTool::new(Arc::clone(&corpus_engine)),
    ));
    // Code-intelligence tools previously registered here against an
    // in-memory stub ScipGraph. Dropped 2026-05-22 along with the
    // REPL's treesitter dep — real SCIP queries go through
    // `svrn daemon` (sovereign-cli-atos), which builds the
    // merged graph from ~/.sovereign/indexes/*/scip_graph.db.
    tools.register(Box::new(sovereign_tools::search::SearchTool::with_web(
        Arc::clone(&store),
        Arc::clone(&inference),
        // DuckDuckGo — free, no key required. Matches the no-API-key
        // fallback in main.rs for parity with the legacy REPL.
        sovereign_tools::web::search::SearchBackend::DuckDuckGo,
    )));
    // Unified knowledge-lookup front door (Tool-Mastery framework
    // Phase 5). Returns a single Evidence envelope across corpus
    // + memory + note channels. The plan migrates skills onto
    // this tool as a follow-up PR; for now it coexists with
    // `search` / `knowledge` / `claim_search`. Note: the
    // NoteStore handle is wired later (after Runtime build); we
    // register the tool here and re-register with notes once we
    // have the store. For now, register without notes — the
    // single-turn knowledge-gym mocks the tool client-side so
    // production daemon-side notes channel isn't load-bearing
    // for the gym, and the threads bench doesn't drive
    // knowledge_lookup directly anyway.
    tools.register(Box::new(sovereign_tools::KnowledgeLookupTool::new(
        Arc::clone(&store),
        Arc::clone(&inference),
    )));
    tools.register(Box::new(sovereign_tools::web::WebFetchTool::new()));
    tools.register(Box::new(sovereign_tools::WikipediaFetchTool::new(
        Arc::clone(&corpus_engine),
    )));
    // `attached_doc_search` is registered unconditionally; the
    // execute() path returns a clear "no document attached" payload
    // on conversations without a DocumentSession, so the model can
    // probe it harmlessly. When a doc IS attached, the runtime's
    // ReasonWithTools loop can call it directly — that's the lever
    // the book-report bench exposed as missing (sovereign decision
    // 7693f16b: attached docs as Tool, not parallel pipeline).
    tools.register(Box::new(sovereign_tools::AttachedDocumentSearchTool::new(
        Arc::clone(&store),
        Arc::clone(&inference),
    )));

    // External MCP servers (the `[[mcp_servers]]` array of the canonical
    // config): connect over HTTP and register their tools into the SAME
    // registry the agent plans against, so a server added via `svrn mcp
    // add` or the desktop settings pane is callable here too. One shared
    // loader, every surface — parity with the router stack below. The manager
    // is held only for connection statuses (logged); the live transports are
    // owned by the registered tools in the registry.
    let mcp = sovereign_tools::mcp::load_from_setup_config(&mut tools).await;
    for st in mcp.server_statuses().await {
        if st.connected {
            eprintln!("MCP:         {} ({} tools)", st.name, st.tool_count);
        } else if let Some(e) = &st.error {
            eprintln!("MCP:         {} unavailable — {e}", st.name);
        }
    }

    eprintln!("Tools:       {} registered", tools.count());

    // 7. Router + planner. The legacy REPL defaults to
    //    `PassthroughRouter`; the desktop uses LLM-based routing.
    //    Use the LLM router here so the chat flow is bit-for-bit
    //    identical to the desktop surface — the point of the CLI is
    //    to reproduce that flow, not a simplified version.
    //
    //    Embed-router pre-check: when the exemplar TOML is reachable
    //    (default `sovereign/router/exemplars.toml` or
    //    `$SOVEREIGN_ROUTER_EXEMPLARS`), load it and pre-embed every
    //    exemplar. Subsequent routing decisions consult the embed
    //    classifier before the heuristic + LLM cascade. Falls through
    //    to the legacy stack on load failure or low-confidence
    //    classifications.
    // Router classifier stack — built through the shared `router_bootstrap`
    // helper so the CLI/bench, desktop, and served daemon all wire the SAME
    // classifiers (parity by construction; see sovereign-core/router_bootstrap.rs).
    // `from_env_and_repo` keeps the `$SOVEREIGN_*` overlay + repo-relative
    // exemplars for dev tuning; a packaged build falls through to the baked set.
    let (llm_router, router_report) = sovereign_core::router_bootstrap::build_llm_router(
        Arc::clone(&inference),
        Arc::clone(&store),
        Arc::clone(&skills),
        &sovereign_core::router_bootstrap::ExemplarOverrides::from_env_and_repo(),
        || eprintln!(
            "Router: exemplar embed cache cold — re-embedding exemplars (can take minutes on a CPU-only embed slot)…"
        ),
    )
    .await;
    eprintln!(
        "Router classifier stack: embed={} scope={} effort={} current_info={}",
        router_report.embed_router.is_some(),
        router_report.scope.is_some(),
        router_report.effort.is_some(),
        router_report.current_info.is_some(),
    );
    let router: Box<dyn sovereign_core::traits::Router> = Box::new(llm_router);
    let planner = LlmPlanner::new(Arc::clone(&inference), Arc::clone(&skills));

    // 8. Approval channel. Chat turns don't trigger confirmations
    //    in the normal path; we wire a yes-only stub so any stray
    //    approval request is auto-granted rather than deadlocking a
    //    one-shot CLI.
    let approval: Arc<dyn ApprovalChannel> = Arc::new(AutoApprove);

    // 9. Mesh knowledge client. Talks to the daemon's `/v1/mesh` —
    //    when no mesh is running, reqwest gets ECONNREFUSED on the
    //    first call and the Runtime falls through to local-only
    //    retrieval. Safe to install unconditionally (same policy as
    //    the desktop).
    let mesh_knowledge: Option<Arc<dyn sovereign_core::traits::MeshKnowledgeSource>> =
        match sovereign_mesh::knowledge_client::MeshKnowledgeClient::new(&base) {
            Ok(c) => Some(Arc::new(c)),
            Err(_) => None,
        };

    // 10. Runtime. Only the fields we need — routing events stay at
    //     the no-op default (the CLI has no UI to emit to), and
    //     landscape-digest / KnowledgeView is intentionally omitted
    //     (desktop feature, not load-bearing for chat correctness).
    let mut inference_config = InferenceConfig::default();
    if let Some(t) = globals.temperature {
        inference_config.temperature = t;
        eprintln!("Temperature: {t} (override)");
    }
    if let Some(n) = globals.max_tokens {
        inference_config.max_tokens = n;
        eprintln!("Max tokens: {n} (override)");
    }
    // Session-level answering discipline (general persona layer). `govern
    // ask` sets this to its governance answering rules; ordinary chat
    // leaves it None (byte-identical prompt to before).
    if globals.custom_instructions.is_some() {
        inference_config.custom_instructions = globals.custom_instructions.clone();
    }
    // Tool-Mastery Layer 3 — NoteStore for the per-conversation
    // tool_decision write hook (runtime.rs handle_message_stream's
    // post-gap-check spawn). Same path the daemon uses
    // (`daemon_cmd.rs::build_tool_registry` → `data_dir.join("notes.db")`)
    // so the chat REPL and bench surfaces share one outcome log.
    let notes_path = globals.data_dir.join("notes.db");
    let notes_store = match corpus_engine_notes::NoteStore::open(&notes_path) {
        Ok(s) => Some(Arc::new(s)),
        Err(e) => {
            eprintln!(
                "warn: NoteStore open failed at {} ({e}); tool-decision \
                 writes will no-op this session",
                notes_path.display()
            );
            None
        }
    };

    let mut runtime = Runtime::new(
        Arc::clone(&inference),
        router,
        Box::new(planner),
        Arc::new(tools),
        Arc::clone(&store),
        skills,
        approval,
        inference_config,
    )
    .with_corpus_engine(Arc::clone(&corpus_engine));
    if let Some(ns) = notes_store.as_ref() {
        runtime = runtime.with_note_store(Arc::clone(ns));
    }
    // Conv-tiered briefing reader — same SqliteStateStore handle
    // already opened above also impls ConvTieredReader. Spec
    // `sovereign/docs/specs/CONV_TIERED_PORT.md`.
    runtime = runtime.with_conv_tiered_reader(
        Arc::clone(&store_concrete) as Arc<dyn sovereign_store::sqlite::ConvTieredReader>
    );
    if let Some(m) = mesh_knowledge {
        runtime = runtime.with_mesh_knowledge(m);
    }
    // GLiNER entity extractor for entity-aware retrieval-over-history
    // (`Runtime::maybe_retrieve_relevant_history`). Best-effort: probe
    // the default model id; if installed, load it and wire it onto
    // the Runtime. Failures soft-fall-through to pure cosine + MMR
    // — the bench/chat path keeps working without GLiNER.
    {
        let model_id = sovereign_gliner::gliner_ner::DEFAULT_MODEL_ID;
        if sovereign_gliner::gliner_ner::probe_model_available(model_id) {
            match sovereign_tools::gliner_ner::GlinerExtractor::new_default() {
                Ok(g) => {
                    let arc: Arc<dyn sovereign_core::traits::EntityExtractor> = Arc::new(g);
                    runtime = runtime.with_gliner(arc);
                    tracing::info!(
                        model = model_id,
                        "bootstrap: GLiNER entity extractor loaded"
                    );
                }
                Err(e) => {
                    tracing::warn!(error = %e, "bootstrap: GLiNER probe ok but load failed; entity-aware retrieval disabled");
                }
            }
        } else {
            tracing::debug!(
                model = model_id,
                "bootstrap: GLiNER model not installed; entity-aware retrieval disabled (falls back to cosine+MMR)"
            );
        }
    }
    // Atlas Layer 0: load any installed Wikipedia link graph. Probes
    // `<indexes_dir>/<corpus>/wikipedia_graph.db` for each installed
    // corpus and, on the first hit, wires it into the Runtime. Today
    // we expect at most one Wikipedia-class corpus per install — if
    // a future build needs multiple, switch this to a registry of
    // (corpus_id, Arc<WikipediaGraph>).
    if let Some(graph) = load_wikipedia_graph(&corpus_engine, &indexes_dir).await {
        eprintln!(
            "Wiki graph:  {} articles, {} edges",
            graph.article_count().await,
            graph.edge_count().await,
        );
        runtime = runtime.with_wikipedia_graph(graph);
    }

    // Atlas-grounded retrieval: build the per-process atlas context
    // manager, attach it to the Runtime, then synchronously load
    // every atlas whose embeddings are already cached on disk.
    // Cold-start embed work (uncached atlases) is intentionally NOT
    // done here — that belongs in the post-install hook so the
    // first user query has a deterministic latency and isn't gated
    // by a 40-min wiki-scale embed pass.
    let atlas_mgr = Arc::new(
        sovereign_tools::atlas_context_manager::AtlasContextManager::new(
            indexes_dir.clone(),
            Arc::clone(&inference),
            embed_model.clone(),
        ),
    );
    runtime =
        runtime
            .with_atlas_context_provider(Arc::clone(&atlas_mgr)
                as Arc<dyn sovereign_core::atlas_context::AtlasContextProvider>);
    atlas_mgr.init_from_cache().await;
    eprintln!(
        "Atlas: {} corpus context(s) loaded from cache",
        sovereign_core::atlas_context::AtlasContextProvider::loaded_corpus_ids(atlas_mgr.as_ref())
            .len()
    );
    // Adaptive triage (Phase B2): start the bump-flusher background
    // task so query-time hits eventually land on disk and feed the
    // next triage rebuild. 30s interval — losing up to half a
    // minute of bumps on a hard kill is acceptable for a statistical
    // signal.
    let _bump_flusher = Arc::clone(&atlas_mgr).spawn_bump_flusher(30);

    // Cross-corpus meta-atlas (Move 5). Loads
    // `~/.sovereign/meta-atlas/canonical_atoms.json` produced by
    // `svrn meta-atlas build`. Empty / absent file → boost is a
    // no-op and retrieval falls back to cosine + existing
    // entity-boost. Operator can rebuild with the CLI; we don't auto-
    // build at chat boot (cost is non-trivial on a 1.6M-atom
    // wikipedia install).
    let meta_atlas_path = corpus_engine::meta_atlas::default_meta_atlas_path();
    let meta_atlas =
        match corpus_engine::meta_atlas::MetaAtlasIndex::load(meta_atlas_path.as_deref()) {
            Ok(idx) => Arc::new(idx),
            Err(e) => {
                eprintln!("Meta-atlas: load failed ({e}); boost disabled");
                Arc::new(corpus_engine::meta_atlas::MetaAtlasIndex::empty())
            }
        };
    eprintln!(
        "Meta-atlas:  {} canonical atoms across {} corpus(es)",
        meta_atlas.len(),
        meta_atlas.corpus_count(),
    );
    runtime = runtime.with_meta_atlas(Arc::clone(&meta_atlas));

    // Cross-corpus bridge edges (Phase 6). Loads
    // `~/.sovereign/meta-atlas/bridge_edges.json` produced by `sovereign
    // meta-atlas align`. Empty/absent → bridge_boost is a no-op; the
    // boost only runs at all when `SOVEREIGN_META_BRIDGE` is set.
    let bridge_index = match corpus_engine::meta_atlas::BridgeIndex::load(None) {
        Ok(idx) => Arc::new(idx),
        Err(e) => {
            eprintln!("Bridge: load failed ({e}); bridge boost disabled");
            Arc::new(corpus_engine::meta_atlas::BridgeIndex::empty())
        }
    };
    eprintln!("Bridge:      {} cross-corpus edges", bridge_index.len());
    runtime = runtime.with_bridge(Arc::clone(&bridge_index));

    // Optional cross-encoder reranker. When `SOVEREIGN_RERANK_MODEL_PATH`
    // is set, load that GGUF into a `StandaloneReranker` and wire it
    // into the Runtime. The reranker runs locally (the daemon-attached
    // `SplitInferenceProvider` doesn't support rerank), so this is
    // process-local additional weight (~500 MB for jina-reranker-v3-Q6_K).
    //
    // The candidate pool / threshold defaults come from
    // `RerankConfig::default()` (candidates_k = 50, no min_score) but
    // can be tuned per-run via `SOVEREIGN_RERANK_CANDIDATES_K` and
    // `SOVEREIGN_RERANK_MIN_SCORE` so an eval ablation can sweep them
    // without rebuilding.
    // Dedup-only ablation: `SOVEREIGN_RERANK_DEDUP_ONLY=1` enables
    // overfetch + per-article dedup using ONLY the fusion ordering.
    // Tests whether the SEP source-recall lift seen in the reranker
    // experiment is actually driven by the dedup mechanism or by the
    // cross-encoder logits — a critical question for the
    // "do we need a reranker slot at all?" decision in
    // `sovereign/docs/RERANK_EXPERIMENT.md`. Takes precedence over
    // `SOVEREIGN_RERANK_MODEL_PATH` so the operator can A/B without
    // touching two env vars at once.
    let dedup_only = std::env::var("SOVEREIGN_RERANK_DEDUP_ONLY")
        .map(|s| s == "1" || s.eq_ignore_ascii_case("true"))
        .unwrap_or(false);
    // Per-corpus dedup allowlist. Empirically (RERANK_EXPERIMENT.md):
    // SEP gains +10 sources from dedup; wiki LOSES 3. Default is
    // SEP-only when nothing is set, but the operator can override.
    // Empty string ("") explicitly = no filter (apply to all corpora;
    // matches the original cross-corpus ablation behaviour).
    let dedup_filter = match std::env::var("SOVEREIGN_RERANK_DEDUP_CORPORA") {
        Ok(s) if s.is_empty() => None,
        Ok(s) => Some(
            s.split(',')
                .map(|t| t.trim().to_string())
                .filter(|t| !t.is_empty())
                .collect::<std::collections::HashSet<_>>(),
        ),
        Err(_) => Some(["sep".to_string()].into_iter().collect()),
    };

    // Dedup picker: `fused` (default, RRF/blended-score order) or
    // `vector` (cosine distance to query — tests whether RRF noise
    // inside an article is what hurts wiki dedup).
    let dedup_picker = match std::env::var("SOVEREIGN_RERANK_DEDUP_PICKER")
        .as_deref()
        .unwrap_or("fused")
    {
        "vector" | "vector_distance" => corpus_engine::DedupPicker::VectorDistance,
        _ => corpus_engine::DedupPicker::FusedScore,
    };

    if dedup_only {
        let mut cfg = corpus_engine::RerankConfig::default();
        cfg.enabled = true;
        cfg.per_article = true;
        cfg.dedup_corpus_filter = dedup_filter.clone();
        cfg.dedup_picker = dedup_picker;
        if let Ok(s) = std::env::var("SOVEREIGN_RERANK_CANDIDATES_K") {
            if let Ok(n) = s.parse::<usize>() {
                cfg.candidates_k = n;
            }
        }
        eprintln!(
            "Rerank dedup-only ablation: candidates_k={}, per_article=true, picker={:?}, dedup_corpora={:?} (no cross-encoder)",
            cfg.candidates_k,
            cfg.dedup_picker,
            cfg.dedup_corpus_filter.as_ref().map(|s| {
                let mut v: Vec<&String> = s.iter().collect();
                v.sort();
                v
            })
        );
        runtime = runtime.with_rerank_config(cfg);
    } else if let Ok(rerank_path) = std::env::var("SOVEREIGN_RERANK_MODEL_PATH") {
        let path = PathBuf::from(&rerank_path);
        match sovereign_inference::reranker_standalone::StandaloneReranker::load(
            &path,
            sovereign_core::model_family::ModelFamily::Reranker,
            None,
        ) {
            Ok(reranker) => {
                let reranker: Arc<dyn InferenceProvider> = Arc::new(reranker);
                let rerank_fn = sovereign_tools::corpus::inference_to_rerank_fn(reranker);
                let mut cfg = corpus_engine::RerankConfig::default();
                // GATE_ONLY: install the rerank_fn (for consumers like
                // the PPR admission gate, SOVEREIGN_PPR_EXPAND) WITHOUT
                // enabling the full-pool search_with_rerank pass — the
                // leaf search stays byte-identical to baseline.
                let gate_only = std::env::var("SOVEREIGN_RERANK_GATE_ONLY")
                    .map(|s| s == "1" || s.eq_ignore_ascii_case("true"))
                    .unwrap_or(false);
                cfg.enabled = !gate_only;
                if let Ok(s) = std::env::var("SOVEREIGN_RERANK_CANDIDATES_K") {
                    if let Ok(n) = s.parse::<usize>() {
                        cfg.candidates_k = n;
                    }
                }
                if let Ok(s) = std::env::var("SOVEREIGN_RERANK_MIN_SCORE") {
                    if let Ok(f) = s.parse::<f32>() {
                        cfg.min_score = Some(f);
                    }
                }
                if let Ok(s) = std::env::var("SOVEREIGN_RERANK_ALPHA") {
                    if let Ok(f) = s.parse::<f32>() {
                        cfg.alpha = f;
                    }
                }
                if let Ok(s) = std::env::var("SOVEREIGN_RERANK_PER_ARTICLE") {
                    cfg.per_article = s == "1" || s.eq_ignore_ascii_case("true");
                }
                if let Ok(s) = std::env::var("SOVEREIGN_RERANK_ATLAS_WEIGHT") {
                    if let Ok(f) = s.parse::<f32>() {
                        cfg.atlas_weight = f;
                    }
                }
                cfg.dedup_corpus_filter = dedup_filter.clone();
                cfg.dedup_picker = dedup_picker;
                eprintln!(
                    "Reranker:    {} (candidates_k={}, alpha={:.2}, per_article={}, atlas_weight={:.2}, dedup_corpora={:?}, min_score={:?})",
                    path.file_name().and_then(|n| n.to_str()).unwrap_or("?"),
                    cfg.candidates_k,
                    cfg.alpha,
                    cfg.per_article,
                    cfg.atlas_weight,
                    cfg.dedup_corpus_filter.as_ref().map(|s| {
                        let mut v: Vec<&String> = s.iter().collect();
                        v.sort();
                        v
                    }),
                    cfg.min_score
                );
                runtime = runtime.with_rerank(rerank_fn, cfg);
            }
            Err(e) => {
                eprintln!(
                    "warning: failed to load reranker at {}: {e} — running baseline",
                    path.display()
                );
            }
        }
    }

    Ok(ChatSession {
        runtime: Arc::new(runtime),
        store,
        corpus_engine,
        inference,
        daemon_base: base,
        embed_model,
        atlas_mgr,
    })
}

/// GET `/v1/models` with a 2s timeout. Any non-200 aborts bootstrap
/// with a clear remediation hint — the alternative is cryptic
/// "connection refused" errors minutes later, mid-retrieval.
async fn probe_or_bail(base: &str) -> Result<()> {
    let url = format!("{base}/v1/models");
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(2))
        .build()
        .map_err(|e| Error::Serialization(format!("http client build: {e}")))?;
    match client.get(&url).send().await {
        Ok(r) if r.status().is_success() => Ok(()),
        Ok(r) => Err(Error::Serialization(format!(
            "daemon at {base} returned {} from /v1/models. \
             Is it really a sovereign daemon? Try `svrn doctor`.",
            r.status()
        ))),
        Err(_) => Err(Error::Serialization(format!(
            "daemon unreachable at {base}. \
             Start it with `svrn daemon run`, or pass --daemon <url>."
        ))),
    }
}

/// Resolve `(chat_model_id, embed_model_id)` against the daemon.
/// See the call-site comment in `build_session` for the preference
/// order — explicit flag → SetupConfig stem → `/v1/models` probe.
async fn resolve_model_ids(v1: &str, globals: &ChatGlobals) -> Result<(String, String)> {
    // (a) Explicit flags short-circuit everything.
    if let (Some(c), Some(e)) = (&globals.chat_model, &globals.embed_model) {
        return Ok((c.clone(), e.clone()));
    }

    // (b) SetupConfig filename stems. The daemon loads
    //     `config.models.embed` and advertises it on `/v1/models`
    //     under its filename stem (e.g. `qwen-embedding-0.6b.gguf`
    //     → `qwen-embedding-0.6b`). Preferring the stem over
    //     `/v1/models` iteration means we always reach the
    //     *local* slot, never a mesh-peer advertisement, and the
    //     answer is stable across invocations.
    let from_config = chat_and_embed_stems_from_config();
    let mut chat_found = globals
        .chat_model
        .clone()
        .or_else(|| from_config.as_ref().and_then(|s| s.chat.clone()));
    let mut embed_found = globals
        .embed_model
        .clone()
        .or_else(|| from_config.as_ref().and_then(|s| s.embed.clone()));
    if let (Some(c), Some(e)) = (chat_found.as_ref(), embed_found.as_ref()) {
        return Ok((c.clone(), e.clone()));
    }

    // (c) Fallback: probe `/v1/models`. Used when SetupConfig is
    //     absent (fresh install, dev without setup) or when it
    //     lacks one of the two slots.
    let url = format!("{v1}/models");
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(5))
        .build()
        .map_err(|e| Error::Serialization(format!("http client build: {e}")))?;
    let resp = client
        .get(&url)
        .send()
        .await
        .map_err(|e| Error::Serialization(format!("GET {url}: {e}")))?;
    if !resp.status().is_success() {
        return Err(Error::Serialization(format!(
            "GET {url} returned {}",
            resp.status()
        )));
    }
    let v: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| Error::Serialization(format!("parse /v1/models: {e}")))?;
    let arr = v
        .get("data")
        .and_then(|d| d.as_array())
        .ok_or_else(|| Error::Serialization("/v1/models: no `data` array".into()))?;
    for m in arr {
        let Some(id) = m.get("id").and_then(|s| s.as_str()) else {
            continue;
        };
        let lower = id.to_lowercase();
        let is_embed = lower.contains("embedding") || lower.contains("-embed");
        if is_embed {
            if embed_found.is_none() {
                embed_found = Some(id.to_string());
            }
        } else if chat_found.is_none() {
            chat_found = Some(id.to_string());
        }
    }

    match (chat_found, embed_found) {
        (Some(c), Some(e)) => Ok((c, e)),
        (None, _) => Err(Error::Serialization(
            "daemon lists no chat models — check `svrn setup` and the primary/fast slots".into(),
        )),
        (_, None) => Err(Error::Serialization(
            "daemon lists no embedding model — retrieval will fail. Set `[models] embed` in \
             ~/.sovereign/config.toml or pass --embed-model."
                .into(),
        )),
    }
}

/// Filename-stem extraction for `SetupConfig.models.{primary,embed}`.
/// The daemon advertises these on `/v1/models` using exactly the
/// file stem (`qwen-embedding-0.6b.gguf` → `qwen-embedding-0.6b`),
/// so returning those stems gives us the stable local-model IDs
/// without any `/v1/models` round-trip.
struct ConfigModelStems {
    chat: Option<String>,
    embed: Option<String>,
}

fn chat_and_embed_stems_from_config() -> Option<ConfigModelStems> {
    let cfg = sovereign_core::setup_config::SetupConfig::load().ok()?;
    Some(ConfigModelStems {
        chat: cfg
            .models
            .primary
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s.to_string()),
        embed: cfg
            .models
            .embed
            .file_stem()
            .and_then(|s| s.to_str())
            .map(|s| s.to_string()),
    })
}

/// Emit a one-line summary of what the CorpusEngine can see. Helps
/// the user confirm they're pointing at the right `~/.sovereign/indexes`
/// before running a confused-retrieval diagnostic.
async fn log_installed_corpora(engine: &corpus_engine::CorpusEngine) {
    match engine.installed_indexes().await {
        Ok(ix) if ix.is_empty() => {
            eprintln!("Corpora:     (none installed)");
        }
        Ok(ix) => {
            let names: Vec<String> = ix
                .iter()
                .map(|i| format!("{} ({} chunks)", i.corpus_id, i.chunk_count))
                .collect();
            eprintln!("Corpora:     {}", names.join(", "));
        }
        Err(e) => {
            eprintln!("Corpora:     <error: {e}>");
        }
    }
}

/// Probe `<indexes_dir>/<corpus_id>/wikipedia_graph.db` for each
/// installed corpus and return the first WikipediaGraph that opens
/// cleanly. `None` when no graph file is present — retrieval then
/// behaves exactly as before (no graph expansion, no contested
/// markers). Builds graphs out-of-band via
/// `svrn atlas wikipedia build-graph <corpus-id>`.
async fn load_wikipedia_graph(
    engine: &corpus_engine::CorpusEngine,
    indexes_dir: &std::path::Path,
) -> Option<Arc<dyn corpus_engine::WikipediaGraphApi>> {
    // Memory-pressure escape hatch. The graph is a 7M-edge sqlite
    // mmap; on a host already running the daemon, loading it twice
    // (daemon + bench) has tipped past available RAM in practice. Set
    // SOVEREIGN_DISABLE_WIKI_GRAPH=1 for retrieval workflows that
    // don't need the Layer 0 link graph (e.g. attached-document
    // benches that only exercise the doc-local index).
    if std::env::var("SOVEREIGN_DISABLE_WIKI_GRAPH")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
    {
        eprintln!("Wiki graph:  disabled via SOVEREIGN_DISABLE_WIKI_GRAPH");
        return None;
    }
    // WIKIPEDIA_ATLAS_V2 W3: per corpus, prefer the columnar store
    // (atlas/articles.lance + edges.lance) over the SQLite graph — the shared
    // `corpus_engine::open_wikipedia_graph` gate, returning a backend-agnostic
    // `Arc<dyn WikipediaGraphApi>`.
    let infos = engine.installed_indexes().await.ok()?;
    for info in infos {
        if let Some(g) = corpus_engine::open_wikipedia_graph(indexes_dir, &info.corpus_id).await {
            return Some(g);
        }
    }
    None
}

/// Approval channel that silently yes-answers everything. Chat never
/// hits the ask-user path in practice; this prevents a surprise
/// deadlock in a one-shot CLI invocation.
struct AutoApprove;

#[async_trait]
impl ApprovalChannel for AutoApprove {
    async fn request_approval(&self, _step: &Step, _preview: &ActionPreview) -> Result<bool> {
        Ok(true)
    }

    async fn ask_user(&self, _question: &str) -> Result<String> {
        Ok(String::new())
    }

    fn emit_progress(&self, _step: &Step, _output: &StepOutput) {}
}

