    fn manifest_with_claim(
        id: &str,
        size_gb: Option<f32>,
        claim: sovereign_core::oicp::CapabilityClaim,
    ) -> ProviderManifest {
        ProviderManifest::new(vec![sovereign_core::oicp::ProviderModel {
