            base_model: None,
            quantization: None,
            context_tokens: claim.max_context,
            status: sovereign_core::oicp::ModelStatus {
                available: true,
                loaded: true,
                estimated_tokens_per_sec: None,
                estimated_ttft_ms: None,
                estimated_load_time_sec: None,
            },
