struct TestEnv {
    watcher: Arc<WikipediaNewsworthyWatcher>,
    host: Arc<StubHost>,
    idx_dir: std::path::PathBuf,
    now: chrono::DateTime<Utc>,
    _tmp: tempfile::TempDir,
}

impl TestEnv {
    async fn new(label: &str) -> Self {
        let tmp = tempfile::tempdir().unwrap();
        let recipes_dir = tmp.path().join("recipes");
        let idx_dir = tmp.path().join("indexes");
        std::fs::create_dir_all(&recipes_dir).unwrap();
        std::fs::create_dir_all(&idx_dir).unwrap();

        let embed: EmbedFn = Arc::new(|_text: &str| Box::pin(async { Ok(vec![0.1_f32; 4]) }));
        let engine = Arc::new(CorpusEngine::new(recipes_dir, idx_dir.clone(), embed));

        // Pre-create the two indexes the watcher writes into. This
        // matches what the bulk-install path produces in production —
        // including the closing `mark_ingestion_complete()`. The
        // watcher's local-install gate calls `installed_indexes()`,
        // which skips any index still flagged `ingestion_in_progress`
        // (the state `CorpusIndex::create` leaves behind). Without the
        // mark, the gate sees no installed corpus and short-circuits
        // the whole tick before any portal ingest / article fetch runs.
        for corpus_id in &["wikipedia-newsworthy", "wikipedia"] {
            let idx = CorpusIndex::create(
                &idx_dir.join(corpus_id),
                corpus_id,
                corpus_id,
                "test-model",
                4,
                false,
                "MIT",
            )
            .await
            .unwrap();
            idx.mark_ingestion_complete().unwrap();
        }

        let host = Arc::new(StubHost::new(label));
        let host_dyn: Arc<dyn NewsworthyHost> = host.clone();
        let mw: Arc<dyn MediaWikiClient> = Arc::new(StubMediaWiki);
        let watcher = Arc::new(WikipediaNewsworthyWatcher::new(
            host_dyn,
            engine,
            mw,
            NewsworthyConfig::default(),
        ));
        Self {
            watcher,
            host,
            idx_dir,
            now: Utc.with_ymd_and_hms(2026, 5, 9, 12, 0, 0).unwrap(),
            _tmp: tmp,
        }
    }
}

struct StubHost {
    label: String,
    store: Mutex<HashMap<(String, String), Vec<u8>>>,
}

impl StubHost {
    fn new(label: &str) -> Self {
        Self {
            label: label.to_string(),
            store: Mutex::new(HashMap::new()),
        }
    }

    fn scan_tracked(&self) -> Vec<TrackedArticle> {
        let store = self.store.lock().unwrap();
        store
            .iter()
            .filter(|((a, _), _)| a == APP_ID_TRACKED)
            .filter_map(|(_, v)| serde_json::from_slice::<TrackedArticle>(v).ok())
            .collect()
    }

    fn list_keys(&self, app_id: &str) -> Vec<String> {
        self.store
            .lock()
            .unwrap()
            .keys()
            .filter(|(a, _)| a == app_id)
            .map(|(_, k)| k.clone())
            .collect()
    }
}

#[async_trait::async_trait]
impl NewsworthyHost for StubHost {
    fn self_node_id_str(&self) -> String {
        self.label.clone()
    }
    async fn is_leader(&self) -> bool {
        true
    }
    async fn is_owner_of(&self, _key: &str) -> bool {
        true
    }
    fn store_get(&self, app_id: &str, key: &str) -> Result<Option<Vec<u8>>> {
        Ok(self
            .store
            .lock()
            .unwrap()
            .get(&(app_id.to_string(), key.to_string()))
            .cloned())
    }
    fn store_set(&self, app_id: &str, key: &str, value: Vec<u8>) -> Result<()> {
        self.store
            .lock()
            .unwrap()
            .insert((app_id.to_string(), key.to_string()), value);
        Ok(())
    }
    fn store_scan(&self, app_id: &str, prefix: &str) -> Result<Vec<(String, Vec<u8>)>> {
        let mut out: Vec<(String, Vec<u8>)> = self
            .store
            .lock()
            .unwrap()
            .iter()
            .filter(|((a, k), _)| a == app_id && k.starts_with(prefix))
            .map(|((_, k), v)| (k.clone(), v.clone()))
            .collect();
        out.sort_by(|a, b| a.0.cmp(&b.0));
        Ok(out)
    }
    fn store_delete(&self, app_id: &str, key: &str) -> Result<bool> {
        Ok(self
            .store
            .lock()
            .unwrap()
            .remove(&(app_id.to_string(), key.to_string()))
            .is_some())
    }
}

#[derive(Default)]
struct StubMediaWiki;

#[async_trait::async_trait]
impl MediaWikiClient for StubMediaWiki {
    async fn fetch_parse(&self, page: &str) -> Result<String> {
        if page.starts_with("Portal:Current_events/") {
            Ok(PORTAL_BODY.to_string())
        } else {
            // Any single-article fetch returns the same canned
            // body (revid 1297048221, title="Kyiv"). For the
            // multi-article assertions we'd need a per-title
            // dispatch — out of scope for v0 since we only
            // assert the single Kyiv path.
            Ok(ARTICLE_BODY.to_string())
        }
    }

    async fn batch_revisions(&self, titles: &[String]) -> Result<Vec<RevisionRecord>> {
        // Mimic "every title currently at revid 1000"; the test's
        // first tick has stored last_known_rev_id=Some(1297...) for
        // articles that landed via fetch_article_initial, so the
        // batch revcheck path can compare against that. For simple
        // PendingFetch flows we don't reach this.
        Ok(titles
            .iter()
            .map(|t| RevisionRecord {
                requested_title: t.clone(),
                canonical_title: t.clone(),
                latest_revid: 1000,
                redirected: false,
            })
            .collect())
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `max_file_size` structural goal — every source file in the
//! workdir must be ≤ N lines. One template per framework; the
//! template is concrete-language test code that walks the workdir
//! and asserts the line-count budget.
//!
//! Single source of truth per (framework × max_lines) cell. Tasks
//! call [`render`] and write the result; the solver loop's
//! `MaximizePassing` polarity then drives the model toward passing
//! the generated test.

use std::path::PathBuf;

use crate::tasks::framework::Framework;

/// Render the (test_file_path, test_content) pair for the given
/// framework + line budget. The path is workdir-relative; the
/// caller writes the content there.
pub fn render(framework: Framework, max_lines: usize) -> (PathBuf, String) {
    match framework {
        Framework::Pytest => (
            PathBuf::from("tests/test_max_file_size.py"),
            pytest_template(rungs),
        ),
        Framework::Cargo => (
            PathBuf::from("tests/max_file_size.rs"),
            cargo_template(rungs),
        ),
        Framework::Vitest => (
            PathBuf::from("tests/max_file_size.test.ts"),
            vitest_template(max_lines),
        ),
        Framework::Jest => (
            PathBuf::from("tests/max_file_size.test.ts"),
            jest_template(max_lines),
        ),
        Framework::GoTest => (
            PathBuf::from("max_file_size_test.go"),
            gotest_template(max_lines),
        ),
    }
}

fn pytest_template(max_lines: usize) -> String {
    format!(
        r#""""Structural assertion — generated by tasks::structural::max_file_size."""

import os


def _source_files():
    root = os.path.dirname(os.path.dirname(__file__))
    out = []
    skip = {{"__pycache__", ".pytest_cache", "tests", "build", "dist", "node_modules", ".git", "target"}}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in skip and not d.startswith(".")]
        for f in filenames:
            if f.endswith(".py"):
                out.append(os.path.join(dirpath, f))
    return out


def _line_count(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return sum(1 for _ in f)


def test_max_file_size():
    limit = {max_lines}
    over = []
    for f in _source_files():
        n = _line_count(f)
        if n > limit:
            over.append((os.path.relpath(f), n))
    assert not over, f"files over {{limit}} lines: {{over}}"
"#
    )
}

fn cargo_template(max_lines: usize) -> String {
    // Cargo integration test — lives at tests/max_file_size.rs.
    // Walks CARGO_MANIFEST_DIR for .rs files, skips build dirs, and
    // asserts the line-count budget.
    format!(
        r#"//! Structural assertion — generated by tasks::structural::max_file_size.

use std::fs;
use std::path::{{Path, PathBuf}};

const MAX_LINES: usize = {max_lines};

fn walk(dir: &Path, out: &mut Vec<(PathBuf, usize)>) {{
    const SKIP: &[&str] = &["target", "node_modules", ".git", "tests", "build", "dist"];
    let Ok(rd) = fs::read_dir(dir) else {{ return }};
    for entry in rd.flatten() {{
        let name = entry.file_name();
        let s = name.to_string_lossy();
        if SKIP.iter().any(|x| *x == s) || s.starts_with('.') {{
            continue;
        }}
        let p = entry.path();
        let Ok(ft) = entry.file_type() else {{ continue }};
        if ft.is_dir() {{
            walk(&p, out);
        }} else if ft.is_file() && p.extension().and_then(|e| e.to_str()) == Some("rs") {{
            if let Ok(text) = fs::read_to_string(&p) {{
                out.push((p.clone(), text.lines().count()));
            }}
        }}
    }}
}}

#[test]
fn max_file_size() {{
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let mut all: Vec<(PathBuf, usize)> = Vec::new();
    walk(&root, &mut all);
    let over: Vec<_> = all.iter().filter(|(_, n)| *n > MAX_LINES).collect();
    assert!(
        over.is_empty(),
        "files over {{}} lines: {{:?}}",
        MAX_LINES,
        over.iter().map(|(p, n)| (p.display().to_string(), n)).collect::<Vec<_>>()
    );
}}
"#
    )
}

fn vitest_template(max_lines: usize) -> String {
    format!(
        r#"// Structural assertion — generated by tasks::structural::max_file_size.

import {{ test, expect }} from 'vitest';
import {{ readdirSync, statSync, readFileSync }} from 'node:fs';
import {{ join }} from 'node:path';

const MAX_LINES = {max_lines};
const EXTS = new Set(['.ts', '.tsx', '.js', '.jsx']);
const SKIP = new Set(['node_modules', 'tests', 'dist', 'build', '.git', 'target']);

function walk(dir, out) {{
  for (const name of readdirSync(dir)) {{
    if (SKIP.has(name) || name.startsWith('.')) continue;
    const p = join(dir, name);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, out);
    else if (st.isFile()) {{
      const dot = name.lastIndexOf('.');
      const ext = dot >= 0 ? name.slice(dot) : '';
      if (EXTS.has(ext)) {{
        const n = readFileSync(p, 'utf8').split('\n').length;
        out.push([p, n]);
      }}
    }}
  }}
}}

test('max_file_size', () => {{
  const all = [];
  walk(process.cwd(), all);
  const over = all.filter(([, n]) => n > MAX_LINES);
  expect(over).toEqual([]);
}});
"#
    )
}

