fn gotest_template(max_lines: usize) -> String {
    // Go convention: foo_test.go alongside source; uses
    // testing.T. Walks via filepath.Walk.
    format!(
        r#"// Structural assertion — generated by tasks::structural::max_file_size.

package main

import (
	"io/ioutil"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const maxLines = {max_lines}

func TestMaxFileSize(t *testing.T) {{
	root, err := os.Getwd()
	if err != nil {{ t.Fatal(err) }}
	skip := map[string]bool{{"target": true, "node_modules": true, "tests": true, "build": true, "dist": true, ".git": true}}
	var over []string
	err = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {{
		if err != nil {{ return nil }}
		name := info.Name()
		if info.IsDir() {{
			if skip[name] || strings.HasPrefix(name, ".") {{ return filepath.SkipDir }}
			return nil
		}}
		if !strings.HasSuffix(name, ".go") {{ return nil }}
		body, err := ioutil.ReadFile(p)
		if err != nil {{ return nil }}
		n := strings.Count(string(body), "\n") + 1
		if n > maxLines {{ over = append(over, p) }}
		return nil
	}})
	if err != nil {{ t.Fatal(err) }}
	if len(over) > 0 {{ t.Errorf("files over %d lines: %v", maxLines, over) }}
}}
"#
    )
}

#[cfg(test)]
mod tests {
