// ─── First-mesh consent (W4) ─────────────────────────────────
//
// One-time dialog shown after setup completes, before the user
// joins a multi-peer mesh: "Share idle GPU with the mesh?" The
// answer drives the daemon's peer-inflight ceiling and persists in
// DesktopConfig so we don't re-prompt on every launch.
//
// The Svelte side calls get_first_mesh_consent on boot; None means
// "show the modal". After the user decides, record_first_mesh_consent
// persists the choice AND applies the ceiling at the daemon, so the
// next peer-served inference request is gated correctly.

#[tauri::command]
pub async fn get_first_mesh_consent(
    state: tauri::State<'_, std::sync::Arc<crate::state::AppState>>,
) -> Result<Option<crate::state::FirstMeshConsent>, String> {
    Ok(state.config.read().await.first_mesh_consent.clone())
}

#[tauri::command]
pub async fn record_first_mesh_consent(
    state: tauri::State<'_, std::sync::Arc<crate::state::AppState>>,
    share_gpu: bool,
) -> Result<crate::state::FirstMeshConsent, String> {
    // 1 concurrent peer request is the "Yes, share idle GPU" default
    // — matches the plan's 25% bucket. The user can lift this later
    // in Settings without re-prompting consent.
    let ceiling = if share_gpu { 1 } else { 0 };
    let recorded_at_unix = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let decision = crate::state::FirstMeshConsent {
        share_gpu,
        ceiling,
        recorded_at_unix,
    };

    // Persist FIRST so even if the daemon call fails the decision
    // survives a restart (and we won't re-prompt the user).
    {
        let mut cfg = state.config.write().await;
        cfg.first_mesh_consent = Some(decision.clone());
        cfg.save()
            .map_err(|e| format!("save desktop config: {e}"))?;
    }

    // Apply the ceiling at the daemon. Best-effort: if the daemon
    // isn't reachable yet (early-boot race), the cfg already records
    // the user's intent and a follow-up apply_first_mesh_consent at
    // boot can re-issue. For v1 we just log + continue.
    if let Err(e) = set_contribution_ceiling(Some(ceiling)).await {
        tracing::warn!(
            error = %e,
            ceiling,
            "consent recorded but daemon ceiling apply failed; \
             will be re-applied on next boot"
        );
    }

    Ok(decision)
}

// ─── Crash report (W6) ───────────────────────────────────────
//
// Bundles the latest supervisor-written crash log + redacted config
// into a single markdown file on Desktop, returns the project's
// GitHub Issues URL the frontend opens via tauri-plugin-shell. NO
// auto-upload — the user reads the file and attaches it to an issue
// they open. See crash_bundle.rs.

#[derive(Debug, serde::Serialize)]
pub struct CrashReportInfo {
    /// Absolute path of the report file on disk. UI shows this so
    /// the user can copy/open it.
    pub report_path: String,
    /// The project's GitHub Issues URL. Frontend passes this to
    /// `tauri-plugin-shell.open(url)`; the user attaches the report.
    pub issues_url: String,
}

#[tauri::command]
pub async fn prepare_crash_report() -> Result<CrashReportInfo, String> {
    let cfg = sovereign_core::setup_config::SetupConfig::load().ok();
    let app_version = env!("CARGO_PKG_VERSION");
    let data_dir = cfg
        .as_ref()
        .map(|c| c.data.dir.clone())
        .or_else(|| dirs::home_dir().map(|h| h.join(".sovereign")))
        .ok_or_else(|| "could not resolve data dir".to_string())?;
    let prepared = crate::crash_bundle::prepare_report(&data_dir, cfg.as_ref(), app_version)?;
    Ok(CrashReportInfo {
        report_path: prepared.report_path.to_string_lossy().into_owned(),
        issues_url: prepared.issues_url,
    })
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Cross-platform service registration for the sovereign daemon.
//!
//! On macOS, writes a launchd plist to `~/Library/LaunchAgents/` and
//! invokes `launchctl load`. On Linux, writes a systemd user unit to
//! `~/.config/systemd/user/` and invokes `systemctl --user
//! daemon-reload` + `enable --now`.
//!
//! Templates are bundled at compile time via `include_str!` — see
//! `contrib/launchd/` and `contrib/systemd/`. `{BINARY}` and `{HOME}`
//! placeholders are substituted with absolute paths.
//!
//! All install/uninstall operations are best-effort: failures return
//! `Err(String)` with a human-readable reason but never panic. Setup
//! should treat these as warnings rather than fatal errors — the user
//! can always start the daemon manually with `sovereign daemon run`.

use std::path::{Path, PathBuf};

#[cfg(target_os = "macos")]
const LAUNCHD_TEMPLATE: &str = include_str!("../../../contrib/launchd/com.sovereign.daemon.plist");

#[cfg(target_os = "linux")]
const SYSTEMD_TEMPLATE: &str = include_str!("../../../contrib/systemd/sovereign.service");

/// Install and enable the sovereign daemon service for the current
/// user. `bin_path` must be absolute and point to the `sovereign`
/// binary that should be invoked by the service manager.
///
/// Returns `Ok(())` when the service is registered and started.
/// Returns `Err(String)` on any failure — setup should treat this as
/// a warning and continue.
pub fn install_service(bin_path: &Path) -> Result<(), String> {
    let bin_path = canonicalize_binary(bin_path)?;

    #[cfg(target_os = "macos")]
    {
        install_launchd(&bin_path)
    }

    #[cfg(target_os = "linux")]
    {
        install_systemd(&bin_path)
    }

    #[cfg(not(any(target_os = "macos", target_os = "linux")))]
    {
        let _ = bin_path;
        Err(format!(
            "service registration is not supported on this platform \
             (os={}). Run `sovereign daemon run` manually.",
            std::env::consts::OS
        ))
    }
}

/// Stop the running sovereign daemon without unregistering it from
/// the service manager. A subsequent `sovereign daemon restart` (or
/// `launchctl start`) will bring it back.
///
/// On macOS, sends SIGTERM via `launchctl stop`. Because the plist
/// sets `KeepAlive.SuccessfulExit = false`, a clean exit (status 0)
/// does NOT trigger an automatic restart, so the daemon stays down
/// until explicitly started again.
///
/// Returns `Ok(())` when the stop command was accepted. The process
/// may still be winding down — the daemon drains in-flight requests
/// before it exits.
pub fn stop_service() -> Result<(), String> {
    #[cfg(target_os = "macos")]
    {
        use std::process::Command;
        let out = Command::new("launchctl")
            .args(["stop", "com.svrnmesh.daemon"])
            .output()
            .map_err(|e| format!("spawn launchctl: {e}"))?;
        if !out.status.success() {
            let stderr = String::from_utf8_lossy(&out.stderr);
            if stderr.contains("No such process") || stderr.contains("not running") {
                // Already stopped — treat as success.
                return Ok(());
            }
            // macOS launchctl returns exit 3 with empty stderr when the
            // service is not registered. That's the pidfile-only-install
            // case: there's no service to stop because the user never
            // ran `sovereign setup`. Treat as already-stopped so the
            // caller (`stop_daemon` → `restart_daemon`) doesn't bail
            // before starting a fresh daemon.
            if out.status.code() == Some(3) && stderr.trim().is_empty() {
                return Ok(());
            }
            return Err(format!(
                "launchctl stop com.svrnmesh.daemon failed: {}\n\
                 hint: if the daemon isn't registered, run `sovereign setup` first.",
                stderr.trim()
            ));
        }
        Ok(())
    }
    #[cfg(target_os = "linux")]
    {
        use std::process::Command;
        let out = Command::new("systemctl")
            .args(["--user", "stop", "sovereign.service"])
            .output()
            .map_err(|e| format!("spawn systemctl: {e}"))?;
        if !out.status.success() {
            return Err(format!(
                "systemctl --user stop sovereign failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            ));
        }
        Ok(())
    }
    #[cfg(not(any(target_os = "macos", target_os = "linux")))]
    {
        Err(format!(
            "service stop is not supported on this platform (os={}). \
             Send SIGTERM to the `sovereign daemon run` process manually.",
            std::env::consts::OS
        ))
    }
}

