    /// Read atoms.lance back into [`StoreRow`]s, sorted by local id (Lance does
    /// not guarantee scan order).
    async fn read_atoms_lance(atlas_dir: &Path) -> Vec<StoreRow> {
        let db = lancedb::connect(atlas_dir.to_str().unwrap())
            .execute()
            .await
            .unwrap();
