async fn check_mesh_member(client_url: &str) -> CheckResult {
    // The real status endpoint lives on the client listener
    // (`:9741/status`), not the internal port. Shape is
    // `{node_id, mesh: {name, members_online, members_total, ...}, ...}`.
    let url = format!("{client_url}/status");
    match http_get_json(&url).await {
        Some(json) => {
            let total = json["mesh"]["members_total"].as_u64().unwrap_or(0);
            let online = json["mesh"]["members_online"].as_u64().unwrap_or(0);
            let name = json["mesh"]["name"].as_str().unwrap_or("<unknown>");
            if total > 1 {
                CheckResult {
                    name: "mesh_member",
                    layer: Layer::Commonwealth,
                    status: CheckStatus::Passed,
                    message: format!("member of \"{name}\" — {online}/{total} online"),
                    repair: Repair::None,
                }
            } else if total == 1 {
                // Solo mesh is the default on a freshly-setup single
                // machine. Not an error — just informational.
                CheckResult {
                    name: "mesh_member",
                    layer: Layer::Commonwealth,
                    status: CheckStatus::Passed,
                    message: format!(
                        "solo mesh \"{name}\" — run `svrn mesh create` to invite peers"
                    ),
                    repair: Repair::None,
                }
            } else {
                CheckResult {
                    name: "mesh_member",
                    layer: Layer::Commonwealth,
                    status: CheckStatus::Warning,
                    message: "daemon running but no mesh formed yet".into(),
                    repair: Repair::Manual("Run `svrn mesh create` or accept a join link".into()),
                }
            }
        }
        None => CheckResult {
            name: "mesh_member",
            layer: Layer::Commonwealth,
            status: CheckStatus::Failed,
            message: format!("could not reach {url}"),
            repair: Repair::Executable("svrn daemon restart".into()),
        },
    }
}

/// H3 egress posture: report whether mesh traffic is on iroh and via
/// which path, plus whether an HTTP(S) proxy is engaged for the relay
/// (credentials redacted). Informational — a mesh on the IP path is
/// perfectly valid; this exists so a netops operator can confirm from
/// one command what the node touches.
async fn check_iroh_egress(client_url: &str) -> CheckResult {
    // Local proxy posture, mirroring iroh's HTTPS_PROXY→HTTP_PROXY
    // precedence, userinfo redacted.
    let proxy = ["HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy"]
        .iter()
        .find_map(|v| std::env::var(v).ok().filter(|s| !s.trim().is_empty()))
        .map(|u| match (u.find("://"), u.find('@')) {
            (Some(s), Some(at)) if at > s + 3 => format!("{}***@{}", &u[..s + 3], &u[at + 1..]),
            _ => u,
        });
    let proxy_note = match &proxy {
        Some(p) => format!("; proxy={p} (Basic auth only — NTLM/Kerberos unsupported)"),
        None => String::new(),
    };

    let url = format!("{client_url}/v1/mesh/status");
    match http_get_json(&url).await {
        Some(json) => {
            let paths: Vec<&str> = json["iroh_transport"]
                .as_array()
                .map(|a| {
                    a.iter()
                        .filter_map(|p| p["path"]["path"].as_str())
                        .collect()
                })
                .unwrap_or_default();
            let msg = if paths.is_empty() {
                format!("mesh on the IP path (iroh not carrying peer traffic){proxy_note}")
            } else {
                format!(
                    "mesh carrying traffic over iroh — peer paths: {}{proxy_note}",
                    paths.join(", ")
                )
            };
            CheckResult {
                name: "iroh_egress",
                layer: Layer::Commonwealth,
                status: CheckStatus::Passed,
                message: msg,
                repair: Repair::None,
            }
        }
        None => CheckResult {
            name: "iroh_egress",
            layer: Layer::Commonwealth,
            status: CheckStatus::Warning,
            message: format!("could not read mesh status from {url}{proxy_note}"),
            repair: Repair::None,
        },
    }
}

async fn check_inference_capable(client_url: &str) -> CheckResult {
    // The daemon exposes `inference.loaded_models` on `/status`.
    // Earlier versions had a flat `inference_capable` bool at the top
    // level; that field no longer exists — infer capability from the
    // loaded-models array instead. Empty = cold-start (no model yet
    // loaded), but `/v1/models` still lists available slots.
    let url = format!("{client_url}/status");
    match http_get_json(&url).await {
        Some(json) => {
            let loaded = json["inference"]["loaded_models"]
                .as_array()
                .map(|a| a.len())
                .unwrap_or(0);
            let models_url = format!("{client_url}/v1/models");
            let registered = http_get_json(&models_url)
                .await
                .and_then(|j| j["data"].as_array().map(|a| a.len()))
                .unwrap_or(0);
            let capable = loaded > 0 || registered > 0;
            if capable {
                CheckResult {
                    name: "inference_capable",
                    layer: Layer::Commonwealth,
                    status: CheckStatus::Passed,
                    message: format!(
                        "{registered} model(s) registered, {loaded} currently resident"
                    ),
                    repair: Repair::None,
                }
            } else {
                CheckResult {
                    name: "inference_capable",
                    layer: Layer::Commonwealth,
                    status: CheckStatus::Warning,
                    message: "no models registered — /v1/models is empty. restart the daemon after `svrn setup` completes.".into(),
                    repair: Repair::Executable(
                        "svrn daemon restart".into(),
                    ),
                }
            }
        }
        None => CheckResult {
            name: "inference_capable",
            layer: Layer::Commonwealth,
            status: CheckStatus::Skipped,
            message: "commonwealth daemon unreachable — skipping".into(),
            repair: Repair::None,
        },
    }
}

async fn check_activity_reporting(internal_url: &str) -> CheckResult {
    // The endpoint expects `{level: "hot"|"warm"|"cool"|..., reason: "..."}`
    // and replies 204. Passing `activity_level: 0.0` (the previous
    // payload) yielded a 422 — it's a string enum, not a float.
    let url = format!("{internal_url}/internal/node/activity");
    let resp = http_post_json(
        &url,
        serde_json::json!({
            "level": "cool",
            "reason": "doctor health check"
        }),
    )
    .await;
    match resp {
        Some(r) if r.status().as_u16() == 204 || r.status().is_success() => CheckResult {
            name: "activity_reporting",
            layer: Layer::Commonwealth,
            status: CheckStatus::Passed,
            message: "activity reporting endpoint reachable".into(),
            repair: Repair::None,
        },
        Some(r) => CheckResult {
            name: "activity_reporting",
            layer: Layer::Commonwealth,
            status: CheckStatus::Warning,
            message: format!("activity endpoint returned HTTP {}", r.status()),
            repair: Repair::Manual("Add commonwealth url to sovereign server config".into()),
        },
        None => CheckResult {
            name: "activity_reporting",
            layer: Layer::Commonwealth,
            status: CheckStatus::Warning,
            message: "could not reach activity reporting endpoint".into(),
            repair: Repair::Manual("Add commonwealth url to sovereign server config".into()),
        },
    }
}

// OmO checks

fn find_opencode_skill_dir() -> Option<PathBuf> {
    // Walk up from cwd looking for .opencode/
    let cwd = std::env::current_dir().ok()?;
    let mut dir = cwd.as_path();
    loop {
        let candidate = dir.join(".opencode").join("skills").join("sovereign-code");
        if candidate.exists() {
            return Some(candidate);
        }
        match dir.parent() {
            Some(p) => dir = p,
            None => break,
        }
    }
    None
}

/// Does this SKILL.md carry the frontmatter a loader needs?
///
/// A skill is a markdown file whose YAML frontmatter declares at least
/// `name`. opencode parses the frontmatter and `safeParse`-fails
/// **silently** when `name` is absent — the skill is dropped with no
/// diagnostic at all. So a SKILL.md with no frontmatter is not "a bit
/// stale", it is a file that never loads, and reporting its mere
/// existence as health is a false green (ARCH §9).
///
/// Returns `Err(reason)` describing the first thing that would make a
/// loader reject it.
fn skill_frontmatter_ok(body: &str) -> Result<(), String> {
    let body = body.strip_prefix('\u{feff}').unwrap_or(body);
    let rest = body
        .strip_prefix("---\n")
        .or_else(|| body.strip_prefix("---\r\n"))
        .ok_or_else(|| "no YAML frontmatter — the file must open with `---`".to_string())?;
    let end = rest
        .find("\n---\n")
        .or_else(|| rest.find("\n---\r\n"))
        .ok_or_else(|| "frontmatter is never closed with `---`".to_string())?;
    let front = &rest[..end];

    let has_key = |k: &str| {
        front
            .lines()
            .any(|l| l.trim_start().starts_with(&format!("{k}:")) && l.split_once(':').is_some_and(|(_, v)| !v.trim().is_empty()))
    };
    if !has_key("name") {
        return Err("frontmatter has no non-empty `name:` — loaders drop the skill silently".into());
    }
    if !has_key("description") {
        return Err("frontmatter has no non-empty `description:`".into());
    }
    Ok(())
}

fn check_skill_file() -> CheckResult {
    match find_opencode_skill_dir() {
        Some(skill_dir) => {
            let skill_md = skill_dir.join("SKILL.md");
            // Existence is not health — read it and validate.
            match std::fs::read_to_string(&skill_md) {
                Ok(body) => match skill_frontmatter_ok(&body) {
                    Ok(()) => CheckResult {
                        name: "skill_file",
                        layer: Layer::Omo,
                        status: CheckStatus::Passed,
                        message: format!("SKILL.md valid at {}", skill_md.display()),
                        repair: Repair::None,
                    },
                    Err(why) => CheckResult {
                        name: "skill_file",
                        layer: Layer::Omo,
                        status: CheckStatus::Failed,
                        message: format!("{}: {why}", skill_md.display()),
                        repair: Repair::Manual(
                            "Add YAML frontmatter with `name:` and `description:` — \
                             without it the skill is silently discarded"
                                .into(),
                        ),
                    },
                },
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => CheckResult {
                    name: "skill_file",
                    layer: Layer::Omo,
                    status: CheckStatus::Failed,
                    message: format!("SKILL.md missing from {}", skill_dir.display()),
                    repair: Repair::Manual(
                        "Copy SKILL.md from sovereign/.opencode/skills/sovereign-code/".into(),
                    ),
                },
                Err(e) => CheckResult {
                    name: "skill_file",
                    layer: Layer::Omo,
                    status: CheckStatus::Failed,
                    message: format!("cannot read {}: {e}", skill_md.display()),
                    repair: Repair::None,
                },
            }
        }
        None => CheckResult {
            name: "skill_file",
            layer: Layer::Omo,
            status: CheckStatus::Warning,
            message: "no .opencode/skills/sovereign-code/ directory found — OmO not configured for this project".into(),
            repair: Repair::Manual(
                "Create .opencode/skills/sovereign-code/SKILL.md from sovereign template".into(),
            ),
        },
    }
}

/// Is the opencode config opencode ACTUALLY reads registering us, in
/// the shape it actually accepts?
///
/// This replaced a check for `.opencode/oh-my-opencode.jsonc`, a file
/// nothing has ever read. The real config is
/// `<config_dir>/opencode/opencode.json`, and `mcp` there is a flat
/// map of name → server whose `type` is `local` or `remote`. We shipped
/// `mcp.servers.sovereign` with `type: "http"` until 2026-07-28, which
/// opencode rejects — and no check noticed, because the old one only
/// asked whether an unrelated file existed.
fn check_opencode_config() -> CheckResult {
    let path = dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("opencode")
        .join("opencode.json");

    let result = |status, message, repair| CheckResult {
        name: "opencode_config",
        layer: Layer::Omo,
        status,
        message,
        repair,
    };

    let raw = match std::fs::read_to_string(&path) {
        Ok(r) => r,
        Err(_) => {
            return result(
                CheckStatus::Warning,
                format!("{} not found — opencode not configured", path.display()),
                Repair::Manual("Run `svrn setup` to write it".into()),
            );
        }
    };
    let cfg: serde_json::Value = match serde_json::from_str(&raw) {
        Ok(v) => v,
        Err(e) => {
            return result(
                CheckStatus::Failed,
                format!("{} is not valid JSON: {e}", path.display()),
                Repair::Manual("Fix the JSON by hand; setup refuses to overwrite it".into()),
            );
        }
    };

    if cfg.pointer("/mcp/servers/sovereign").is_some() {
        return result(
            CheckStatus::Failed,
            format!(
                "{} uses the legacy `mcp.servers.sovereign` shape — opencode reads `mcp` as a \
                 flat name → server map, so this entry fails its schema and the server is not \
                 registered",
                path.display()
            ),
            Repair::Manual("Re-run `svrn setup` — it now rewrites this entry".into()),
        );
    }
    match cfg.pointer("/mcp/sovereign/type").and_then(|v| v.as_str()) {
        Some("remote") => result(
            CheckStatus::Passed,
            format!("opencode registers sovereign at {}", path.display()),
            Repair::None,
        ),
        Some(other) => result(
            CheckStatus::Failed,
            format!("`mcp.sovereign.type` is \"{other}\" — opencode accepts only \"local\" or \"remote\""),
            Repair::Manual("Re-run `svrn setup`".into()),
        ),
        None => result(
            CheckStatus::Warning,
            format!("{} has no `mcp.sovereign` entry", path.display()),
            Repair::Manual("Run `svrn setup` to add it".into()),
        ),
    }
}

async fn check_mcp_live() -> CheckResult {
    // MCP is JSON-RPC over `/mcp`; tools/list is a method, not a
    // path. See the same fix in `check_server_tools`.
    let resp = http_post_json(
        "http://localhost:9741/mcp",
        serde_json::json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "tools/list",
        }),
