}

// ── Freshness-pipeline checks ────────────────────────────────

/// Query the daemon's `/v1/projects` endpoint and surface the
/// aggregate watcher health. Passes when every registered project
/// has all its watchers healthy; downgrades to Warning when any
/// watcher is Crashed; Failed when any watcher is Disabled (the
/// daemon has given up auto-restarting and needs operator action).
async fn check_project_watchers() -> CheckResult {
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(3))
        .build()
    {
        Ok(c) => c,
        Err(_) => {
            return CheckResult {
                name: "project_watchers",
                layer: Layer::Sovereign,
                status: CheckStatus::Warning,
                message: "could not build HTTP client".into(),
                repair: Repair::None,
            };
        }
    };

    let resp = match client.get("http://127.0.0.1:9741/v1/projects").send().await {
        Ok(r) => r,
        Err(_) => {
            return CheckResult {
                name: "project_watchers",
                layer: Layer::Sovereign,
                status: CheckStatus::Warning,
                message: "daemon unreachable — /v1/projects did not answer".into(),
                repair: Repair::Executable("svrn daemon restart".into()),
            };
        }
    };

    if resp.status().as_u16() == 404 {
        return CheckResult {
            name: "project_watchers",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message:
                "/v1/projects returned 404 — project_http_router not mounted (restart the daemon)"
                    .into(),
            repair: Repair::Executable("svrn daemon restart".into()),
        };
    }

    let body: serde_json::Value = match resp.json().await {
        Ok(v) => v,
        Err(_) => {
            return CheckResult {
                name: "project_watchers",
                layer: Layer::Sovereign,
                status: CheckStatus::Warning,
                message: "/v1/projects returned unexpected shape".into(),
                repair: Repair::Manual("inspect daemon logs".into()),
            };
        }
    };

    let Some(projects) = body["projects"].as_array() else {
        return CheckResult {
            name: "project_watchers",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message: "/v1/projects returned unexpected shape".into(),
            repair: Repair::Manual("inspect daemon logs".into()),
        };
    };
    if projects.is_empty() {
        return CheckResult {
            name: "project_watchers",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message: "daemon is running but no projects registered".into(),
            repair: Repair::Manual(
                "cd <repo-root> && svrn project register  (run from each repo root)".into(),
            ),
        };
    }

    let mut crashed: Vec<String> = Vec::new();
    let mut disabled: Vec<String> = Vec::new();
    let mut active_ok = 0usize;
    for p in projects {
        let id = p["corpus_id"].as_str().unwrap_or("?");
        let Some(status) = p["status"].as_object() else {
            continue;
        };
        for (kind, s) in status {
            let state = s["state"].as_str().unwrap_or("?");
            match state {
                "idle" | "active" | "pending" => active_ok += 1,
                "crashed" => crashed.push(format!("{id}:{kind}")),
                "disabled" => disabled.push(format!("{id}:{kind}")),
                _ => {}
            }
        }
    }

    if !disabled.is_empty() {
        return CheckResult {
            name: "project_watchers",
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} watcher(s) disabled after repeated crashes: {}",
                disabled.len(),
                disabled.join(", ")
            ),
            repair: Repair::Executable("svrn project watch restart <corpus_id>".into()),
        };
    }
    if !crashed.is_empty() {
        return CheckResult {
            name: "project_watchers",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message: format!(
                "{} watcher(s) crashed but auto-restarting: {}",
                crashed.len(),
                crashed.join(", ")
            ),
            repair: Repair::Manual(
                "tail ~/.sovereign/logs/watch-<id>-<watcher>.log for details".into(),
            ),
        };
    }
    CheckResult {
        name: "project_watchers",
        layer: Layer::Sovereign,
        status: CheckStatus::Passed,
        message: format!(
            "{} project(s), {} watcher(s) healthy",
            projects.len(),
            active_ok
        ),
        repair: Repair::None,
    }
}

/// Run `PRAGMA integrity_check` (via `ScipGraph::open_with_integrity`)
/// on every per-corpus `scip_graph.db`. A corrupt DB is quarantined
/// by `open_with_integrity` as a side effect; we surface that to
/// the operator so they can trigger an immediate rebuild. This is
/// the doctor-level complement of the daemon's automatic
/// quarantine-on-open behaviour.
fn check_scip_integrity() -> CheckResult {
    let indexes_dir = home_dir().join(".sovereign").join("indexes");
    let Ok(entries) = std::fs::read_dir(&indexes_dir) else {
        return CheckResult {
            name: "scip_integrity",
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: format!("no indexes dir at {}", indexes_dir.display()),
            repair: Repair::None,
        };
    };

    let mut checked = 0usize;
    let mut corrupt: Vec<String> = Vec::new();
    let mut stale_schema: Vec<String> = Vec::new();
    for entry in entries.flatten() {
        if !entry.path().is_dir() {
            continue;
        }
        let db = entry.path().join("scip_graph.db");
        if !db.exists() {
            continue;
        }
        let corpus = entry.file_name().to_string_lossy().to_string();
        match corpus_engine_scip::ScipGraph::open_with_integrity(&db, &corpus) {
            Ok(_) => {
                checked += 1;
            }
            Err(corpus_engine_scip::OpenError::Corrupt { .. }) => {
                corrupt.push(corpus);
            }
            Err(corpus_engine_scip::OpenError::SchemaMismatch { .. }) => {
                stale_schema.push(corpus);
            }
            Err(_) => {
                // Other errors (IO, transient DB issues) shouldn't
                // trip the integrity check — the daemon will log
                // them on its next open.
            }
        }
    }

    if !corrupt.is_empty() {
        return CheckResult {
            name: "scip_integrity",
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} SCIP DB(s) were corrupt and moved aside: {}",
                corrupt.len(),
                corrupt.join(", ")
            ),
            repair: Repair::MultiExecutable(
                corrupt
                    .iter()
                    .map(|id| format!("svrn project refresh --name {id} --local"))
                    .collect(),
            ),
        };
    }
    if !stale_schema.is_empty() {
        return CheckResult {
            name: "scip_integrity",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message: format!(
                "{} SCIP DB(s) have an outdated schema: {}",
                stale_schema.len(),
                stale_schema.join(", ")
            ),
            repair: Repair::MultiExecutable(
                stale_schema
                    .iter()
                    .map(|id| format!("svrn project refresh --name {id} --local"))
                    .collect(),
            ),
        };
    }
    CheckResult {
        name: "scip_integrity",
        layer: Layer::Sovereign,
        status: CheckStatus::Passed,
        message: format!("{checked} SCIP DB(s) integrity OK"),
        repair: Repair::None,
    }
}

/// Per-project snapshot of "is a rebuild trying right now" pulled
/// from `/v1/projects`. The freshness check uses this to tell apart
/// two failure modes that look identical from disk state alone:
///
/// - **Wedged**: source-tree mtime is past `last_export_at`, AND no
///   rebuild is running. The watcher fired nothing in response to
///   recent edits.
///
/// - **Slow rebuild**: source-tree mtime is past `last_export_at`,
///   AND a rebuild IS in flight. The watcher fired correctly — the
///   exporter is the slow link (or stuck on the cargo target lock,
///   or hung in rust-analyzer).
///
/// Without `rebuild_in_flight`, a single Failed message would fire
/// every time you save during the debounce-plus-rebuild window
/// (~2.5 min on this monorepo), which would make the check
/// effectively useless.
#[derive(Debug, Default)]
struct ProjectLiveness {
    rebuild_in_flight: bool,
}

async fn fetch_project_liveness() -> std::collections::HashMap<String, ProjectLiveness> {
    let mut out = std::collections::HashMap::new();
    let v = match http_get_json("http://127.0.0.1:9741/v1/projects").await {
        Some(v) => v,
        None => return out,
    };
    let projects = match v.get("projects").and_then(|p| p.as_array()) {
        Some(arr) => arr,
        None => return out,
    };
    for proj in projects {
        let Some(id) = proj.get("corpus_id").and_then(|s| s.as_str()) else {
            continue;
        };
        let rebuild_in_flight = proj
            .get("rebuild_in_flight")
            .and_then(|b| b.as_bool())
            .unwrap_or(false);
        out.insert(id.to_string(), ProjectLiveness { rebuild_in_flight });
    }
    out
}

/// Check that each registered project's SCIP graph reflects the
/// current state of its source tree. Three independent signals:
///
/// 1. `last_indexed_head` vs `git rev-parse HEAD`: catches a
///    watcher that's behind by one or more commits.
///
/// 2. `export_age_secs` vs the newest source-file mtime under the
///    project root: catches a wedged watcher that hasn't picked up
///    *uncommitted* edits. The newest mtime walk is bounded by the
///    same exclusions the FS watcher applies (`target/`, `.git/`,
///    `node_modules/`, the per-project `ignore_paths`).
///
/// 3. `rebuild_in_flight` from `/v1/projects`: when signals 1 or 2
///    trip, this tells us *why*. A rebuild that's running (just
///    slow) gets a Warning; no-rebuild-firing gets a Failed.
///
/// Pairs with `scip_indexed` (row count) and `scip_exporters`
/// (toolchain). Together they answer the "is the SCIP graph
/// honestly reflecting reality?" question that the byte-threshold
/// version of `scip_indexed` was lying about.
/// Corpus ids under `~/.sovereign/indexes` that carry a SCIP graph — i.e.
/// things a project watcher OUGHT to be maintaining. Mirrors the daemon's
/// `warn_orphaned_indexes` scan; used to tell "nothing registered because
/// there's nothing to register" apart from "nothing registered and four
/// code indexes are quietly rotting".
fn orphaned_index_ids() -> Vec<String> {
    let mut ids: Vec<String> = orphaned_indexes().into_iter().map(|(id, _)| id).collect();
    ids.sort();
    ids
}

/// The same scan, paired with each corpus's originating repo root.
///
/// The daemon's `warn_orphaned_indexes` says it "can't safely auto-register
/// those — we don't know which filesystem path each one came from". For a
/// code corpus we usually DO know: the code-ingest pipeline stamps
/// `source_path` into `_corpus_meta.json` (`CorpusIndex::set_source_path`),
/// which is precisely the repo root `project register --root` wants. That
/// turns doctor's advice from "go figure out the path" into an exact,
/// copy-pasteable command.
fn orphaned_indexes() -> Vec<(String, Option<String>)> {
    let indexes_dir = home_dir().join(".sovereign").join("indexes");
    let Ok(entries) = std::fs::read_dir(&indexes_dir) else {
        return Vec::new();
    };
    let mut out: Vec<(String, Option<String>)> = entries
        .flatten()
        .filter(|e| e.path().is_dir())
        .filter(|e| e.path().join("scip_graph.db").exists())
        .filter_map(|e| {
            let id = e.file_name().to_str()?.to_string();
            let root = std::fs::read_to_string(e.path().join("_corpus_meta.json"))
                .ok()
                .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())
                .and_then(|v| v.get("source_path")?.as_str().map(str::to_string));
            Some((id, root))
        })
        .collect();
    out.sort();
    out
}

/// Do the code tools actually SEE any corpus?
///
/// Every other code check verifies an ingredient — the SCIP db exists,
/// `CorpusIndex::open` succeeds — and all of them passed on 2026-07-24
/// while `code_search` returned "0 code corpora" on a healthy 36k-chunk
/// index. The corpus was screened out one layer further in, by a
/// `kind == CorpusKind::Code` filter that repo corpora deliberately don't
/// satisfy. No amount of ingredient-checking catches that; only asking the
/// question the tool asks does.
///
/// So this check runs the REAL predicate the code tools run
/// (`sovereign_tools::code::has_code_graph`) over the REAL corpus list and
/// reports the count. If a corpus has a graph but the tools would skip it,
/// that discrepancy IS the finding.
async fn check_code_tools_see_corpora() -> CheckResult {
    let name = "code_tools_visibility";
    let on_disk = orphaned_index_ids();
    if on_disk.is_empty() {
        return CheckResult {
            name,
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: "no code corpora indexed".into(),
            repair: Repair::None,
        };
    }

    // Open each index and ask the REAL predicate about the REAL `IndexInfo`
    // — same `kind` derivation, same `has_code_graph` rule the tools use. No
    // corpus engine (and so no EmbedFn) is needed to answer this.
    let indexes_dir = home_dir().join(".sovereign").join("indexes");
    let mut visible: Vec<String> = Vec::new();
    for id in &on_disk {
        let Ok(index) = corpus_engine::CorpusIndex::open(&indexes_dir.join(id)).await else {
            // `code_indexed` already reports an unreadable Lance table.
            continue;
        };
        let Ok(info) = index.info().await else {
            continue;
        };
        if sovereign_tools::code::has_code_graph(&info) {
            visible.push(info.corpus_id);
        }
    }

    if visible.is_empty() {
        return CheckResult {
            name,
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} code corpus(es) on disk ({}) but the code tools can see NONE \
                 of them — symbols / code_search / recent_changes will return \
                 empty while every other check reports green.",
                on_disk.len(),
                on_disk.join(", ")
            ),
            repair: Repair::Manual(
                "A corpus is visible to the code tools when it is tagged \
                 CorpusKind::Code OR has a scip_graph.db beside its chunk table \
                 (sovereign_tools::code::has_code_graph). Check that the index \
                 dir and _corpus_meta.json agree."
                    .into(),
            ),
        };
    }

    CheckResult {
        name,
        layer: Layer::Sovereign,
        status: CheckStatus::Passed,
        message: format!(
            "code tools can see {} corpus(es): {}",
            visible.len(),
            visible.join(", ")
        ),
        repair: Repair::None,
    }
}

async fn check_watcher_freshness() -> CheckResult {
    let registry = match sovereign_mesh::projects::Registry::load() {
        Ok(r) => r,
        Err(_) => {
            return CheckResult {
                name: "watcher_freshness",
                layer: Layer::Sovereign,
                status: CheckStatus::Skipped,
                message: "project registry not loadable".into(),
                repair: Repair::None,
            };
        }
    };
    let entries = registry.entries();
    if entries.is_empty() {
        // An empty registry is only a non-event when there is nothing to
        // keep fresh. If code indexes exist on disk, this is the ORPHAN
        // state and it is the single most misleading condition doctor can
        // encounter: freshness is owned by the Reindexer, which builds one
        // ProjectHandle per REGISTERED project, so zero registrations means
        // zero watchers — while `scip_indexed` / `code_indexed` keep
        // reporting green off the stale files sitting right there, and
        // `svrn status` prints ✓/✓ for both.
        //
        // Reported as Skipped ("no projects registered"), it rendered as a
        // neutral dash and cost a full debugging session on 2026-07-24 to
        // rediscover by hand — on a box whose chunk index was 27 days old
        // and whose call graph was 11. The daemon already logs this via
        // `warn_orphaned_indexes`, but into a log nobody reads. Fail loudly
        // instead; the fix is one command.
        let orphans = orphaned_indexes();
        if !orphans.is_empty() {
            let ids: Vec<&str> = orphans.iter().map(|(id, _)| id.as_str()).collect();
            // `source_path` gives an exact command; without it the operator
            // has to supply the root, so say that rather than guess.
            let repairs: Vec<String> = orphans
                .iter()
                .map(|(id, root)| match root {
                    Some(r) => format!("svrn project register --root {r} --name {id}"),
                    None => format!("svrn project register --root <repo> --name {id}"),
                })
                .collect();
            return CheckResult {
                name: "watcher_freshness",
                layer: Layer::Sovereign,
                status: CheckStatus::Failed,
                message: format!(
                    "NO projects registered, but {} code index(es) exist on disk \
                     ({}). Nothing is watching them: no FS watcher, no git-HEAD \
                     poll, no rebuild queue. The index/call-graph checks above \
                     pass off whatever was last built BY HAND and will keep \
                     passing as the code drifts away from them.",
                    orphans.len(),
                    ids.join(", ")
                ),
                repair: Repair::MultiExecutable(repairs),
            };
        }
        return CheckResult {
            name: "watcher_freshness",
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: "no projects registered (and no code indexes to watch)".into(),
            repair: Repair::None,
        };
    }

    let indexes_dir = home_dir().join(".sovereign").join("indexes");
    // Allow this many seconds between source mtime and export time
    // before we flag. Covers normal debounce (2s) + worker latency +
    // the export run itself. Anything past this is a real wedge.
    const FRESHNESS_GRACE_SECS: u64 = 60;
    // Hard cap on the source-tree walk so a misconfigured ignore list
    // can't tip doctor into a multi-minute traversal of a model-checkpoint
    // directory. 25k files is well above any realistic source corpus.
    const WALK_FILE_BUDGET: usize = 25_000;

    // Liveness from /v1/projects. Empty when the daemon isn't reachable;
    // in that case we degrade gracefully — all source-newer-than-export
    // findings render as Failed, since we can't tell apart "wedged" from
    // "rebuild trying".
    let liveness = fetch_project_liveness().await;

    let mut behind_head: Vec<String> = Vec::new();
    let mut wedged: Vec<String> = Vec::new();
    let mut slow_rebuild: Vec<String> = Vec::new();
    let mut healthy: Vec<String> = Vec::new();

    for entry in entries {
        let corpus_id = entry.corpus_id.clone();
        let db = indexes_dir.join(&corpus_id).join("scip_graph.db");
        if !db.exists() {
            // `scip_indexed` already covers the missing-DB case; don't double-fail.
            continue;
        }
        let graph = match corpus_engine_scip::ScipGraph::open(&db, &corpus_id) {
            Ok(g) => g,
            Err(_) => continue,
        };

        // Signal 1: git-head drift. Surfaces a watcher that's a full
        // commit behind. Skip silently when the project isn't a git
        // repo (no HEAD to compare against).
        let current_head = sovereign_mesh::reindexer::read_git_head(&entry.root);
        let indexed_head = graph.last_indexed_head().await;
        if let (Some(cur), Some(idx)) = (current_head.as_ref(), indexed_head.as_ref()) {
            if cur != idx {
                behind_head.push(format!(
                    "{corpus_id}: indexed {short_idx}, HEAD {short_cur}",
                    short_idx = &idx[..idx.len().min(8)],
                    short_cur = &cur[..cur.len().min(8)],
                ));
                continue;
            }
        }

        // Signal 2: source-tree mtime past last export. Walks the
        // project root for the newest source-extension mtime, then
        // compares it to last_export_at.
        let export_age = match graph.export_age_secs().await {
            Some(a) => a,
            None => continue, // no export recorded — `scip_indexed` covers
        };
        let newest_source_age =
            newest_source_age_secs(&entry.root, &entry.watchers.ignore_paths, WALK_FILE_BUDGET);
        match newest_source_age {
            Some(src_age) if src_age + FRESHNESS_GRACE_SECS < export_age => {
                // Source is meaningfully newer than the last completed export.
                // Now ask the daemon: is a rebuild trying right now? If yes,
                // we're not wedged — just slow. If no, the watcher missed it.
                let in_flight = liveness
                    .get(&corpus_id)
                    .map(|l| l.rebuild_in_flight)
                    .unwrap_or(false);
                if in_flight {
                    slow_rebuild.push(format!(
                        "{corpus_id}: rebuild in flight, last successful index {export_age}s ago, source edit {src_age}s ago"
                    ));
                } else {
                    wedged.push(format!(
                        "{corpus_id}: newest source edit {src_age}s ago, last index {export_age}s ago, no rebuild in flight"
                    ));
                }
            }
            _ => {
                healthy.push(corpus_id);
            }
        }
    }

    // Status precedence: Failed (wedged or behind-HEAD) > Warning
    // (slow rebuild) > Passed. A single CheckResult collapses
    // multi-project state to the worst observed level, with all
    // findings listed in the message so nothing's hidden.
    if !behind_head.is_empty() {
        return CheckResult {
            name: "watcher_freshness",
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} project(s) have a SCIP graph behind git HEAD: {}. \
                 The watcher hasn't rebuilt since a recent commit — check daemon.err for \
                 SCIP export failures or a stuck rebuild lock.",
                behind_head.len(),
                behind_head.join("; ")
            ),
            repair: Repair::MultiExecutable(
                registry
                    .entries()
                    .iter()
                    .map(|e| format!("svrn project refresh --name {} --local", e.corpus_id))
                    .collect(),
            ),
        };
    }
    if !wedged.is_empty() {
        return CheckResult {
            name: "watcher_freshness",
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} project(s) have uncommitted source edits the watcher hasn't picked up: {}. \
                 fs_change events may not be reaching the reindexer — check daemon.err for \
                 `notify` errors or nudge with `svrn project refresh`.",
                wedged.len(),
                wedged.join("; ")
            ),
            repair: Repair::Executable("svrn project refresh".into()),
        };
    }
    if !slow_rebuild.is_empty() {
        return CheckResult {
            name: "watcher_freshness",
            layer: Layer::Sovereign,
            status: CheckStatus::Warning,
            message: format!(
                "{} project(s) have a SCIP rebuild in flight but the source has moved past \
                 the last successful index: {}. The watcher is firing correctly — the exporter \
                 is slow (rust-analyzer often blocks on the cargo target lock during a release \
                 build, or stalls on macro-heavy crates). Wait it out, then re-run doctor.",
                slow_rebuild.len(),
                slow_rebuild.join("; ")
            ),
            repair: Repair::None,
        };
    }
    if healthy.is_empty() {
        return CheckResult {
            name: "watcher_freshness",
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: "no projects had enough state to evaluate freshness".into(),
            repair: Repair::None,
        };
    }
    CheckResult {
        name: "watcher_freshness",
        layer: Layer::Sovereign,
        status: CheckStatus::Passed,
        message: format!(
            "SCIP graph current for {}: {}",
            healthy.len(),
            healthy.join(", ")
        ),
        repair: Repair::None,
    }
}

/// Walk the project root and return the seconds-since-last-modified
/// of the newest source file. Mirrors the watcher's `is_source_event`
/// + `IgnoreFilter` logic at directory granularity so the answer
/// reflects what the watcher *would* have seen.
///
/// Bounded by `file_budget` to keep doctor latency predictable on
/// any tree shape. Returns `None` when the root is unreadable, has
/// no source files within the budget, or when system clock skew
/// makes mtimes nonsensical.
fn newest_source_age_secs(
    root: &std::path::Path,
    extra_ignores: &[String],
    file_budget: usize,
) -> Option<u64> {
    use std::time::SystemTime;

    const UNIVERSAL_IGNORES: &[&str] = &[
        ".git",
        "node_modules",
        "target",
        "dist",
        "build",
        ".cache",
        ".next",
        "__pycache__",
        ".venv",
        "venv",
    ];
    const SOURCE_EXTS: &[&str] = &[
        "rs", "ts", "tsx", "js", "jsx", "mjs", "cjs", "py", "go", "java",
    ];

    let now = SystemTime::now();
    let mut newest: Option<u64> = None;
    let mut visited = 0usize;
    let mut stack: Vec<std::path::PathBuf> = vec![root.to_path_buf()];

    while let Some(dir) = stack.pop() {
        if visited >= file_budget {
            break;
        }
        let entries = match std::fs::read_dir(&dir) {
            Ok(e) => e,
            Err(_) => continue,
        };
        for entry in entries.flatten() {
            if visited >= file_budget {
                break;
            }
            let path = entry.path();
            let file_name = match path.file_name().and_then(|n| n.to_str()) {
                Some(n) => n.to_string(),
                None => continue,
            };
            if UNIVERSAL_IGNORES.contains(&file_name.as_str())
                || extra_ignores.iter().any(|e| e == &file_name)
            {
                continue;
            }
            let file_type = match entry.file_type() {
                Ok(t) => t,
                Err(_) => continue,
            };
            if file_type.is_dir() {
                stack.push(path);
                continue;
            }
            if !file_type.is_file() {
                continue;
            }
            visited += 1;
            let ext = path
                .extension()
                .and_then(|s| s.to_str())
                .unwrap_or_default()
                .to_ascii_lowercase();
            if !SOURCE_EXTS.contains(&ext.as_str()) {
                continue;
            }
            let mtime = match entry.metadata().ok().and_then(|m| m.modified().ok()) {
                Some(m) => m,
                None => continue,
            };
            let age_secs = now.duration_since(mtime).ok()?.as_secs();
            newest = Some(match newest {
                Some(prev) => prev.min(age_secs),
                None => age_secs,
            });
        }
    }
    newest
}

/// Verify that, for every registered project, the SCIP exporter
/// binaries needed by the languages present in its workspace are
/// reachable on PATH. Language-agnostic: it consults
/// `corpus_engine_scip::scip_export::check_exporters`, which iterates
/// every registered exporter (rust-analyzer, scip-typescript,
/// scip-python, scip-go, scip-java) and reports those that are
/// needed but absent. Pairs with `scip_indexed` (row count): an
/// empty graph plus a missing exporter localises the failure.
fn check_scip_exporters() -> CheckResult {
    let registry = match sovereign_mesh::projects::Registry::load() {
        Ok(r) => r,
        Err(_) => {
            return CheckResult {
                name: "scip_exporters",
                layer: Layer::Sovereign,
                status: CheckStatus::Skipped,
                message: "project registry not loadable".into(),
                repair: Repair::None,
            };
        }
    };

    let entries = registry.entries();
    if entries.is_empty() {
        return CheckResult {
            name: "scip_exporters",
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: "no projects registered".into(),
            repair: Repair::None,
        };
    }

    // Aggregate workspace roots across every registered project so
    // we ask `check_exporters` once. The function dedupes via its
    // exporter loop; per-project ordering doesn't matter here.
    let mut roots: Vec<std::path::PathBuf> = Vec::new();
    for entry in entries {
        let root = entry.root.clone();
        if !root.exists() {
            continue;
        }
        let detected = corpus_engine_scip::scip_export::find_cargo_workspace_roots(&root);
        if detected.is_empty() {
            roots.push(root);
        } else {
            roots.extend(detected);
        }
    }
    roots.sort();
    roots.dedup();

    if roots.is_empty() {
        return CheckResult {
            name: "scip_exporters",
            layer: Layer::Sovereign,
            status: CheckStatus::Skipped,
            message: "no reachable project roots".into(),
            repair: Repair::None,
        };
    }

    let check = corpus_engine_scip::scip_export::check_exporters(&roots);
    if !check.missing.is_empty() {
        let summary = check
            .missing
            .iter()
            .map(|m| format!("{} ({})", m.language_id, m.command))
            .collect::<Vec<_>>()
            .join(", ");
        let hints: Vec<String> = check
            .missing
            .iter()
            .map(|m| format!("{}: {}", m.language_id, m.install_hint))
            .collect();
        return CheckResult {
            name: "scip_exporters",
            layer: Layer::Sovereign,
            status: CheckStatus::Failed,
            message: format!(
                "{} SCIP exporter(s) referenced by registered projects are not in PATH: {summary}. \
                 Calling these is what populates the SCIP graph — when they fail silently the \
                 graph stays empty and call-graph tools return nothing.",
                check.missing.len(),
            ),
            repair: Repair::MultiExecutable(hints),
        };
    }
    let available = check
        .available
        .iter()
        .map(|e| e.language_id)
        .collect::<Vec<_>>()
        .join(", ");
    CheckResult {
        name: "scip_exporters",
        layer: Layer::Sovereign,
        status: CheckStatus::Passed,
        message: if available.is_empty() {
            "no language exporters needed for registered projects".into()
        } else {
            format!("SCIP exporters available for: {available}")
        },
        repair: Repair::None,
    }
}

/// Scan registered project roots for legacy `SOVEREIGN_HOOK_V*`
/// post-commit hooks. The daemon owns freshness now, so any
/// surviving hook is a ticking footgun (stale binary path, silent
/// failures into `~/.sovereign/hooks.log`). Surface them with a
/// one-shot cleanup hint.
fn check_legacy_hooks() -> CheckResult {
    // Best-effort: read the registry directly. If the registry
    // isn't loadable, skip this check — the `warn_orphaned_indexes`
    // path at daemon startup will cover the miss.
    let registry = match sovereign_mesh::projects::Registry::load() {
        Ok(r) => r,
        Err(_) => {
            return CheckResult {
                name: "legacy_hooks",
                layer: Layer::Sovereign,
                status: CheckStatus::Skipped,
                message: "project registry not loadable".into(),
                repair: Repair::None,
            };
        }
    };
    let mut stale: Vec<String> = Vec::new();
    for entry in registry.entries() {
        let hook = entry.root.join(".git/hooks/post-commit");
        let Ok(contents) = std::fs::read_to_string(&hook) else {
            continue;
        };
        if contents.contains("SOVEREIGN_HOOK_V") {
            stale.push(entry.corpus_id.clone());
        }
    }
    if stale.is_empty() {
        return CheckResult {
            name: "legacy_hooks",
            layer: Layer::Sovereign,
            status: CheckStatus::Passed,
            message: "no legacy post-commit hooks found".into(),
            repair: Repair::None,
        };
    }
    CheckResult {
        name: "legacy_hooks",
        layer: Layer::Sovereign,
        status: CheckStatus::Warning,
        message: format!(
            "{} project(s) still carry a legacy sovereign post-commit hook: {}",
            stale.len(),
            stale.join(", ")
        ),
        repair: Repair::Executable(
            "svrn project install-hooks  (in the affected repo — removes the legacy hook)".into(),
        ),
    }
}

// ── Run all checks ─────────────────────────────────────────────────────────────

async fn run_checks(sovereign_dir: &std::path::Path) -> Vec<CheckResult> {
    let mut results = Vec::new();

    // ── Sovereign layer ──────────────────────────────────────────
    results.push(check_server_running().await);
    results.push(check_server_tools().await);
    results.push(check_scip_indexed().await);
    results.push(check_scip_exporters());
    results.push(check_watcher_freshness().await);
    results.push(check_code_indexed().await);
    results.push(check_code_tools_see_corpora().await);
    results.push(check_project_indexed());
    results.push(check_notes_db());
    results.push(check_test_runner(sovereign_dir));
    results.push(check_lint_runner(sovereign_dir));
    results.push(check_watcher_live(sovereign_dir).await);
    results.push(check_log_dir_size());
    // Config-only, and intentionally not gated on the daemon being up — see the
    // function's doc comment.
    results.push(check_distributed_primary_contained());

    // Freshness pipeline: registry-level checks that report on the
    // daemon's project watchers and the integrity of their SCIP
    // databases. These run only when the daemon is live; otherwise
    // we'd be testing files the daemon may be about to overwrite.
    if tcp_connectable("127.0.0.1", 9741).await {
        results.push(check_project_watchers().await);
        results.push(check_scip_integrity());
        results.push(check_legacy_hooks());
    }

    // ── Commonwealth layer (skip if not configured) ──────────────
    // The embedded daemon serves two listeners:
    //   - `:9741` — client surface: /status, /v1/*, /mcp, /v1/mesh/*.
    //   - `:9742` — internal surface: /internal/*, used for gossip
    //     and per-node activity reporting.
    // Checks split between the two accordingly. An explicit
    // override in sovereign-server.toml still wins for compatibility
    // with standalone Commonwealth deployments.
    let client_url = detect_commonwealth_url(sovereign_dir)
        .unwrap_or_else(|| "http://127.0.0.1:9741".to_string());
    // Resolved from `[daemon] internal_port`, not hardcoded: doctor probing the
    // default port while the daemon listens elsewhere reports a false "down".
    let internal_url = sovereign_core::setup_config::internal_daemon_base();
    // Supervision check runs UNCONDITIONALLY — outside the :9741
    // reachability gate below — because it matters most precisely
    // when the daemon is down: an unsupervised daemon that crashed is
    // the incident this check exists to prevent.
    results.push(check_daemon_supervised());
    if tcp_connectable("127.0.0.1", 9741).await {
        results.push(check_daemon_running().await);
        results.push(check_daemon_memory(&client_url).await);
        results.push(check_mesh_member(&client_url).await);
        results.push(check_iroh_egress(&client_url).await);
        results.push(check_inference_capable(&client_url).await);
        results.push(check_activity_reporting(&internal_url).await);
    }
    // else: daemon not running — skip layer silently

    // ── OmO layer (skip if `opencode` not in PATH) ───────────────
    let opencode_available = std::process::Command::new("which")
        .arg("opencode")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);

    if opencode_available {
        results.push(check_skill_file());
        results.push(check_opencode_config());
        results.push(check_mcp_live().await);
    }

    results
}

fn detect_commonwealth_url(sovereign_dir: &std::path::Path) -> Option<String> {
    // Read sovereign-server config to find commonwealth.url.
    let config_path = sovereign_dir.join("server.toml");
    if !config_path.exists() {
        return None;
    }
    let contents = std::fs::read_to_string(&config_path).ok()?;
    let table: toml::Value = toml::from_str(&contents).ok()?;
    table
        .get("commonwealth")
        .and_then(|c| c.get("url"))
        .and_then(|u| u.as_str())
        .map(|s| s.to_string())
}

// ── Output formatters ─────────────────────────────────────────────────────────

fn status_symbol(s: &CheckStatus) -> &'static str {
    match s {
        CheckStatus::Passed => "✓",
        CheckStatus::Failed => "✗",
        CheckStatus::Warning => "⚠",
        CheckStatus::Skipped => "–",
    }
}

fn print_human(results: &[CheckResult]) {
    let layers = [
        (Layer::Sovereign, "Sovereign"),
        (Layer::Commonwealth, "Commonwealth"),
        (Layer::Omo, "OmO"),
    ];

    let mut total_issues = 0usize;

    for (layer, label) in &layers {
        let layer_results: Vec<_> = results.iter().filter(|r| &r.layer == layer).collect();
        if layer_results.is_empty() {
            continue;
        }

        println!("\n  {label}:");
        for r in &layer_results {
            let sym = status_symbol(&r.status);
            println!("    {sym}  {}  —  {}", r.name, r.message);
            if r.status == CheckStatus::Failed || r.status == CheckStatus::Warning {
                match &r.repair {
                    Repair::Executable(cmd) | Repair::Manual(cmd) => {
                        println!("       → {cmd}");
                    }
                    Repair::MultiExecutable(cmds) => {
                        for cmd in cmds {
                            println!("       → {cmd}");
                        }
                    }
                    Repair::None => {}
                }
                if r.status == CheckStatus::Failed {
                    total_issues += 1;
                }
            }
        }
    }

    println!();
    if total_issues == 0 {
        println!("  All checks passed.");
    } else {
        println!("  {total_issues} issue(s) found. Run `svrn doctor --fix` to auto-repair where possible.");
    }
}

fn print_json(results: &[CheckResult]) {
    let issues: Vec<_> = results
        .iter()
        .filter(|r| r.status == CheckStatus::Failed)
        .collect();
    let out = serde_json::json!({
        "issues": issues.len(),
        "checks": results,
    });
    println!("{}", serde_json::to_string_pretty(&out).unwrap_or_default());
}

// ── Default config templates (embedded at compile time) ──────────────────────

const DEFAULT_TEST_RUNNER_TOML: &str = r#"
[test_runner]
command = "scripts/sovereign-test.sh"
working_dir = "."
timeout_secs = 120
debounce_ms = 2000
"#;

const DEFAULT_LINT_RUNNER_TOML: &str = r#"
[lint_runner]
command = "scripts/sovereign-lint.sh"
working_dir = "."
timeout_secs = 60
debounce_ms = 800
"#;

const SKILL_MD_TEMPLATE: &str = include_str!("../../../.opencode/skills/sovereign-code/SKILL.md");

// ── Inline repair helpers ─────────────────────────────────────────────────────

/// Write a default `.sovereign/sovereign.toml` with both runners configured,
/// appending only the sections that are missing when the file already exists.
fn attempt_write_runner_config(sovereign_dir: &std::path::Path) {
    let toml_path = sovereign_dir.join("sovereign.toml");
    if toml_path.exists() {
        let existing = std::fs::read_to_string(&toml_path).unwrap_or_default();
        let mut append = String::new();
        if !existing.contains("[test_runner]") {
            append.push_str(DEFAULT_TEST_RUNNER_TOML);
        }
        if !existing.contains("[lint_runner]") {
            append.push_str(DEFAULT_LINT_RUNNER_TOML);
        }
        if append.is_empty() {
            println!("  – runners: already configured, no changes needed");
            return;
        }
        match std::fs::OpenOptions::new()
            .append(true)
            .open(&toml_path)
            .and_then(|mut f| std::io::Write::write_all(&mut f, append.as_bytes()))
        {
            Ok(_) => println!("  ✓ runners: appended to {}", toml_path.display()),
            Err(e) => println!("  ✗ runners: could not write {}: {e}", toml_path.display()),
        }
        return;
    }
    if let Some(parent) = toml_path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let content = format!("{DEFAULT_TEST_RUNNER_TOML}{DEFAULT_LINT_RUNNER_TOML}");
    match std::fs::write(&toml_path, &content) {
        Ok(_) => println!("  ✓ runners: wrote {}", toml_path.display()),
        Err(e) => println!("  ✗ runners: could not write {}: {e}", toml_path.display()),
    }
}

/// Write the OmO SKILL.md to `.opencode/skills/sovereign-code/SKILL.md`.
///
/// Writes into the directory `check_skill_file` actually inspected when
/// there is one, falling back to cwd. They used to disagree — the check
/// walks UP from cwd, the writer always wrote INTO cwd — so running
/// `--fix` from a monorepo subdirectory could create a second skill dir
/// that the check would never look at.
fn attempt_write_skill_file() {
    let skill_dir = find_opencode_skill_dir().unwrap_or_else(|| {
        std::env::current_dir()
            .unwrap_or_else(|_| std::path::PathBuf::from("."))
            .join(".opencode")
            .join("skills")
            .join("sovereign-code")
    });
    if let Err(e) = std::fs::create_dir_all(&skill_dir) {
        println!(
            "  ✗ skill_file: could not create directory {}: {e}",
            skill_dir.display()
        );
        return;
    }
    let skill_md = skill_dir.join("SKILL.md");
    if skill_md.exists() {
        // Present but unloadable is the interesting case, and it is not
        // ours to silently overwrite — the user may have edited it.
        match std::fs::read_to_string(&skill_md) {
            Ok(body) => match skill_frontmatter_ok(&body) {
                Ok(()) => println!("  – skill_file: already valid at {}", skill_md.display()),
                Err(why) => println!(
                    "  – skill_file: {} exists but will not load ({why}); \
                     edit it or delete it and re-run --fix",
                    skill_md.display()
                ),
            },
            Err(e) => println!("  ✗ skill_file: cannot read {}: {e}", skill_md.display()),
        }
        return;
    }
    match std::fs::write(&skill_md, SKILL_MD_TEMPLATE) {
        Ok(_) => println!("  ✓ skill_file: wrote {}", skill_md.display()),
        Err(e) => println!(
            "  ✗ skill_file: could not write {}: {e}",
            skill_md.display()
        ),
    }
}

// ── Fix runner ────────────────────────────────────────────────────────────────

async fn run_fix(results: &[CheckResult], sovereign_dir: &std::path::Path) {
    let fixable: Vec<_> = results
        .iter()
        .filter(|r| r.status == CheckStatus::Failed || r.status == CheckStatus::Warning)
        .collect();

    if fixable.is_empty() {
        println!("  Nothing to auto-repair.");
        return;
    }

    // ── Executable repairs ────────────────────────────────────────
    for r in fixable
        .iter()
        .filter(|r| matches!(r.repair, Repair::Executable(_)))
    {
        let Repair::Executable(cmd) = &r.repair else {
            continue;
        };
        println!("  Repairing {}: {cmd}", r.name);
        let mut parts = cmd.splitn(2, ' ');
        let prog = parts.next().unwrap_or(cmd);
        let rest: Vec<&str> = parts
            .next()
            .map(|s| s.split_whitespace().collect())
            .unwrap_or_default();
        let status = std::process::Command::new(prog).args(&rest).status();
        match status {
            Ok(s) if s.success() => println!("  ✓ {} repaired", r.name),
            Ok(s) => println!("  ✗ {} repair exited {s}", r.name),
            Err(e) => println!("  ✗ {} repair failed: {e}", r.name),
        }
    }

    // ── MultiExecutable repairs (e.g. one per stale SCIP corpus) ─
    for r in fixable
        .iter()
        .filter(|r| matches!(r.repair, Repair::MultiExecutable(_)))
    {
        let Repair::MultiExecutable(cmds) = &r.repair else {
            continue;
        };
        println!("  Repairing {} ({} commands):", r.name, cmds.len());
        let mut all_ok = true;
        for cmd in cmds {
            println!("    {cmd}");
            let mut parts = cmd.splitn(2, ' ');
            let prog = parts.next().unwrap_or(cmd);
            let rest: Vec<&str> = parts
                .next()
                .map(|s| s.split_whitespace().collect())
                .unwrap_or_default();
            let status = std::process::Command::new(prog).args(&rest).status();
            match status {
                Ok(s) if s.success() => {}
                Ok(s) => {
                    println!("    ✗ exited {s}");
                    all_ok = false;
                }
                Err(e) => {
                    println!("    ✗ {e}");
                    all_ok = false;
                }
            }
        }
        if all_ok {
            println!("  ✓ {} repaired", r.name);
        }
    }

    // ── Inline repairs for checks that need file-writing logic ───
    let mut repaired_inline: Vec<&str> = Vec::new();
    for r in fixable.iter() {
        match r.name {
            "test_runner" | "lint_runner" => {
                attempt_write_runner_config(sovereign_dir);
                repaired_inline.push(r.name);
            }
            "skill_file" => {
                attempt_write_skill_file();
                repaired_inline.push(r.name);
            }
            _ => {}
        }
    }

    // ── Print manual hints ────────────────────────────────────────
    // Anything just repaired inline is excluded: printing "do X
    // yourself" directly under "✓ wrote X" is how `--fix` used to read.
    let manual: Vec<_> = fixable
        .iter()
        .filter(|r| matches!(r.repair, Repair::Manual(_)))
        .filter(|r| !repaired_inline.contains(&r.name))
        .collect();
    if !manual.is_empty() {
        println!("\n  Manual repairs needed:");
        for r in &manual {
            if let Repair::Manual(hint) = &r.repair {
                println!("    {}: {hint}", r.name);
            }
        }
    }
}

// ── Entry point ───────────────────────────────────────────────────────────────

const HELP: sovereign_cli_shared::help::Help = sovereign_cli_shared::help::Help {
    command: "svrn doctor",
    summary: "Diagnose setup and daemon health across the Sovereign / Commonwealth / OmO layers.",
    sections: &[
        sovereign_cli_shared::help::HelpSection::Usage("svrn doctor [--fix] [--watch] [--json]"),
        sovereign_cli_shared::help::HelpSection::Flags(&[
            ("--fix", "Attempt automatic repair for failing checks"),
            (
                "--watch",
                "Re-run periodically (every 5s) with a clear screen",
            ),
            (
                "--json",
                "Emit structured JSON (one object per check) for scripting",
            ),
        ]),
        sovereign_cli_shared::help::HelpSection::Notes(
            "Checks three layers: Sovereign (server, indexes, config), Commonwealth (daemon,\n\
             mesh, inference), OmO (skill file, MCP round-trip). Exit 0 = all pass (warnings\n\
             don't count), exit 1 = any failure.",
        ),
    ],
};

pub async fn run_doctor(args: &[String]) -> i32 {
    if sovereign_cli_shared::help::wants_help(args) {
        sovereign_cli_shared::help::print(&HELP);
        return 0;
    }
    let fix = args.iter().any(|a| a == "--fix");
    let watch = args.iter().any(|a| a == "--watch");
    let json = args.iter().any(|a| a == "--json");

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let sovereign_dir = find_sovereign_dir_or_cwd(&cwd);

    if watch {
        return run_watch(&sovereign_dir, json).await;
    }

    let results = run_checks(&sovereign_dir).await;

    if json {
        print_json(&results);
    } else {
        print_human(&results);
        if fix {
            println!("\n  Running repairs...");
            run_fix(&results, &sovereign_dir).await;
        }
    }

    let has_failures = results.iter().any(|r| r.status == CheckStatus::Failed);
    if has_failures {
        1
    } else {
        0
    }
}

fn find_sovereign_dir_or_cwd(cwd: &std::path::Path) -> PathBuf {
    let mut dir = cwd;
    loop {
        let candidate = dir.join(".sovereign");
        if candidate.exists() {
            return candidate;
        }
        match dir.parent() {
            Some(p) => dir = p,
            None => break,
        }
    }
    cwd.join(".sovereign")
}

async fn run_watch(sovereign_dir: &std::path::Path, json: bool) -> i32 {
    let is_tty = std::io::stdout().is_terminal();
    let mut prev_statuses: Vec<(&'static str, CheckStatus)> = Vec::new();

    loop {
        let results = run_checks(sovereign_dir).await;
        let now = {
            let secs = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs();
            let h = (secs / 3600) % 24;
            let m = (secs / 60) % 60;
            let s = secs % 60;
            format!("{h:02}:{m:02}:{s:02}")
        };

        // Diff against previous run.
        let changed: Vec<_> = results
            .iter()
            .filter(|r| {
                let prev = prev_statuses.iter().find(|(n, _)| *n == r.name);
                match prev {
                    None => true, // new check
                    Some((_, s)) => s != &r.status,
                }
            })
            .collect();

        if changed.is_empty() && !prev_statuses.is_empty() {
            if !json {
                println!("[{now}] No changes.");
            }
        } else {
            if is_tty && !json {
                // Clear screen for TTY.
                print!("\x1b[2J\x1b[H");
            }
            if json {
                let issues: Vec<_> = results
                    .iter()
                    .filter(|r| r.status == CheckStatus::Failed)
                    .collect();
                println!(
                    "{}",
                    serde_json::to_string(&serde_json::json!({
                        "timestamp": now.to_string(),
                        "issues": issues.len(),
                        "checks": &results,
                    }))
                    .unwrap_or_default()
                );
            } else {
                println!("[{now}] Changes:");
                let changed_owned: Vec<CheckResult> = changed.into_iter().cloned().collect();
                print_human(&changed_owned);
            }
        }

        prev_statuses = results.iter().map(|r| (r.name, r.status.clone())).collect();
        tokio::time::sleep(Duration::from_secs(30)).await;
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn atos replay` — reconstruct a historical commit as an
//! ATOS Runner task.
//!
//! Flow:
//!   1. Resolve the commit's parent SHA and verify both exist.
//!   2. Check out a fresh branch at the parent SHA.
//!   3. Ask the Fast slot to synthesize `DESIGN.md` + `CHARTER.md`
//!      from the commit message and diff — what the design WOULD have
//!      looked like before the commit.
//!   4. Hand off to `svrn atos run` with the synthesized artifacts
//!      in the workdir; the existing drive loop runs unchanged.
//!
//! After the loop terminates, `git diff <parent_sha>..<commit_sha>` is
//! the ground-truth comparison for the `sovereign-eval scope` analyzer
//! — a future `--score` flag wires this in.
//!
//! See `sovereign/docs/ATOS_RUNNER.md` § replay primitive.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

use super::args::{get_flag, split_args};

const DEFAULT_SYNTH_MODEL: &str = "commonwealth/primary";
const DEFAULT_DAEMON_URL: &str = "http://localhost:9741";
const SYNTH_MAX_TOKENS: u32 = 4096;
const SYNTH_TEMPERATURE: f32 = 0.0;
const SYNTH_SEED: u64 = 0xA705;
const SYNTH_TIMEOUT_SECS: u64 = 600;
/// Diffs above this size get truncated before being shown to the
/// synthesizer — the goal is intent recovery, not byte-perfect echo.
const MAX_DIFF_BYTES: usize = 64 * 1024;

pub async fn cmd_replay(args: &[String]) -> i32 {
    let (_positional, flags) = split_args(args);

    let commit = match get_flag(&flags, "--commit") {
        Some(s) => s,
        None => {
            eprintln!("atos replay: missing --commit <sha>");
            print_help();
            return 2;
        }
    };
    let workdir = match get_flag(&flags, "--workdir") {
        Some(s) => PathBuf::from(s),
        None => {
            eprintln!("atos replay: missing --workdir <path>");
            print_help();
            return 2;
        }
    };
    if !workdir.is_dir() {
        eprintln!(
            "atos replay: --workdir is not a directory: {}",
            workdir.display()
        );
        return 2;
    }

    let driver = get_flag(&flags, "--driver").unwrap_or_else(|| "opencode".to_string());
    let daemon_url =
        get_flag(&flags, "--daemon-url").unwrap_or_else(|| DEFAULT_DAEMON_URL.to_string());
    let synth_model =
        get_flag(&flags, "--synth-model").unwrap_or_else(|| DEFAULT_SYNTH_MODEL.to_string());
    let custom_branch = get_flag(&flags, "--branch-name");
    let dry_run = flags.iter().any(|(k, _)| k == "dry-run");
    let max_iters = get_flag(&flags, "--max-iters").unwrap_or_else(|| "8".to_string());

    println!("atos replay: workdir = {}", workdir.display());
    println!("  commit       = {commit}");
    println!("  driver       = {driver}");
    println!("  synth model  = {synth_model}");

    // ── 1. Resolve commit + parent SHA ───────────────────────────
    let commit_sha = match git_rev_parse(&workdir, &commit) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot resolve commit `{commit}`: {e}");
            return 1;
        }
    };
    let parent_sha = match git_rev_parse(&workdir, &format!("{commit_sha}^")) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot resolve parent of `{commit_sha}`: {e}");
            return 1;
        }
    };
    println!("  parent       = {parent_sha}");
    println!("  target       = {commit_sha}");

    // ── 2. Read commit message + diff BEFORE checking out ────────
    let commit_message = match git_commit_message(&workdir, &commit_sha) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot read commit message: {e}");
            return 1;
        }
    };
    let mut diff_text = match git_diff(&workdir, &parent_sha, &commit_sha) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: cannot compute diff: {e}");
            return 1;
        }
    };
    let diff_truncated = diff_text.len() > MAX_DIFF_BYTES;
    if diff_truncated {
        diff_text.truncate(MAX_DIFF_BYTES);
        diff_text.push_str("\n... (diff truncated)\n");
    }
    let changed_files = match git_changed_files(&workdir, &parent_sha, &commit_sha) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("atos replay: cannot list changed files: {e}");
            return 1;
        }
    };
    println!(
        "  diff         = {} bytes ({} files){}",
        diff_text.len(),
        changed_files.len(),
        if diff_truncated { " [truncated]" } else { "" }
    );

    // ── 3. Check out a fresh branch at parent SHA ────────────────
    let branch_name = custom_branch.unwrap_or_else(|| {
        let short = &commit_sha[..7.min(commit_sha.len())];
        let stamp = chrono::Utc::now().format("%Y%m%d%H%M%S");
        format!("atos-replay-{short}-{stamp}")
    });
    if let Err(e) = git_checkout_new_branch(&workdir, &branch_name, &parent_sha) {
        eprintln!("atos replay: branch checkout failed: {e}");
        return 1;
    }
    println!("  branch       = {branch_name} @ {parent_sha}");

    // ── 4. Fast slot synthesizes DESIGN.md and CHARTER.md ────────
    let design_md = match synthesize_design(
        &daemon_url,
        &synth_model,
        &commit_message,
        &diff_text,
        &changed_files,
    )
    .await
    {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: design synthesis failed: {e}");
            return 1;
        }
    };
    let charter_md = match synthesize_charter(
        &daemon_url,
        &synth_model,
        &commit_message,
        &diff_text,
        &changed_files,
    )
    .await
    {
        Ok(s) => s,
        Err(e) => {
            eprintln!("atos replay: charter synthesis failed: {e}");
            return 1;
        }
    };

    let design_path = workdir.join("DESIGN.md");
    let charter_path = workdir.join("CHARTER.md");
    if let Err(e) = std::fs::write(&design_path, &design_md) {
        eprintln!("atos replay: write {}: {e}", design_path.display());
        return 1;
    }
    if let Err(e) = std::fs::write(&charter_path, &charter_md) {
        eprintln!("atos replay: write {}: {e}", charter_path.display());
        return 1;
    }
    println!(
        "  design       = {} ({} bytes)",
        design_path.display(),
        design_md.len()
    );
    println!(
        "  charter      = {} ({} bytes)",
        charter_path.display(),
        charter_md.len()
    );

    // Snapshot the synthesized artifacts to the runs dir for triage.
    // The actual run-id is allocated by `cmd_run`, so write to a
    // sidecar keyed by branch_name; operators can correlate via the
    // branch name printed above.
    let sidecar = sovereign_root()

        .join("replay-synth")
        .join(&branch_name);
    let _ = std::fs::create_dir_all(&sidecar);
    let _ = std::fs::write(sidecar.join("DESIGN.md"), &design_md);
    let _ = std::fs::write(sidecar.join("CHARTER.md"), &charter_md);
    let _ = std::fs::write(sidecar.join("commit_message.txt"), &commit_message);
    let _ = std::fs::write(sidecar.join("diff.patch"), &diff_text);

    if dry_run {
        println!("\natos replay: --dry-run set — synthesized artifacts only, not spawning driver.");
        println!("  synth dir  = {}", sidecar.display());
        return 0;
    }

    // ── 5. Delegate to `svrn atos run` ──────────────────────
    let workdir_str = workdir.to_string_lossy().to_string();
    let run_args = vec![
        "--workdir".to_string(),
        workdir_str,
        "--driver".to_string(),
        driver,
        "--max-iters".to_string(),
        max_iters,
        "--daemon-url".to_string(),
        daemon_url,
    ];
    super::run::cmd_run(&run_args).await
}

// ─── Synthesis prompts ───────────────────────────────────────────

const DESIGN_SYNTH_SYSTEM: &str = "You are an architect drafting a DESIGN.md for a software change. \
Output ONLY the markdown body — no surrounding prose, no fences, no commentary. \
The document should describe what the change accomplishes, the load-bearing anchors (files / functions / interfaces affected), and the success conditions a reviewer would check. \
Write it as if BEFORE the change was implemented — describe intent, not what happened.";

const CHARTER_SYNTH_SYSTEM: &str = "You are drafting a CHARTER.md that constrains an agent implementing the change described. \
Output ONLY the markdown body — no surrounding prose, no fences, no commentary. \
Include a `**Stop condition:**` line whose value is a single shell command that mechanically verifies the change. \
Prefer a `cargo test` / `cargo check` invocation scoped to the affected crate(s) when tests changed; otherwise use `cargo check --workspace`. \
Include short subsections on scope, out-of-scope, and what the reviewer should reject.";

async fn synthesize_design(
    daemon_url: &str,
    model: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> Result<String, String> {
    let user_prompt =
        build_synth_user_prompt("DESIGN.md", commit_message, diff_text, changed_files);
    call_synth(daemon_url, model, DESIGN_SYNTH_SYSTEM, &user_prompt).await
}

async fn synthesize_charter(
    daemon_url: &str,
    model: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> Result<String, String> {
    let user_prompt =
        build_synth_user_prompt("CHARTER.md", commit_message, diff_text, changed_files);
    call_synth(daemon_url, model, CHARTER_SYNTH_SYSTEM, &user_prompt).await
}

fn build_synth_user_prompt(
    artifact: &str,
    commit_message: &str,
    diff_text: &str,
    changed_files: &[String],
) -> String {
    let files_list = if changed_files.is_empty() {
        "(none listed)".to_string()
    } else {
        changed_files
            .iter()
            .map(|f| format!("- {f}"))
            .collect::<Vec<_>>()
            .join("\n")
    };
    format!(
        "Draft a {artifact} that an agent could implement against this codebase to reproduce the change described below.\n\n\
         ## Commit message\n\n{commit_message}\n\n\
         ## Files changed\n\n{files_list}\n\n\
         ## Diff (may be truncated)\n\n```\n{diff_text}\n```\n"
    )
}

async fn call_synth(
    daemon_url: &str,
    model: &str,
    system: &str,
    user: &str,
) -> Result<String, String> {
    let url = format!("{}/v1/chat/completions", daemon_url.trim_end_matches('/'));
    let body = serde_json::json!({
        "model": model,
        "temperature": SYNTH_TEMPERATURE,
        "top_p": 1.0,
        "max_tokens": SYNTH_MAX_TOKENS,
        "seed": SYNTH_SEED,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ],
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(SYNTH_TIMEOUT_SECS))
        .build()
        .map_err(|e| format!("build http client: {e}"))?;
    let resp = client
        .post(&url)
        .json(&body)
        .send()
        .await
        .map_err(|e| format!("POST /v1/chat/completions: {e}"))?;
    if !resp.status().is_success() {
        let status = resp.status();
        let text = resp.text().await.unwrap_or_default();
        return Err(format!(
            "daemon returned {status}: {}",
            text.chars().take(1024).collect::<String>()
        ));
    }
    let v: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| format!("parse daemon response: {e}"))?;
    let content = v
        .pointer("/choices/0/message/content")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();
    if content.is_empty() {
        return Err("daemon returned empty content".into());
    }
    Ok(content)
}

// ─── Git helpers ─────────────────────────────────────────────────

fn git_rev_parse(workdir: &Path, refspec: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("rev-parse")
        .arg("--verify")
        .arg(refspec)
        .output()
        .map_err(|e| format!("spawn git: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

fn git_commit_message(workdir: &Path, sha: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("log")
        .arg("-1")
        .arg("--format=%B")
        .arg(sha)
        .output()
        .map_err(|e| format!("spawn git log: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

fn git_diff(workdir: &Path, base: &str, head: &str) -> Result<String, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("diff")
        .arg(format!("{base}..{head}"))
        .output()
        .map_err(|e| format!("spawn git diff: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

fn git_changed_files(workdir: &Path, base: &str, head: &str) -> Result<Vec<String>, String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("diff")
        .arg("--name-only")
        .arg(format!("{base}..{head}"))
        .output()
        .map_err(|e| format!("spawn git diff --name-only: {e}"))?;
    if !out.status.success() {
        return Err(String::from_utf8_lossy(&out.stderr).trim().to_string());
    }
    Ok(String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(str::to_string)
        .collect())
}

fn git_checkout_new_branch(workdir: &Path, branch: &str, base_sha: &str) -> Result<(), String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(workdir)
        .arg("checkout")
        .arg("-b")
        .arg(branch)
        .arg(base_sha)
        .output()
        .map_err(|e| format!("spawn git checkout: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "git checkout -b {branch} {base_sha}: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    Ok(())
}

fn home_dir() -> PathBuf {
    std::env::var("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("/tmp"))
}

fn print_help() {
    eprintln!(
        "svrn atos replay — reconstruct a historical commit as a Runner task\n\
         \n\
         USAGE\n    sovereign atos replay --commit <sha> --workdir <repo> [flags]\n\
         \n\
         REQUIRED\n\
         \x20   --commit <sha>          The historical commit whose work the agent should reproduce.\n\
         \x20   --workdir <path>        Path to the git repo containing the commit.\n\
         \n\
         OPTIONAL\n\
         \x20   --driver opencode|claude  Driver to use (default: opencode).\n\
         \x20   --branch-name <name>      Override the auto-generated branch name.\n\
         \x20   --synth-model <id>        Model to synthesize DESIGN.md + CHARTER.md (default: commonwealth/primary).\n\
         \x20   --daemon-url <url>        Daemon base URL (default: http://localhost:9741).\n\
         \x20   --max-iters <N>           Max Runner iterations (default: 8).\n\
         \x20   --dry-run                 Synthesize artifacts only; don't spawn the driver.\n"
    );
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Measured throughput for one model on one mesh split — recorded, never
//! estimated.
//!
//! `svrn mesh plan` answers "will this model fit on my machines" from a GGUF
//! header parse alone: offline, no GPU, instant even on a 400 GB split. The
//! question it could not answer is "what will it feel like." This module is the
//! memory that lets it answer — and, just as importantly, the structure that
//! keeps it from *making the answer up*.
//!
//! ## The design rule: measure, don't predict
//!
//! Nothing here estimates. A record is written only after a real run against a
//! real placement, and it is served back only for the *exact* configuration it
//! was taken on. Where there is no record, the honest output is "not measured"
//! plus the command that would measure it — never an interpolation between
//! records that do exist.
//!
//! That rule is not caution for its own sake. `SCHEDULER_QUALITY.md` §4.5
//! priced the alternative against the simulator: a throughput number
//! extrapolated from a baseline probe onto a differently-sized model reads
//! −56%, doubles declined upgrades, and is filed **DO-NOT-BUILD**. The live
//! extrapolator is `throughput_factor` (`oicp-types/src/scoring.rs:384`), and it
//! is already wired end to end — the only thing keeping it dark is that nothing
//! populates `NodeCapabilities.benchmark`. See the guard test
//! `gossip_never_advertises_a_benchmark` in `sovereign-mesh`.
//!
//! **These records must never reach that field.** They are a different thing
//! for a different consumer: §4.5 measured a number's worth to the scheduler's
//! automatic ranked dispatch, through a clamp that only carries information
//! about nodes slower than the reference rate. These records are read by a
//! *person* deciding whether to add a machine, move the host role, or buy
//! hardware. That person has no clamp, and a number worth 0% to a ranker can be
//! decisive for them.
//!
//! Note what [`MeasurementRecord`] deliberately does **not** carry: any model
//! size. There is nothing here from which a size ratio could be computed, so
//! re-deriving the banned extrapolation would require first *adding a field* —
//! a reviewable act, rather than a one-line temptation.
//!
//! ## Why the key has exactly these five parts
//!
//! A cache key that is too coarse fabricates; one that is too fine never hits.
//! Each field of [`MeasurementKey`] is here because dropping it would serve a
//! real number for a configuration it was not measured on:
//!
//! | Field | Drop it and… |
//! |---|---|
//! | `model_fingerprint` | a Q4 number is shown for a Q8 plan |
//! | `placement_digest` | a 36/12 split's number is shown for a 24/24 plan |
//! | `host_hw_fingerprint` | one machine's number is shown on another's |
//! | `n_ctx` | an 8k number is shown for a 128k plan (decode rate tracks KV size) |
//! | `probe_version` | numbers taken by different methods are compared as equals |
//! | `link` | a tunnelled number is shown for a direct-IP plan (a 2.3× error) |
//!
//! And what is deliberately *excluded*: RPC endpoint ports (DHCP churn would
//! make every lookup a miss), and the probe's prompt text and token counts
//! (they are protocol constants folded into `probe_version`, not key fields —
//! keying on them would drive the hit rate to zero).
//!
//! `link` is the newest of the six and was added after the other five were
//! already in service, so it is worth saying why it earns its place. It is the
//! only key field that can change *without anything on either machine
//! changing*: the same model, the same split, the same silicon, reached over a
//! different path. Measured on this fleet, the same 4B distributed decode read
//! 17.35 tok/s over a forced iroh tunnel and ~40 tok/s over direct IP — a 2.3×
//! spread from link choice alone, larger than most of what the other five
//! fields guard against. Before it existed those two runs shared a key and the
//! later one silently answered for both. See [`LinkClass`].
//!
//! The GPU backend is folded *inside* `host_hw_fingerprint` rather than sitting
//! beside it, because a ROCm↔Vulkan swap shifts throughput materially on
//! identical silicon without changing the GPU's name — so it has to break the
//! key, not merely annotate it.
//!
//! Peer hardware is covered the same way, one level down. `host_hw_fingerprint`
//! pins only the machine that *ran* the probe; the machines that held the rest
//! of the model are described by `placement_digest`, so each
//! [`PlacementShard`] carries its own [`hw`](PlacementShard::hw) fingerprint
//! and the digest changes when a peer's silicon does. Until 2026-07-29 a shard
//! was identified by mesh *name* alone, so a peer that swapped a GPU for a
//! different one of the same capacity — or merely flipped Vulkan↔ROCm — kept
//! every key it had ever filed, and the old number answered for the new
//! machine. A name is not hardware.
//!
//! Where a machine advertises no fingerprint (a peer on an older daemon), the
//! callers do not fall back to a name-only key: `mesh plan` reports "not
//! measured" and `mesh bench` refuses to file. An unattributable record is
//! worse than a missing one, because only the missing one admits what it does
//! not know.
//!
//! ## The key is an identity, not a description
//!
//! Both digests in the key are one-way. That is the right shape for [`lookup`],
//! which asks only "is this the same configuration" — but it means a record can
//! state a number without being able to say what the number was *for*. On
//! 2026-07-30 two runs of this fleet, four hours apart, filed under different
//! placement digests with identical human labels, and an exhaustive search over
//! every integer split of the model across both machines — both range orders,
//! either machine holding the output head, every known peer fingerprint — could
//! not reconstruct what the earlier one had described. Nothing was corrupt. The
//! pre-image had simply never been kept.
//!
//! So every hashed component of the key has a witness beside it:
//! [`PlacementWitness`] holds the exact inputs the digest was computed from, and
//! [`MachineWitness`] says what each named machine is in terms a person can
//! weigh. The witness is checkable against the hash it explains
//! ([`PlacementWitness::explains`]) and is ignored where it does not match, so
//! it can be trusted without being believed.
//!
//! This matters most for the case the key is worst at. A key pins the exact
//! split *and* the exact silicon, so two operators with genuinely comparable
//! machines will essentially never share one. Exactness is right — it is what
//! stops a number being served for a configuration nobody ran — but it makes
//! [`near_misses`] the surface that actually answers the question, and a near
//! miss is only worth reading if it can say *how* the other configuration
//! differed. [`Difference`] is that answer.
//!
//! ## Storage
//!
//! `~/.sovereign/mesh-measurements.json`. `SOVEREIGN_MESH_MEASUREMENTS=<path>`
//! relocates it; `SOVEREIGN_MESH_MEASUREMENTS=0` disables reads and writes
//! entirely. Records are append-only per key, capped at [`MAX_RUNS_PER_KEY`]
//! (FIFO) so repeated runs make variance *visible* rather than averaging it
//! away — a thermally-throttled or link-jittery machine should look unstable,
//! not merely slow.
//!
//! There is no time-based expiry. A measurement does not rot: the hardware that
//! produced it is pinned in the key. What can change underneath it is the
//! inference engine, so every record stamps the build that took it and
//! [`lookup`] flags a mismatch as stale rather than discarding it. Silently
//! dropping a record would cost the operator a re-measurement for nothing;
//! silently refreshing it would spend twenty minutes they did not ask for.
//! Showing the age and letting them judge is the whole premise of the tool.
//!
//! ## Travel
//!
//! A measurement is worth most to the machine that did not take it: locally it
//! recalls what a run felt like, on a peer it answers what a configuration
//! *would* feel like on hardware the reader cannot try. Records therefore
//! gossip, under [`MEASUREMENTS_APP_ID`], as versioned [`to_wire`] envelopes.
//!
//! Two rules keep that from undoing everything above. Peer records never enter
//! [`MeasurementFile`], so [`lookup`] still answers only "what did *this*
//! machine measure" and no peer's number can be served as the reader's own; and
//! every peer record reaches the operator through [`near_misses`] carrying
//! [`NearMiss::taken_by`], so it is named as someone else's. Invalid runs do not
//! travel at all ([`to_wire`] refuses them) — a failure is glassbox material for
//! the operator who caused it and noise to everyone else.
//!
//! The mesh KV store is a wire buffer, not storage: it is in-memory in the
//! daemon and empties on restart. The durable file stays authoritative and the
//! daemon republishes it at boot. See the `Travel` section below.

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::path::PathBuf;

/// Bumped when the probe protocol changes in any way that makes new numbers
/// incomparable with old ones: the prompt, the token budget, the timing
/// formula, or the set of validity guards. Old records then stop matching
/// rather than being silently compared against numbers taken differently.
pub const PROBE_VERSION: u32 = 1;

/// Bumped when the on-disk layout changes incompatibly. A file at a different
/// version is discarded wholesale.
///
/// v2 (2026-07-29) added [`MeasurementKey::link`]. Discarding rather than
/// migrating is the honest option: a v1 record does not say which link it was
/// taken over, and there is no way to recover that after the fact. Defaulting
/// them to any concrete [`LinkClass`] would assert something nobody measured,
/// and defaulting them to `Unknown` would keep rows that can never match. They
/// are dropped, and the operator re-measures.
const SCHEMA_VERSION: u32 = 2;

/// Per-key run cap. Keeps variance visible without unbounded growth.
pub const MAX_RUNS_PER_KEY: usize = 8;

// ---------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------

/// Proof that a real, present host was identified — the token
/// [`MeasurementKey::for_plan`] requires.
///
/// This exists to make one rule structural instead of conventional: **a
/// hypothetical mesh can never match a measurement.** `svrn mesh plan
/// --devices 64,32,32` describes hardware that is not here, so there is no host
/// to fingerprint and no measurement that could honestly apply to it. Rather
/// than rely on a runtime `if` that a later refactor could drop, the key simply
/// cannot be *constructed* without this value, and the only way to obtain one
/// is [`HostIdentity::from_live_mesh`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HostIdentity(u64);

impl HostIdentity {
    /// Identify the host from a fingerprint read off the live mesh.
    ///
    /// `None` when the host advertises no fingerprint — an older peer, or a
    /// node whose hardware detection came up empty. A caller that gets `None`
    /// must report "not measured" rather than substituting a placeholder:
    /// a shared default would collide every unidentified host into one key.
    pub fn from_live_mesh(hw_fingerprint: Option<u64>) -> Option<Self> {
        hw_fingerprint.map(Self)
    }

    /// The underlying fingerprint, for display and JSON emission.
    pub fn fingerprint(self) -> u64 {
        self.0
    }
}

/// Stable hash of one machine's hardware.
///
/// Small on purpose — this needs equality against a previously recorded value,
/// not cryptographic uniqueness. `gpus` is `(name, vram_gb, backend)`, and the
/// backend string is part of the hash because the same silicon driven through
/// different backends is, for throughput purposes, different hardware.
///
/// Order-independent across GPUs: the same two cards enumerated in either order
/// hash identically, so a driver-order change does not invalidate a record.
pub fn hardware_fingerprint(
    cpu_cores: u32,
    system_ram_gb: u32,
    gpus: &[(String, u32, String)],
) -> u64 {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};

    // Hash each GPU independently, then combine with a commutative fold so
    // enumeration order cannot change the result.
    let mut gpu_mix: u64 = 0;
    for (name, vram_gb, backend) in gpus {
        let mut g = DefaultHasher::new();
        name.hash(&mut g);
        vram_gb.hash(&mut g);
        backend.hash(&mut g);
        gpu_mix ^= g.finish();
    }

    let mut h = DefaultHasher::new();
    cpu_cores.hash(&mut h);
    system_ram_gb.hash(&mut h);
    gpus.len().hash(&mut h);
    gpu_mix.hash(&mut h);
    h.finish()
}

/// Fingerprint a model from its GGUF tensor table — `"mf1:<16 hex>"`.
///
/// `sizes` is the `(tensor_name, layer, nbytes)` table that `mesh plan` already
/// parses; only name and byte count participate. Properties that matter:
///
/// - **Order-independent.** The table is sorted before hashing, so two reads of
///   the same file agree regardless of enumeration order.
/// - **Quantisation-sensitive.** Byte counts are hashed, so Q4 and Q8 of the
///   same model are different models here — which is the point.
/// - **Rename-proof.** Nothing about the file's path or name is included.
/// - **Free.** This is a header parse the caller has already done.
pub fn model_fingerprint(sizes: &[(String, Option<u32>, u64)], block_count: u32) -> String {
    let mut rows: Vec<(&str, u64)> = sizes.iter().map(|(n, _, b)| (n.as_str(), *b)).collect();
    rows.sort_unstable();

    let mut h = Sha256::new();
    h.update(b"mf1");
    h.update(block_count.to_le_bytes());
    h.update((rows.len() as u64).to_le_bytes());
    for (name, nbytes) in &rows {
        h.update(name.as_bytes());
        h.update([0u8]); // delimiter: "ab"+"c" must not collide with "a"+"bc"
        h.update(nbytes.to_le_bytes());
    }
    format!("mf1:{}", hex16(&h.finalize()))
}

/// One device's share of a placement, as the digest sees it.
///
/// Serialisable because [`PlacementWitness`] stores these verbatim: a witness
/// that paraphrased the digest's inputs could not be checked against the digest,
/// which is the only thing that makes it worth trusting.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PlacementShard {
    /// Stable identity of the machine holding this share.
    ///
    /// Callers pass a mesh member *name* where the RPC endpoint resolves to a
    /// known peer, and an endpoint host with the port dropped otherwise. Ports
    /// must not appear: they churn across restarts and would make every lookup
    /// a miss.
    pub node_key: String,
    /// The fingerprint of the silicon behind `node_key`.
    ///
    /// A name is not hardware. A peer that swaps a GPU for a different one of
    /// the same capacity, or flips its backend between Vulkan and ROCm, keeps
    /// its mesh name and every name-only key it ever filed — so the old number
    /// answers for the new machine. This field is what makes the digest notice.
    /// It is deliberately *beside* `node_key` rather than concatenated into it,
    /// because `node_key` is also the mesh-member name used to look a peer up in
    /// the live mesh and to label it in human output; hashing hardware into that
    /// string would break both.
    ///
    /// `None` means the machine did not advertise one (a peer on an older
    /// daemon). Both callers refuse to build a key in that case rather than
    /// filing under a shard they cannot attribute — see
    /// [`hardware_fingerprint`]. It is still encoded distinctly from any `Some`
    /// so the two can never collide in the digest.
    pub hw: Option<u64>,
    /// Inclusive block range this device holds, or `None` if it holds none.
    pub blocks: Option<(u32, u32)>,
    /// Whether this device carries the output head.
    pub holds_output: bool,
}

/// Fingerprint a placement — `"pd2:<16 hex>"`.
///
/// `mode` distinguishes a single-machine load from a split one, so the same
/// model measured solo and measured distributed are never confused. Shards are
/// sorted by `node_key`, making the digest independent of the order the mesh
/// happened to enumerate its members.
///
/// The prefix is a *generation*, not decoration. `pd1` hashed a shard as
/// name + blocks + output-head; `pd2` also hashes [`PlacementShard::hw`], so
/// the same inputs produce a different digest under the two schemes. Bumping it
/// means a stored `pd1:` digest is visibly from the older construction instead
/// of being silently un-matchable bytes wearing the same label.
pub fn placement_digest(mode: &str, total_blocks: u32, shards: &[PlacementShard]) -> String {
    let mut sorted: Vec<&PlacementShard> = shards.iter().collect();
    sorted.sort_unstable_by(|a, b| a.node_key.cmp(&b.node_key));

    let mut h = Sha256::new();
    h.update(b"pd2");
    h.update(mode.as_bytes());
    h.update([0u8]);
    h.update(total_blocks.to_le_bytes());
    h.update((sorted.len() as u64).to_le_bytes());
    for s in sorted {
        h.update(s.node_key.as_bytes());
        h.update([0u8]);
        // Tagged, so "no fingerprint" cannot hash the same as any real one.
        match s.hw {
            Some(fp) => {
                h.update([1u8]);
                h.update(fp.to_le_bytes());
            }
            None => h.update([0u8]),
        }
        match s.blocks {
            Some((lo, hi)) => {
                h.update([1u8]);
                h.update(lo.to_le_bytes());
                h.update(hi.to_le_bytes());
            }
            None => h.update([0u8]),
        }
        h.update([u8::from(s.holds_output)]);
    }
    format!("pd2:{}", hex16(&h.finalize()))
}

fn hex16(digest: &[u8]) -> String {
    digest[..8].iter().map(|b| format!("{b:02x}")).collect()
}

// ---------------------------------------------------------------------------
// Witness — the pre-image of a digest
// ---------------------------------------------------------------------------

/// What one machine in a placement *is*, in terms a reader can act on.
///
/// A [`hardware_fingerprint`] is deliberately a small opaque hash: it answers
/// "is this the same machine" and is not meant to be read. That is enough on the
/// machine that took the measurement, where the operator already knows what
/// their own hardware is. It is not enough anywhere else — a reader shown
/// `host_hw_fingerprint: 7602642063143971880` learns nothing they can weigh.
///
/// **Descriptive only, and deliberately not a rate.** `vram_gb` is a capacity
/// and `backend` is a label; neither is a throughput figure, so neither can be
/// divided by another machine's to scale a measured number onto it. That
/// restraint is the same one the module docs describe for model size: the banned
/// extrapolation of `SCHEDULER_QUALITY.md` §4.5 needs a rate or a size to divide
/// by, and adding one here would be a reviewable act rather than an accident.
/// Anything added to this struct should pass the same test.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MachineWitness {
    /// The [`PlacementShard::node_key`] this describes.
    pub node_key: String,
    /// Total advertised GPU memory in GB, summed across the machine's cards.
    pub vram_gb: u32,
    /// Advertised GPU backend (`cuda` | `rocm` | `metal` | `vulkan`), when the
    /// machine said. Folded into the fingerprint, so it is also part of why two
    /// otherwise-identical machines key differently.
    pub backend: Option<String>,
}

impl MachineWitness {
    /// One-line description, e.g. `"51 GB vulkan"`.
    pub fn describe(&self) -> String {
        match &self.backend {
            Some(b) => format!("{} GB {b}", self.vram_gb),
            None => format!("{} GB", self.vram_gb),
        }
    }
}

/// The inputs a [`placement_digest`] was computed from.
///
/// A digest is a lossy projection. It answers "is this the same configuration"
/// and nothing else, which is exactly what [`lookup`] needs — an equality test
/// between keys written and read on the same machine. It is not enough for
/// anything that has to *explain* a configuration to a reader who did not run
/// it, and that is every other use these records have:
///
/// - Two of this machine's own records land under different keys, and the
///   operator asks which one describes what they are running now. Without the
///   pre-image this is unanswerable: on 2026-07-30 an exhaustive search over
///   every integer split of a 48-block model across both machines of this fleet,
///   in both range orders, with either machine holding the output head, and
///   every known peer fingerprint substituted, failed to reconstruct what a
///   digest recorded four hours earlier had described. The number was still
///   there; what it was a number *for* was gone.
/// - A [`NearMiss`] has to say how the measured configuration differs from the
///   one being planned, concretely enough for the reader to judge relevance.
///   `differs_by: ["split"]` does not clear that bar.
/// - A record that travelled from another machine, where an exact key hit is
///   vanishingly unlikely — the key pins the exact split *and* the exact
///   silicon — so the near miss is not a courtesy, it is the entire value.
///
/// The witness is therefore kept beside the hash rather than derived from it.
/// What makes it trustworthy is that it is *checkable*: [`Self::explains`]
/// re-runs [`placement_digest`] over these exact fields, so a witness that does
/// not account for the digest it sits next to can be detected rather than
/// believed.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PlacementWitness {
    /// The `mode` string that was hashed — `"local"` or `"distributed"`.
    pub mode: String,
    /// The `total_blocks` that was hashed.
    pub total_blocks: u32,
    /// Exactly the shards that were hashed. Order is immaterial:
    /// [`placement_digest`] sorts by `node_key`.
    pub shards: Vec<PlacementShard>,
    /// What each named machine is. Never hashed — a description changing must
    /// not change a configuration's identity, or improving what a peer
    /// advertises would silently orphan every record naming it.
    #[serde(default)]
    pub machines: Vec<MachineWitness>,
}

impl PlacementWitness {
    /// The digest these inputs produce.
    pub fn digest(&self) -> String {
        placement_digest(&self.mode, self.total_blocks, &self.shards)
    }

    /// Whether this witness accounts for `digest`.
    ///
    /// A `false` here means the producer built the witness and the key from
    /// different inputs — a bug in the writer, not in the reader, and one worth
    /// surfacing rather than papering over: a witness that explains the wrong
    /// configuration is more misleading than no witness at all.
    pub fn explains(&self, digest: &str) -> bool {
        self.digest() == digest
    }

    /// The description of one named machine, when it was recorded.
    pub fn machine(&self, node_key: &str) -> Option<&MachineWitness> {
        self.machines.iter().find(|m| m.node_key == node_key)
    }

    /// The machine carrying `hw`, by fingerprint rather than by name — how the
    /// host is located, since [`MeasurementKey::host_hw_fingerprint`] names
    /// silicon and not a mesh member.
    pub fn machine_with_hw(&self, hw: u64) -> Option<&MachineWitness> {
        let shard = self.shards.iter().find(|s| s.hw == Some(hw))?;
        self.machine(&shard.node_key)
    }

    /// The split, as a line a reader can compare against another —
    /// e.g. `"BeefyMac 12 · RuggedFox 36 +head"`.
    ///
    /// Block *counts*, not ranges: which end of the model a machine holds is
    /// part of the identity (and so part of the digest), but a reader deciding
    /// where to put weight is asking how much each machine carries.
    pub fn describe_split(&self) -> String {
        let mut sorted: Vec<&PlacementShard> = self.shards.iter().collect();
        sorted.sort_unstable_by(|a, b| a.node_key.cmp(&b.node_key));
        sorted
            .iter()
            .map(|s| {
                let held = match s.blocks {
                    Some((lo, hi)) => format!("{}", hi.saturating_sub(lo) + 1),
                    None => "idle".to_string(),
                };
                let head = if s.holds_output { " +head" } else { "" };
                format!("{} {held}{head}", s.node_key)
            })
            .collect::<Vec<_>>()
            .join(" · ")
    }
}

// ---------------------------------------------------------------------------
// Link
// ---------------------------------------------------------------------------

/// How the host reaches the machines holding the rest of the model.
///
/// The tensor stream is raw TCP to each worker's rpc-server, so this is a
/// property of *the endpoint ggml dials*, not of the peer's identity. The same
/// peer is [`Direct`](LinkClass::Direct) when discovery found a routable
/// address for it and [`Tunnel`](LinkClass::Tunnel) when it fell back to a
/// loopback proxy whose far end is an iroh tunnel. Which of those happens is
/// decided by network conditions on the day, not by configuration — which is
/// exactly why it has to be in the key rather than in a comment.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LinkClass {
    /// No network hop at all: the whole model is on the host.
    Local,
    /// Raw TCP to a routable address — a LAN, or a WireGuard-style overlay.
    Direct,
    /// Relayed or hole-punched through an iroh loopback proxy.
    Tunnel,
    /// The link could not be determined. Never matches a record: see [`lookup`].
    Unknown,
}

impl LinkClass {
    /// Stable identifier for JSON and human output.
    pub fn as_str(self) -> &'static str {
        match self {
            LinkClass::Local => "local",
            LinkClass::Direct => "direct",
            LinkClass::Tunnel => "tunnel",
            LinkClass::Unknown => "unknown",
        }
    }

    /// The link class of a whole placement, from its workers' individual links.
    ///
    /// Three rules, each chosen for a reason:
    ///
    /// - **No workers ⇒ [`Local`](LinkClass::Local).** There is no link to
    ///   classify, and a single-node run must not be keyed as though there
    ///   were.
    /// - **Any `Unknown` ⇒ `Unknown`.** One unclassifiable worker makes the
    ///   whole placement unattributable. Guessing the rest would be answering a
    ///   question we cannot see the answer to.
    /// - **Any `Tunnel` ⇒ `Tunnel`,** rather than a majority or an average. A
    ///   single-stream pipeline runs at the speed of its slowest hop, so one
    ///   tunnelled worker characterises the whole run even when every other
    ///   worker is direct.
    pub fn summarize(workers: &[LinkClass]) -> LinkClass {
        if workers.is_empty() {
            return LinkClass::Local;
        }
        if workers.contains(&LinkClass::Unknown) {
            return LinkClass::Unknown;
        }
        if workers.contains(&LinkClass::Tunnel) {
            return LinkClass::Tunnel;
        }
        LinkClass::Direct
    }
}

/// Classify the endpoint ggml dials for one worker.
///
/// A loopback authority is the tell. Worker discovery hands ggml either a
/// routable `host:port` it probed successfully, or `127.0.0.1:<port>` — a local
/// proxy socket whose far end is an iroh tunnel to the peer. Nothing else can
/// legitimately present as loopback: a worker genuinely on this machine is not
/// a worker, it is the host.
///
/// **This is the single decider, and it is shared deliberately.** `svrn mesh
/// bench` calls it on the endpoints in the daemon's live placement; `svrn mesh
/// plan` calls it on the endpoints in the mesh status' discovered-worker list.
/// Two implementations that disagreed by one edge case would file every record
/// under a key the reader can never reproduce — the store would grow forever
/// while the plan reported "not measured" for the configuration it just
/// measured. One function, two callers, is what makes that failure impossible
/// rather than merely unlikely.
pub fn link_class_of_endpoint(endpoint: &str) -> LinkClass {
    let e = endpoint.trim();
    // Only two forms carry a port unambiguously: `[<ipv6>]:port` and a single-
    // colon `<host>:port`. A bare IPv6 literal has no port (that is what the
    // brackets are for), so it is taken whole rather than truncated at its
    // first colon — `::1` must not parse as an empty host.
    let host = if let Some(rest) = e.strip_prefix('[') {
        rest.split(']').next().unwrap_or(rest)
    } else if e.matches(':').count() > 1 {
        e
    } else {
        e.split(':').next().unwrap_or(e)
    }
    .trim();

    if host.is_empty() {
        return LinkClass::Unknown;
    }
    let loopback = host.eq_ignore_ascii_case("localhost")
        || host == "::1"
        || host == "0:0:0:0:0:0:0:1"
        // The whole 127.0.0.0/8 block, not just 127.0.0.1.
        || host
            .strip_prefix("127.")
            .is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_digit()));
    if loopback {
        LinkClass::Tunnel
    } else {
        LinkClass::Direct
    }
}

// ---------------------------------------------------------------------------
// The key
// ---------------------------------------------------------------------------

/// The identity of a measurable configuration. Two runs share a key only if
/// they are genuinely the same thing measured twice.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MeasurementKey {
    /// See [`PROBE_VERSION`].
    pub probe_version: u32,
    /// See [`model_fingerprint`].
    pub model_fingerprint: String,
    /// See [`placement_digest`].
    pub placement_digest: String,
    /// See [`hardware_fingerprint`], for the host.
    pub host_hw_fingerprint: u64,
    /// Context length the measurement was taken at. Decode rate is a function
    /// of KV size, so 8k and 128k are not the same measurement.
    pub n_ctx: u32,
    /// See [`LinkClass`]. The path the tensor stream took between the machines
    /// in this placement.
    pub link: LinkClass,
}

impl MeasurementKey {
    /// Build the key for a plan against a real, present mesh.
    ///
    /// Requires a [`HostIdentity`], which is what bars a `--devices`
    /// hypothetical from ever matching a record. Always stamps the current
    /// [`PROBE_VERSION`]: a caller cannot ask for a number taken by a
    /// superseded method.
    pub fn for_plan(
        host: HostIdentity,
        model_fingerprint: String,
        placement_digest: String,
        n_ctx: u32,
        link: LinkClass,
    ) -> Self {
        Self {
            probe_version: PROBE_VERSION,
            model_fingerprint,
            placement_digest,
            host_hw_fingerprint: host.fingerprint(),
            n_ctx,
            link,
        }
    }
}

// ---------------------------------------------------------------------------
// Records
// ---------------------------------------------------------------------------

/// Whether a run is fit to be served back.
///
/// A run that tripped a validity guard is still *written* — a discarded failure
/// teaches nobody anything, and silently dropping them would turn the tool into
/// retry-until-lucky. It is simply never returned by [`lookup`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "verdict", rename_all = "snake_case")]
pub enum Verdict {
    /// Every guard passed; this number may be shown.
    Valid,
    /// At least one guard tripped. `problems` is operator-facing prose.
    Invalid {
        /// What went wrong, one entry per tripped guard.
        problems: Vec<String>,
    },
}

impl Verdict {
    /// Whether this run may be served back to a reader.
    pub fn is_valid(&self) -> bool {
        matches!(self, Verdict::Valid)
    }
}

/// What else was true of this machine while the run was taken.
///
/// [`PlacementWitness`] explains *what* a run measured. This explains the
/// *conditions it measured under* — the half that was missing when two runs
/// under one key came back 43% apart and nothing recorded could say why. Every
/// field here is something that can differ between two runs of an identical
/// configuration, which is exactly the class of thing the key cannot hold.
///
/// **Never hashed, never part of [`MeasurementKey`].** Conditions are not
/// identity. Keying on them would give every run a unique unmatched key and
/// destroy the ability to compare runs of the same configuration at all — which
/// is the entire point of the store. So a busy run and a quiet run land under
/// one key, both are kept, and the reader is told which was which.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RunConditions {
    /// Slot roles reported resident alongside the measured primary, sorted.
    ///
    /// The primary itself is excluded — it is what was measured, not something
    /// competing with it. So `["embed", "fast"]` means two other models held
    /// memory and could take GPU time during the run.
    ///
    /// Recorded because slot co-residency was the leading suspect for the 43%
    /// spread and could not be checked: it had to be *recalled* rather than
    /// read, and recall could not distinguish "resident in both runs" (a
    /// constant, which cannot explain a difference) from "resident in one".
    pub co_resident_roles: Vec<String>,

    /// Daemon resident-set size in MB at the start of the run, when `/status`
    /// reported it.
    pub host_rss_mb_before: Option<u64>,
    /// The same at the end. A large climb across a short run means something
    /// else on this box was growing while the number was being taken.
    pub host_rss_mb_after: Option<u64>,

    /// Daemon uptime in seconds when the run started.
    ///
    /// Distinguishes a measurement taken on a long-settled daemon from one
    /// taken minutes after a restart, when caches are cold and the supervisor
    /// may still be reconciling.
    pub host_uptime_s: Option<u64>,

    /// Wall-clock seconds spanned by the whole run, first trial to last.
    ///
    /// Not a performance figure — a cross-check. Two runs of the same trial
    /// count whose spans differ sharply were not taken under the same load.
    pub run_span_s: Option<f64>,
}

impl RunConditions {
    /// Whether anything shared the GPU with the measured primary.
    pub fn had_co_residents(&self) -> bool {
        !self.co_resident_roles.is_empty()
    }

    /// Growth in daemon RSS across the run, when both ends were reported.
    ///
    /// Signed on purpose: a *drop* is as interesting as a climb, because it
    /// means a slot was evicted mid-run.
    pub fn rss_delta_mb(&self) -> Option<i64> {
        match (self.host_rss_mb_before, self.host_rss_mb_after) {
            (Some(a), Some(b)) => Some(b as i64 - a as i64),
            _ => None,
        }
    }

    /// One line an operator can read, or `None` when nothing was captured.
    ///
    /// Deliberately says "nothing else resident" rather than staying silent
    /// when the slot list is empty: absence of co-residents is a *finding*
    /// about the run, not absence of information about it.
    pub fn describe(&self) -> Option<String> {
        let mut parts: Vec<String> = Vec::new();
        if self.co_resident_roles.is_empty() {
            parts.push("nothing else resident".to_string());
        } else {
            parts.push(format!("also resident: {}", self.co_resident_roles.join(", ")));
        }
        if let Some(rss) = self.host_rss_mb_before {
            match self.rss_delta_mb() {
                Some(d) if d != 0 => parts.push(format!("daemon rss {rss} MB ({d:+} MB over the run)")),
                _ => parts.push(format!("daemon rss {rss} MB")),
            }
        }
        if let Some(up) = self.host_uptime_s {
            parts.push(format!("daemon up {}", human_duration(up)));
        }
        if parts.is_empty() {
            None
        } else {
            Some(parts.join(" · "))
        }
    }
}

/// Compact duration for operator-facing condition lines.
fn human_duration(secs: u64) -> String {
    match secs {
        s if s < 90 => format!("{s}s"),
        s if s < 5400 => format!("{}m", s / 60),
        s => format!("{}h{:02}m", s / 3600, (s % 3600) / 60),
    }
}

/// One completed measurement run.
///
/// Deliberately carries **no model size**. See the module docs: without a size
/// there is no ratio to extrapolate by, so the banned size-law estimate cannot
/// be reconstructed from this data without someone first adding a field.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MeasurementRecord {
    /// The configuration this run measured.
    pub key: MeasurementKey,

    /// Median steady-state decode rate across the run's trials.
    pub decode_tok_s: f64,
    /// Slowest trial in the run.
    pub decode_tok_s_min: f64,
    /// Fastest trial in the run.
    pub decode_tok_s_max: f64,
    /// Median time to first content token.
    pub ttft_ms: f64,
    /// Median inter-token latency.
    pub itl_p50_ms: f64,
    /// 95th-percentile inter-token latency — where link jitter shows up.
    pub itl_p95_ms: f64,
    /// Prefill rate, present only when the server reported real prompt-token
    /// counts. `None` renders as "n/a", never as an estimate from string
    /// length.
    pub prefill_tok_s: Option<f64>,
    /// Seconds spent loading the model, when this run paid for a cold load.
    pub cold_load_s: Option<f64>,
    /// Timed trials contributing to this run (warm-up excluded).
    pub trials: u32,
    /// Content frames observed, summed across trials.
    pub content_frames: u32,

    /// Human-facing model name. Provenance only — never keyed on.
    pub model_name: String,
    /// Human-facing placement, e.g. `"36 local + 12 @beefymac"`.
    pub placement_human: String,
    /// Machines holding blocks.
    pub nodes: u32,
    /// Network hops per token (`nodes - 1` for a single-stream pipeline).
    pub hops: u32,
    /// Unix seconds at which the run completed.
    pub measured_at: u64,
    /// Build that took the measurement. A mismatch marks a lookup stale.
    pub build: String,
    /// Engine-reported backend, for display and for spotting a payload/key
    /// disagreement.
    pub backend: Option<String>,
    /// Measured round-trip time to the furthest worker, when distributed.
    pub link_rtt_ms: Option<f64>,

    /// Whether this run may be served back.
    pub verdict: Verdict,

    /// The inputs behind [`MeasurementKey::placement_digest`], so this record can
    /// explain itself to a reader who did not run it. See [`PlacementWitness`].
    ///
    /// `None` for a record written before 2026-07-30, when only the hash was
    /// kept. Those records still serve exact hits perfectly well — the witness is
    /// explanatory, not part of the identity — so unlike the v1→v2 change
    /// (see [`SCHEMA_VERSION`], where the missing field was a *key* field and
    /// keeping the rows would have kept rows that could never match) they are
    /// preserved rather than discarded. The cost of keeping them is that they
    /// cannot say what they measured beyond `placement_human`, and the surfaces
    /// that read a witness say so instead of guessing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub witness: Option<PlacementWitness>,

    /// What else was true of this machine while the run was taken. See
    /// [`RunConditions`].
    ///
    /// `None` for a record written before 2026-07-30. Kept rather than
    /// discarded for the same reason as a witness-less record: conditions are
    /// explanatory, not part of the identity, so an old row still serves an
    /// exact hit perfectly well. The cost of keeping it is that it cannot say
    /// what else was running — and the surfaces that read conditions say
    /// exactly that instead of implying the box was quiet.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub conditions: Option<RunConditions>,
}

/// The on-disk file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MeasurementFile {
    schema_version: u32,
    records: Vec<MeasurementRecord>,
}

impl Default for MeasurementFile {
    fn default() -> Self {
        Self {
            schema_version: SCHEMA_VERSION,
            records: Vec::new(),
        }
    }
}

impl MeasurementFile {
    /// An empty file at the current schema.
    pub fn new() -> Self {
        Self::default()
    }

    /// Every record, newest last. Includes invalid runs — they are glassbox
    /// material, and `svrn mesh bench --history` shows them.
    pub fn records(&self) -> &[MeasurementRecord] {
        &self.records
    }
}

