        vec![
            PlacementShard {
                node_key: "beefymac".into(),
                hw: Some(0xBEEF),
                blocks: Some((0, 11)),
                holds_output: false,
            },
            PlacementShard {
                node_key: "ruggedfox".into(),
                hw: Some(0xF0F),
                blocks: Some((12, 47)),
                holds_output: true,
            },
        ]
