        }
    }

    /// The witness that explains [`key`]'s placement digest.
    fn witness() -> PlacementWitness {
        PlacementWitness {
            mode: "distributed".into(),
            total_blocks: 48,
            shards: shards(),
            machines: vec![
                MachineWitness {
                    node_key: "beefymac".into(),
