    /// A peer's number is the one the reader cannot check, so the load it was
    /// taken under has to travel with it. Without this the reader is back in the
    /// position that produced a false 43% variance: two rates, no way to know
    /// they were taken on differently-loaded machines.
    #[test]
    fn a_peers_conditions_travel_with_their_number() {
        let f = MeasurementFile::new();
        let asked = witnessed_key();
        let mut busy = rec_at(asked.clone(), 500, 7.75, Verdict::Valid);
        busy.conditions = Some(RunConditions {
            co_resident_roles: vec!["embed".into(), "fast".into()],
            host_rss_mb_before: Some(4_100),
            host_rss_mb_after: Some(4_260),
            host_uptime_s: Some(2_320),
            run_span_s: Some(41.5),
        });
        let theirs = from_peer(busy, Some("BeefyMac"));

        let near = near_misses(&f, &[theirs], &asked, Some(&witness()));
        assert_eq!(near.len(), 1);
        let line = near[0]
            .conditions
            .as_deref()
            .expect("a peer's conditions must reach the surface that offers their number");
        assert!(line.contains("embed"), "{line}");
        assert!(line.contains("fast"), "{line}");
        assert_eq!(near[0].taken_by.as_deref(), Some("BeefyMac"));
    }

    /// An old record carries no conditions, and the surface must say nothing
    /// rather than imply the box was quiet.
    #[test]
    fn a_peer_record_without_conditions_offers_none() {
        let f = MeasurementFile::new();
        let asked = witnessed_key();
        let theirs = from_peer(rec_at(asked.clone(), 500, 11.08, Verdict::Valid), Some("BeefyMac"));
        let near = near_misses(&f, &[theirs], &asked, Some(&witness()));
        assert_eq!(near.len(), 1);
        assert!(
            near[0].conditions.is_none(),
            "absent conditions must not be rendered as a claim about the box"
        );
    }

    #[test]
    fn an_invalid_peer_record_is_not_offered() {
        // `to_wire` refuses to publish these, so one can only arrive from a
        // peer on a build that did not yet refuse. Filter on read as well:
        // the wire is not a trust boundary we control.
        let f = MeasurementFile::new();
        let theirs = from_peer(
            rec_at(
                witnessed_key(),
                500,
                2.1,
                Verdict::Invalid {
                    problems: vec!["decode stalled".into()],
                },
            ),
            Some("BeefyMac"),
        );
        assert!(near_misses(&f, &[theirs], &moved_key(), Some(&moved_witness())).is_empty());
    }

    #[test]
    fn a_peer_measuring_a_different_model_is_not_a_near_miss() {
        let f = MeasurementFile::new();
        let mut other = witnessed_key();
        other.model_fingerprint = "mf1:something-else".into();
        let theirs = from_peer(rec_at(other, 500, 44.0, Verdict::Valid), Some("BeefyMac"));
        assert!(
            near_misses(&f, &[theirs], &moved_key(), Some(&moved_witness())).is_empty(),
            "a different model's number is an unrelated fact, not a weaker answer"
        );
    }

    #[test]
    fn local_and_peer_measurements_rank_together_by_recency() {
        let mut f = MeasurementFile::new();
        let mut older_local = rec_at(witnessed_key(), 100, 10.4, Verdict::Valid);
        older_local.witness = Some(witness());
        record(&mut f, older_local);

        let newer_peer = from_peer(
            rec_at(witnessed_key(), 900, 11.08, Verdict::Valid),
            Some("BeefyMac"),
        );
        let near = near_misses(&f, &[newer_peer], &moved_key(), Some(&moved_witness()));
        assert_eq!(near.len(), 2);
        assert_eq!(
            near[0].taken_by.as_deref(),
            Some("BeefyMac"),
            "the question is what is the closest thing anyone measured, so the \
             two sources rank in one list rather than local-always-first"
        );
        assert!(near[1].taken_by.is_none());
    }

    #[test]
    fn a_peer_falls_back_to_its_node_id_when_the_mesh_cannot_name_it() {
        let rec = rec_at(key(), 500, 10.4, Verdict::Valid);
        assert_eq!(
            from_peer(rec.clone(), Some("BeefyMac")).describe_origin(),
            "BeefyMac"
        );
        assert_eq!(
            from_peer(rec.clone(), None).describe_origin(),
            "node-b88252e4325bc377",
            "a peer that has left the mesh is still matchable against `mesh status`"
        );
        assert_eq!(
            from_peer(rec, Some("   ")).describe_origin(),
            "node-b88252e4325bc377",
            "a blank name is no name"
        );
    }

    // -----------------------------------------------------------------------
    // Run conditions — the half a witness does not explain
    // -----------------------------------------------------------------------

    fn conditions() -> RunConditions {
        RunConditions {
            co_resident_roles: vec!["embed".into(), "fast".into()],
            host_rss_mb_before: Some(4_100),
            host_rss_mb_after: Some(4_260),
            host_uptime_s: Some(2_320),
            run_span_s: Some(41.5),
        }
    }

    /// The load-bearing rule. Conditions are explanatory, never identity: if
    /// they reached the key, two runs of one configuration taken under any
    /// different load would file under different keys, `lookup` would never
    /// find more than one run, and the variance this field exists to expose
    /// would become structurally invisible.
    #[test]
    fn conditions_never_reach_the_key() {
        let quiet = RunConditions {
            co_resident_roles: vec![],
            host_rss_mb_before: Some(900),
            host_rss_mb_after: Some(905),
            host_uptime_s: Some(90_000),
            run_span_s: Some(38.0),
        };
        let busy = conditions();

        let a = MeasurementRecord {
            conditions: Some(quiet),
            ..rec_at(key(), 1_000, 11.08, Verdict::Valid)
        };
        let b = MeasurementRecord {
            conditions: Some(busy),
            ..rec_at(key(), 2_000, 7.75, Verdict::Valid)
        };

        assert_eq!(a.key, b.key, "conditions must not participate in identity");

        // And both survive in one file, under one key, which is the whole point.
        let mut f = MeasurementFile::new();
        record(&mut f, a);
        record(&mut f, b);
        let s = lookup(&f, &key(), "0.10.0").expect("both runs are one configuration");
        assert_eq!(
            s.runs, 2,
            "a quiet run and a busy run belong to the same configuration"
        );
        assert!(
            (s.decode_tok_s_min - 7.55).abs() < 1e-9 || s.decode_tok_s_min < 7.75,
            "the spread stays visible across conditions, min was {}",
            s.decode_tok_s_min
        );
    }

    /// A record written before conditions existed must still load. The field is
    /// explanatory, so unlike the v1->v2 key change there is nothing to discard.
    #[test]
    fn a_record_with_no_conditions_still_loads() {
        let mut json = serde_json::to_value(rec_at(key(), 10, 9.0, Verdict::Valid)).unwrap();
        json.as_object_mut().unwrap().remove("conditions");
        assert!(
            !json.as_object().unwrap().contains_key("conditions"),
            "fixture must actually lack the field"
        );
        let back: MeasurementRecord = serde_json::from_value(json).unwrap();
        assert!(back.conditions.is_none(), "absent means not recorded");
    }

    #[test]
    fn conditions_round_trip_through_json() {
        let r = MeasurementRecord {
            conditions: Some(conditions()),
            ..rec_at(key(), 10, 9.0, Verdict::Valid)
        };
        let back: MeasurementRecord =
            serde_json::from_str(&serde_json::to_string(&r).unwrap()).unwrap();
        assert_eq!(back.conditions, r.conditions);
    }

    /// An empty slot list is a FINDING — "nothing else was resident" — not
    /// missing information. A reader who cannot tell those apart cannot use the
    /// field to compare two runs, which is its only purpose.
    #[test]
    fn no_co_residents_is_reported_as_a_finding_not_as_silence() {
        let c = RunConditions {
            co_resident_roles: vec![],
            host_rss_mb_before: None,
            host_rss_mb_after: None,
            host_uptime_s: None,
            run_span_s: None,
        };
        let line = c.describe().expect("an empty slot list still says something");
        assert!(
            line.contains("nothing else resident"),
            "expected an explicit finding, got: {line}"
        );
        assert!(!c.had_co_residents());
    }

    #[test]
    fn describe_names_every_co_resident_and_the_rss_climb() {
        let line = conditions().describe().unwrap();
        assert!(line.contains("embed"), "{line}");
        assert!(line.contains("fast"), "{line}");
        assert!(line.contains("4100 MB"), "{line}");
        assert!(line.contains("+160 MB"), "expected a signed delta, got: {line}");
        assert!(line.contains("38m"), "expected a compact uptime, got: {line}");
    }

    /// A negative delta means a slot was evicted mid-run, which invalidates the
    /// comparison as surely as a climb does. Reporting it unsigned would hide
    /// the direction and make the two look alike.
    #[test]
    fn an_rss_drop_reports_as_negative() {
        let c = RunConditions {
            host_rss_mb_before: Some(90_000),
            host_rss_mb_after: Some(4_000),
            ..conditions()
        };
        assert_eq!(c.rss_delta_mb(), Some(-86_000));
        assert!(c.describe().unwrap().contains("-86000 MB"));
    }

    #[test]
    fn an_rss_delta_needs_both_ends() {
        let c = RunConditions {
            host_rss_mb_after: None,
            ..conditions()
        };
        assert_eq!(c.rss_delta_mb(), None, "one reading is not a delta");
        let line = c.describe().unwrap();
        assert!(line.contains("4100 MB"), "{line}");
        assert!(!line.contains("+"), "no delta should be claimed: {line}");
    }

    #[test]
    fn human_duration_stays_compact_across_the_ranges() {
        assert_eq!(human_duration(45), "45s");
        assert_eq!(human_duration(89), "89s");
        assert_eq!(human_duration(90), "1m");
        assert_eq!(human_duration(2_320), "38m");
        assert_eq!(human_duration(5_400), "1h30m");
        assert_eq!(human_duration(90_061), "25h01m");
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn mesh` subcommand handlers (the `corpus` half moved to
//! `corpus_cmd` in the §3.2 split that fixed the dispatch naming lie).
//!
//! These are lightweight commands that don't require loading a full model
//! or database — they manage the embedded Commonwealth daemon.

use std::path::PathBuf;

use sovereign_cli_shared::dirs::mesh_data_dir;
use sovereign_mesh::deep_link::{build_https_join_link, parse_join_argument};
use sovereign_mesh::EmbeddedDaemon;

/// Run a mesh subcommand. Returns the exit code.
pub async fn run_mesh(args: &[String]) -> i32 {
    if args.is_empty() {
        sovereign_cli_shared::help::print(&HELP_MESH);
        return 1;
    }
    if matches!(args[0].as_str(), "--help" | "-h" | "help") {
        sovereign_cli_shared::help::print(&HELP_MESH);
        return 0;
    }

    match args[0].as_str() {
        "create" => cmd_create(&args[1..]).await,
        "join" => cmd_join(&args[1..]).await,
        "rotate" => cmd_rotate(&args[1..]).await,
        "status" => cmd_status(&args[1..]).await,
        "transport" => cmd_transport(&args[1..]).await,
        "balance" => cmd_balance().await,
        "leave" => cmd_leave().await,
        "logs" => cmd_logs().await,
        "fetch-model" => cmd_fetch_model(&args[1..]).await,
        "warm-cache" => cmd_warm_cache(&args[1..]).await,
        "plan" => cmd_plan(&args[1..]).await,
        "bench" => crate::mesh_bench::cmd_bench(&args[1..]).await,
        "check-invariants" => cmd_check_invariants(&args[1..]).await,
        "soak-gate" => cmd_soak_gate(&args[1..]).await,
        other => {
            eprintln!("Unknown mesh subcommand: {other}");
            sovereign_cli_shared::help::print(&HELP_MESH);
            1
        }
    }
}

/// `svrn mesh warm-cache <gguf> [--cache-dir <dir>]`
///
/// Pre-seed the RPC worker's tensor cache from a local GGUF — fully offline (no
/// network, no GPU). When the cluster later serves this model, the host's
/// tensor-hash requests are all cache hits and zero weight bytes cross the wire.
/// The companion to a thumbdrive'd GGUF: distribute the model offline, run this
/// on each worker, and a metered/throttled link never carries the weights.
async fn cmd_warm_cache(args: &[String]) -> i32 {
    let mut model: Option<std::path::PathBuf> = None;
    let mut cache_dir: Option<std::path::PathBuf> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--cache-dir" => {
                i += 1;
                cache_dir = args.get(i).map(std::path::PathBuf::from);
            }
            "--help" | "-h" => {
                eprintln!("Usage: svrn mesh warm-cache <model.gguf> [--cache-dir <dir>]");
                eprintln!();
                eprintln!("  Pre-seeds the RPC tensor cache from a local GGUF so a mesh worker");
                eprintln!("  serves this model with ZERO weight transfer over the network.");
                eprintln!("  Fully offline — no network, no GPU. Default cache dir:");
                eprintln!("  ~/.sovereign/rpc-cache (matches the in-process worker).");
                return 0;
            }
            s if model.is_none() && !s.starts_with('-') => {
                model = Some(std::path::PathBuf::from(s));
            }
            other => {
                eprintln!("Unknown arg: {other}");
                return 2;
            }
        }
        i += 1;
    }
    let Some(model) = model else {
        eprintln!("Usage: svrn mesh warm-cache <model.gguf> [--cache-dir <dir>]");
        return 2;
    };
    let cache_dir = match cache_dir.or_else(sovereign_inference::embedded::default_cache_dir) {
        Some(d) => d,
        None => {
            eprintln!("could not resolve a cache dir (pass --cache-dir or set HOME)");
            return 1;
        }
    };
    eprintln!(
        "warming RPC cache for {} → {}",
        model.display(),
        cache_dir.display()
    );
    let t0 = std::time::Instant::now();
    match sovereign_inference::embedded::warm_cache_from_gguf(&model, &cache_dir) {
        Ok(s) => {
            println!(
                "✓ {}/{} tensors cacheable (>10MB): {} written ({:.2} GB), {} already present — {:.1}s",
                s.tensors_cacheable,
                s.tensors_total,
                s.written,
                s.bytes_written as f64 / 1e9,
                s.already_present,
                t0.elapsed().as_secs_f64(),
            );
            println!("  cache dir: {}", s.cache_dir.display());
            0
        }
        Err(e) => {
            eprintln!("warm-cache failed: {e}");
            1
        }
    }
}

/// `svrn mesh check-invariants --nodes <a:port,b:port,...> [--expect-live <id,...>] [--json]`
///
/// The assertion engine for the multi-process soak (`scripts/mesh-soak.sh`):
/// polls each node's `GET /v1/mesh/status` and evaluates the HTTP-observable
/// mesh invariants (convergence / no-ghost / liveness — see [`crate::mesh_soak`]).
/// Exits non-zero if any invariant is violated, so a soak loop can `||` on it.
/// `--json` emits one machine-readable line for `mesh-soak-findings.jsonl`.
async fn cmd_check_invariants(args: &[String]) -> i32 {
    use crate::mesh_soak::{evaluate_invariants, NodeSnapshot, NodeStatusView};

    let mut nodes: Vec<String> = Vec::new();
    let mut json = false;
    let mut expect_live: Option<std::collections::BTreeSet<String>> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--nodes" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    nodes = v
                        .split(',')
                        .map(|s| s.trim().to_string())
                        .filter(|s| !s.is_empty())
                        .collect();
                }
            }
            "--expect-live" => {
                i += 1;
                if let Some(v) = args.get(i) {
                    expect_live = Some(
                        v.split(',')
                            .map(|s| s.trim().to_string())
                            .filter(|s| !s.is_empty())
                            .collect(),
                    );
                }
            }
            "--json" => json = true,
            "--help" | "-h" => {
                eprintln!("Usage: svrn mesh check-invariants --nodes <a:port,b:port,...> [--expect-live <id,...>] [--json]");
                eprintln!();
                eprintln!("  Polls GET /v1/mesh/status on each node and asserts the mesh");
                eprintln!("  invariants: convergence (all agree on the member set), no-ghost");
                eprintln!("  (no deliberately-downed node shown live; pair with --expect-live),");
                eprintln!("  and liveness (every reachable node seen live by its peers).");
                eprintln!("  Exit 0 if all hold, 1 on violation. The assertion engine for");
                eprintln!("  scripts/mesh-soak.sh.");
                return 0;
            }
            other => {
                eprintln!("Unknown arg: {other}");
                return 2;
            }
        }
        i += 1;
    }
    if nodes.is_empty() {
        eprintln!("--nodes is required (comma-separated host:port list)");
        return 2;
    }

    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(5))
        .build()
        .unwrap_or_default();

    let mut snapshots = Vec::with_capacity(nodes.len());
    for addr in &nodes {
        let url = format!("http://{addr}/v1/mesh/status");
        let snap = match client.get(&url).send().await {
            Ok(resp) if resp.status().is_success() => match resp.json::<NodeStatusView>().await {
                Ok(v) => NodeSnapshot {
                    addr: addr.clone(),
                    status: Some(v),
                    error: None,
                },
                Err(e) => NodeSnapshot {
                    addr: addr.clone(),
                    status: None,
                    error: Some(format!("bad status json: {e}")),
                },
            },
            Ok(resp) => NodeSnapshot {
                addr: addr.clone(),
                status: None,
                error: Some(format!("http {}", resp.status())),
            },
            Err(e) => NodeSnapshot {
                addr: addr.clone(),
                status: None,
                error: Some(format!("unreachable: {e}")),
            },
        };
        snapshots.push(snap);
    }

    let violations = evaluate_invariants(&snapshots, expect_live.as_ref());

    if json {
        let unreachable: Vec<&str> = snapshots
            .iter()
            .filter(|s| s.status.is_none())
            .map(|s| s.addr.as_str())
            .collect();
        // Track W: nodes whose founder self-heal is currently degraded (soft
        // signal — transient under reachability chaos, gated by the
        // `founder_degraded_rate` SLI, NOT a hard invariant `ok` failure).
        let founder_degraded = crate::mesh_soak::founder_degraded_addrs(&snapshots);
        let line = serde_json::json!({
            "nodes": nodes,
            "unreachable": unreachable,
            "violations": violations
                .iter()
                .map(|v| serde_json::json!({ "invariant": v.invariant, "detail": v.detail }))
                .collect::<Vec<_>>(),
            "ok": violations.is_empty(),
            "founder_degraded": founder_degraded,
        });
        println!("{line}");
    } else {
        for s in &snapshots {
            match &s.status {
                Some(v) => println!("  {} — {} members", s.addr, v.members_total),
                None => println!(
                    "  {} — UNREACHABLE ({})",
                    s.addr,
                    s.error.as_deref().unwrap_or("?")
                ),
            }
        }
        if violations.is_empty() {
            println!("✓ mesh invariants hold across {} node(s)", nodes.len());
        } else {
            eprintln!("✘ {} invariant violation(s):", violations.len());
            for v in &violations {
                eprintln!("  [{}] {}", v.invariant, v.detail);
            }
        }
    }

    if violations.is_empty() {
        0
    } else {
        1
    }
}

/// `svrn mesh soak-gate <findings.jsonl> [--baseline <file>] [--update-baseline]`
///
/// Layer 3 of the mesh QA plan: distils `mesh-soak-findings.jsonl` into SLIs
/// (invariant violation rate, load success rate, load p50/p99) and gates each
/// against a committed baseline (direction + tolerance — the `lane_baseline`
/// pattern). Exit 1 on regression so CI can gate. `--update-baseline` captures
/// the current SLIs as the new baseline (establish-then-ratchet).
async fn cmd_soak_gate(args: &[String]) -> i32 {
    use crate::mesh_soak::{gate_slis, soak_slis};

    let mut findings: Option<String> = None;
    let mut baseline_path: Option<String> = None;
    let mut update = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--baseline" => {
                i += 1;
                baseline_path = args.get(i).cloned();
            }
            "--update-baseline" => update = true,
            "--help" | "-h" => {
                eprintln!("Usage: svrn mesh soak-gate <findings.jsonl> [--baseline <file>] [--update-baseline]");
                eprintln!();
                eprintln!("  Distils mesh-soak-findings.jsonl into SLIs (invariant violation");
                eprintln!("  rate, load success rate, load p50/p99) and gates each against a");
                eprintln!("  committed baseline. Exit 1 on regression past tolerance.");
                eprintln!("  --update-baseline writes the current SLIs as the new baseline.");
                return 0;
            }
            s if findings.is_none() && !s.starts_with('-') => findings = Some(s.to_string()),
            other => {
                eprintln!("Unknown arg: {other}");
                return 2;
            }
        }
        i += 1;
    }
    let Some(findings) = findings else {
        eprintln!("findings.jsonl path required");
        return 2;
    };
    let text = match std::fs::read_to_string(&findings) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("read {findings}: {e}");
            return 1;
        }
    };
    let lines: Vec<serde_json::Value> = text
        .lines()
        .filter_map(|l| serde_json::from_str(l).ok())
        .collect();
    let current = soak_slis(&lines);

    if update {
        let Some(bp) = &baseline_path else {
            eprintln!("--update-baseline requires --baseline <file>");
            return 2;
        };
        return match serde_json::to_string_pretty(&current)
            .map_err(|e| e.to_string())
            .and_then(|s| std::fs::write(bp, s).map_err(|e| e.to_string()))
        {
            Ok(()) => {
                println!("✓ wrote mesh-soak baseline → {bp}");
                0
            }
            Err(e) => {
                eprintln!("write baseline {bp}: {e}");
                1
            }
        };
    }

    let baseline: Option<std::collections::BTreeMap<String, f64>> = baseline_path
        .as_ref()
        .and_then(|bp| std::fs::read_to_string(bp).ok())
        .and_then(|s| serde_json::from_str(&s).ok());
    let (rows, first_run) = gate_slis(&current, baseline.as_ref());

    eprintln!("── mesh-soak SLO gate (baseline-relative) ──");
    for r in &rows {
        let base = r
            .baseline
            .map(|b| format!("{b:.4}"))
            .unwrap_or_else(|| "—".into());
        let status = if r.regressed { "REGRESSED" } else { "ok" };
        eprintln!(
            "  {:<28} base={:>10} cur={:>10.4}  {status}",
            r.name, base, r.current
        );
    }
    if first_run {
        eprintln!("  no baseline yet — first run. Capture one with --update-baseline.");
        return 0;
    }
    let n = rows.iter().filter(|r| r.regressed).count();
    if n == 0 {
        eprintln!("  VERDICT: PASS ✓ — no SLI regressed past tolerance.");
        0
    } else {
        eprintln!("  VERDICT: FAIL ✗ — {n} SLI(s) regressed vs baseline.");
        1
    }
}

