            data_dir: PathBuf::from("/cfg"),
            client_port: 9741,
        }
    }

    /// A re-run against files already on disk must not claim it is
    /// about to download 10.88 GB — the consent screen is only worth
    /// anything if its numbers are true.
    #[test]
    fn download_gb_is_zero_when_the_model_is_already_present() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"GGUF").unwrap();
        let plan = plan_with(model, None);
        assert_eq!(plan.download_gb(), 0.0);
    }

    #[test]
    fn download_gb_counts_a_missing_model() {
        let tmp = tempfile::tempdir().unwrap();
        let plan = plan_with(tmp.path().join("absent.gguf"), None);
        assert!((plan.download_gb() - 10.88).abs() < f64::EPSILON);
    }

    #[test]
    fn download_gb_counts_a_missing_embed_too() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"GGUF").unwrap();
        let mut plan = plan_with(model, None);
        let embed = tmp.path().join("e.gguf");
        plan.embed_download = Some((slot("e.gguf", 0.6), embed));
        assert!((plan.download_gb() - 0.6).abs() < 1e-9);
    }

    /// An empty file is not a model. `download_gguf` resumes from a
    /// `.part`, but a zero-byte final path is the signature of an
    /// interrupted move and must count as absent.
    #[test]
    fn zero_byte_files_count_as_absent() {
        let tmp = tempfile::tempdir().unwrap();
        let model = tmp.path().join("m.gguf");
        std::fs::write(&model, b"").unwrap();
        assert!(!file_is_present(&model));
    }

    #[test]
    fn already_lean_requires_both_primary_and_fim_to_match() {
        let model = PathBuf::from("/models/m.gguf");
        let other = PathBuf::from("/models/other.gguf");

        let matching = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: model.clone(),
                fim_path: Some(model.clone()),
            }),
        );
        assert!(matching.already_lean_on_this_model());

        // primary matches but FIM was never configured
        let half = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: model.clone(),
                fim_path: None,
            }),
        );
        assert!(!half.already_lean_on_this_model());

        // FIM points somewhere else — the dedicated-slot arrangement
        let dedicated = plan_with(
            model.clone(),
            Some(ExistingConfig {
                primary: other,
                fim_path: Some(model),
            }),
        );
        assert!(!dedicated.already_lean_on_this_model());

        assert!(!plan_with(PathBuf::from("/models/m.gguf"), None).already_lean_on_this_model());
    }

    #[test]
    fn backup_path_sits_beside_the_config() {
        let cfg = PathBuf::from("/home/u/.sovereign/config.toml");
        assert_eq!(
            cfg.with_extension("toml.pre-fim"),
            PathBuf::from("/home/u/.sovereign/config.toml.pre-fim")
        );
    }

    #[test]
    fn truncate_keeps_short_strings_whole() {
        assert_eq!(truncate("abc", 10), "abc");
        assert_eq!(truncate("abcdefghij", 5), "abcd\u{2026}");
    }

    #[test]
    fn on_path_finds_a_real_executable_dir_entry() {
        // `sh` exists on every unix host the daemon supports; on
        // Windows the candidate-extension branch is what matters and
        // this assertion would be about a different binary, so scope
        // the test to unix.
        #[cfg(unix)]
        assert!(on_path("sh"), "expected sh on PATH");
        assert!(!on_path("definitely-not-a-real-binary-9f3a"));
    }

    #[test]
    fn existing_vsix_picks_the_newest() {
        let tmp = tempfile::tempdir().unwrap();
        let old = tmp.path().join("sovereign-fim-0.0.1.vsix");
        let new = tmp.path().join("sovereign-fim-0.1.0.vsix");
        std::fs::write(&old, b"old").unwrap();
        std::thread::sleep(std::time::Duration::from_millis(20));
        std::fs::write(&new, b"new").unwrap();
        std::fs::write(tmp.path().join("notes.txt"), b"ignore me").unwrap();
        assert_eq!(existing_vsix(tmp.path()), Some(new));
    }

    #[test]
    fn existing_vsix_is_none_when_there_are_none() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("package.json"), b"{}").unwrap();
        assert_eq!(existing_vsix(tmp.path()), None);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn knowledge-gym …` — correctness harness for the
//! unified `knowledge_lookup` tool (Tool-Mastery framework Phase 5).
//!
//! Each fixture under `sovereign/bench/knowledge-gym/fixtures/`
//! is a self-contained replay: an `input.json` (OpenAI-compatible
//! chat completion request with the `knowledge_lookup` tool
//! declared), a `mock_evidence.json` (the canned response we
//! return when the model emits a `knowledge_lookup` call), and a
//! `pass.toml` (the predicates to evaluate against the transcript).
//!
//! The gym hits the running daemon at `/v1/chat/completions`,
//! observes the model's `tool_calls`, fields the
//! `knowledge_lookup` invocations with the fixture's mock
//! evidence (no live tool execution), and scores the transcript
//! against structural + semantic predicates.

mod runner;

use std::path::{Path, PathBuf};
use std::time::Duration;

use serde_json::Value;

const DEFAULT_BASE_URL: &str = "http://localhost:9741";
const DEFAULT_FIXTURES_DIR: &str = "sovereign/bench/knowledge-gym/fixtures";
const HTTP_TIMEOUT: Duration = Duration::from_secs(120);
const DEFAULT_REPLAYS: u32 = 3;

pub async fn run_knowledge_gym(args: &[String]) -> i32 {
    let cmd = args.first().map(String::as_str).unwrap_or("run");
    match cmd {
        "run" => run_cmd(&args[1..]).await,
        "-h" | "--help" | "help" => {
            print_help();
            0
        }
        other => {
            eprintln!("unknown subcommand: {other}\n");
            print_help();
            2
        }
    }
}

fn print_help() {
    println!(
        "svrn knowledge-gym — correctness harness for knowledge_lookup\n\n\
         USAGE\n  sovereign knowledge-gym run [--fixture SLUG] [--replays N] \
         [--base-url URL] [--fixtures-dir PATH] [--json]\n\n\
         Each fixture dir holds input.json + mock_evidence.json + pass.toml.\n\
         The gym replays the input against the running daemon, mocks the\n\
         knowledge_lookup tool with the canned evidence, and scores the\n\
         transcript."
    );
}

async fn run_cmd(args: &[String]) -> i32 {
    let mut base_url = DEFAULT_BASE_URL.to_string();
    let mut fixtures_dir: PathBuf = DEFAULT_FIXTURES_DIR.into();
    let mut only_fixture: Vec<String> = Vec::new();
    let mut replays: u32 = DEFAULT_REPLAYS;
    let mut json_out = false;

    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        match a.as_str() {
            "--base-url" => {
                base_url = iter.next().cloned().unwrap_or_else(|| {
                    eprintln!("--base-url requires a value");
                    std::process::exit(2)
                });
            }
            "--fixtures-dir" => {
                fixtures_dir = iter.next().map(PathBuf::from).unwrap_or_else(|| {
                    eprintln!("--fixtures-dir requires a value");
                    std::process::exit(2)
                });
            }
            "--fixture" => {
                only_fixture.push(iter.next().cloned().unwrap_or_else(|| {
                    eprintln!("--fixture requires a value");
                    std::process::exit(2)
                }));
            }
            "--replays" => {
                let v = iter.next().cloned().unwrap_or_else(|| {
                    eprintln!("--replays requires a value");
                    std::process::exit(2)
                });
                replays = v.parse().unwrap_or_else(|_| {
                    eprintln!("--replays expects an integer");
                    std::process::exit(2)
                });
            }
            "--json" => {
                json_out = true;
            }
            _ => {
                eprintln!("unknown flag: {a}");
                return 2;
            }
        }
    }

    let fixtures = match load_fixtures(&fixtures_dir, &only_fixture) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("knowledge-gym: cannot load fixtures: {e}");
            return 1;
        }
    };
    if fixtures.is_empty() {
        eprintln!(
            "knowledge-gym: no fixtures found under {}",
            fixtures_dir.display()
        );
        return 1;
    }

    let client = reqwest::Client::builder()
        .timeout(HTTP_TIMEOUT)
        .build()
        .expect("build http client");
    let cfg = runner::RunnerCfg { base_url, replays };

    let mut all_runs: Vec<runner::FixtureReport> = Vec::new();
    for fx in &fixtures {
        emit(&format!("\n=== fixture: {} ===", fx.slug));
        let report = runner::run_fixture_replays(&client, &cfg, fx).await;
        for line in report.human_lines() {
            emit(&format!("  {line}"));
        }
        all_runs.push(report);
    }

    let agg = runner::summarise(&all_runs);
    if json_out {
        match serde_json::to_string_pretty(&agg) {
            Ok(s) => println!("{s}"),
            Err(e) => eprintln!("knowledge-gym: cannot serialise summary: {e}"),
        }
    } else {
        eprintln!("\n=== summary ===");
        for line in agg.human_lines() {
            eprintln!("  {line}");
        }
    }

    if agg.pass_rate >= 0.9 {
        0
    } else {
        // Soft non-zero so CI can gate on the threshold while
        // letting interactive iteration still see the table.
        3
    }
}

/// One turn's input + mock evidence in a fixture. Single-turn
/// fixtures have a `Vec<TurnSpec>` of length 1; multi-turn
/// fixtures (Gym Phase 2 of the tool-framework expansion plan)
/// have one entry per user turn. The runner walks them in order,
/// preserving the conversation history between turns.
#[derive(Debug)]
pub(crate) struct TurnSpec {
    pub input: Value,
    pub mock_evidence: Value,
}

#[derive(Debug)]
pub(crate) struct Fixture {
    pub slug: String,
    #[allow(dead_code)]
    pub path: PathBuf,
    pub turns: Vec<TurnSpec>,
    pub predicates: toml::Value,
}

const EMPTY_MOCK_EVIDENCE: &str =
    r#"{"query": "", "evidence": [], "by_kind_counts": {"corpus": 0, "memory": 0, "note": 0}}"#;

fn load_fixtures(dir: &Path, only: &[String]) -> std::io::Result<Vec<Fixture>> {
    let entries = std::fs::read_dir(dir)?;
    let mut out = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let slug = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("?")
            .to_string();
        if !only.is_empty() && !only.iter().any(|s| s == &slug) {
            continue;
        }
        let pass_path = path.join("pass.toml");
        if !pass_path.exists() {
            continue;
        }
        let pass_raw = std::fs::read_to_string(&pass_path)?;
        let predicates: toml::Value = toml::from_str(&pass_raw)
            .map_err(|e| std::io::Error::other(format!("{slug}/pass.toml: {e}")))?;

        // Detect single-turn (input.json) vs multi-turn
        // (input_turn_0.json, input_turn_1.json, ...). The
        // detection rule is presence of `input.json`: when it
        // exists, this is a single-turn fixture and any
        // input_turn_N.json files are ignored (so a fixture
        // author can leave a draft sequence on disk without
        // breaking the single-turn path).
        let turns = if path.join("input.json").exists() {
            vec![load_turn(&path, &slug, "input.json", "mock_evidence.json")?]
        } else {
            load_multi_turn(&path, &slug)?
        };
        if turns.is_empty() {
            continue;
        }
        out.push(Fixture {
            slug,
            path,
            turns,
            predicates,
        });
    }
    out.sort_by(|a, b| a.slug.cmp(&b.slug));
    Ok(out)
}

/// Load a single turn's spec from explicit file names. The mock
/// path is optional — when absent, the runner injects an empty
/// evidence envelope (useful for fixtures whose model is expected
/// NOT to call the tool).
fn load_turn(
    dir: &Path,
    slug: &str,
    input_name: &str,
    mock_name: &str,
) -> std::io::Result<TurnSpec> {
    let input_path = dir.join(input_name);
    let mock_path = dir.join(mock_name);
    let input_raw = std::fs::read_to_string(&input_path)?;
    let mock_raw = if mock_path.exists() {
        std::fs::read_to_string(&mock_path)?
    } else {
        EMPTY_MOCK_EVIDENCE.to_string()
    };
    let input: Value = serde_json::from_str(&input_raw)
        .map_err(|e| std::io::Error::other(format!("{slug}/{input_name}: {e}")))?;
    let mock_evidence: Value = serde_json::from_str(&mock_raw)
        .map_err(|e| std::io::Error::other(format!("{slug}/{mock_name}: {e}")))?;
    Ok(TurnSpec {
        input,
        mock_evidence,
    })
}

/// Walk `input_turn_N.json` + `mock_evidence_turn_N.json` pairs
/// for `N = 0, 1, 2, …` until the input file is missing. Returns
/// the contiguous prefix. Gaps (e.g. turn_0 + turn_2 with no
/// turn_1) are not supported — the runner stops at the first
/// missing input.
fn load_multi_turn(dir: &Path, slug: &str) -> std::io::Result<Vec<TurnSpec>> {
    let mut turns = Vec::new();
    for n in 0..64 {
        let input_name = format!("input_turn_{n}.json");
        let mock_name = format!("mock_evidence_turn_{n}.json");
        if !dir.join(&input_name).exists() {
            break;
        }
        turns.push(load_turn(dir, slug, &input_name, &mock_name)?);
    }
    Ok(turns)
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! Member-list gossip — the thing that keeps two peers' views of
//! the mesh converged after the initial join.
//!
//! Model: anti-entropy push-pull over plain HTTP on port 9742. Every
//! `interval` (default 10s) we pick up to `FANOUT` random members
//! and POST our current `Mesh` to their `/internal/gossip`; they
//! merge it into theirs and reply with their (now-updated) snapshot
//! which we then merge in. Convergence in one round per pair.
//!
//! Two side effects every round:
//! 1. Our own `last_seen` is bumped to `now()` so peers learn we're
//!    still here and don't decay us to Offline.
//! 2. Members whose `last_seen` is older than `offline_threshold`
//!    are marked `NodeStatus::Offline` locally — the mechanism that
//!    turns "the founder closed their laptop" from a silent stale
//!    member list into a visible offline indicator.
//!
//! Reuses `Mesh::merge_from` for the actual last-writer-wins
//! reconciliation. This module is just the network plumbing on top.
use std::time::{Duration, Instant};

use commonwealth_api::state::AppState;
use commonwealth_core::ids::MeshId;
use commonwealth_core::mesh::{MemberRecord, Mesh, MeshPeering, NodeStatus};
use commonwealth_transport::{peer_contact, PeerContact, TrafficClass};
use serde::{Deserialize, Serialize};
use tracing::{debug, info, warn};

use crate::capabilities::build_local_capabilities;

// Address ordering and the last-working-address promotion both live
// in the PeerTransport seam now (`IpTransport` in
// commonwealth-transport) — this module used to carry a
// process-global `last_working_address_cache`; the transport on
// `AppState` has the same effective lifetime (one per daemon run)
// and shares the hint with every other traffic class.

/// Default: send to at most this many peers per round. Small mesh
/// sizes make higher fan-out pointless; bandwidth is negligible at
/// 2 even with full-snapshot gossip.
const FANOUT: usize = 2;

/// Hard per-peer HTTP timeout. Mirrors `sovereign-mesh::join` so
/// slow/unreachable peers don't drag out a gossip round.
const PEER_TIMEOUT: Duration = Duration::from_secs(3);

/// After this long without a successful gossip contact, a peer is
/// marked Offline. Needs to be >> `interval` so a single missed
/// round doesn't flap peers offline — roughly 6× the interval is
/// a reasonable default.
pub const DEFAULT_OFFLINE_THRESHOLD: Duration = Duration::from_secs(60);

/// Default gossip cadence. Chosen to match the UI's 5s poll
/// comfortably (UI sees converged state within ~2× the cadence).
pub const DEFAULT_GOSSIP_INTERVAL: Duration = Duration::from_secs(10);

/// Handle to the spawned gossip task. Aborts the task when dropped
/// (mirrors `commonwealth_discovery::mdns::BrowseHandle`). The
/// `DaemonState::Running` variant holds one of these so stopping
/// the daemon cleanly tears down the gossip loop along with mDNS.
pub struct GossipHandle {
    _task: tokio::task::JoinHandle<()>,
}

impl Drop for GossipHandle {
    fn drop(&mut self) {
        self._task.abort();
    }
}

/// Spawn the periodic gossip task. Call once per daemon start.
///
/// `persist_dir` is the directory containing `mesh.json`. When
/// provided, every round re-persists the current mesh snapshot so
/// that mutations from any source — the `/internal/join` handler,
/// `merge_from` via gossip, `last_seen` bumps, status decays —
/// survive a daemon restart without needing a per-handler persist
/// callback. Costs one JSON file write per 10s (trivial). `None`
/// (test harnesses, CLI without persistence) skips persistence.
pub fn spawn_gossip_loop(
    app_state: AppState,
    interval: Duration,
    offline_threshold: Duration,
    persist_dir: Option<std::path::PathBuf>,
) -> GossipHandle {
    let task = tokio::spawn(async move {
        info!(
            interval_secs = interval.as_secs(),
            offline_threshold_secs = offline_threshold.as_secs(),
            persistence = persist_dir.is_some(),
            "gossip: loop started"
        );
        loop {
            tokio::time::sleep(interval).await;
            if let Err(e) = run_one_round(&app_state, offline_threshold).await {
                warn!(error = %e, "gossip: round errored");
            }
            if let Some(dir) = persist_dir.as_deref() {
                let mesh = app_state.inner.mesh.read().await.clone();
                let self_id = *app_state.inner.self_node_id_swap.load_full().as_ref();
                if let Err(e) = crate::persist::save(dir, &mesh, self_id) {
                    // Don't spam — persistence failure is rarely
                    // fatal to the running session, but the operator
                    // should know their mesh won't survive restart.
                    warn!(
                        error = %e,
                        "gossip: mesh.json re-persist failed"
                    );
                }
            }
        }
    });
    GossipHandle { _task: task }
}

/// Fire a single gossip round immediately — used as a "fast initial
/// sync" trigger right after the daemon starts so a restart doesn't
/// wait a full interval before reconciling with peers. Bounded by
/// `max_duration` so daemon startup stays prompt even when all
/// peers are unreachable.
pub async fn initial_sync(
    app_state: &AppState,
    offline_threshold: Duration,
    max_duration: Duration,
) {
    match tokio::time::timeout(max_duration, run_one_round(app_state, offline_threshold)).await {
        Ok(Ok(())) => {
            debug!("gossip: initial_sync completed");
        }
        Ok(Err(e)) => warn!(error = %e, "gossip: initial_sync errored"),
        Err(_) => {
            debug!(
                max_ms = max_duration.as_millis() as u64,
                "gossip: initial_sync timed out — continuing startup"
            );
        }
    }
}

/// Choose this round's gossip targets from `(peer, last_contact_unix)`
/// pairs: online peers first, and **most-stale first within each group** —
/// the peer closest to the offline threshold is the one a round can least
/// afford to skip. Offline peers take whatever slots are left. Returned in
/// dial order, so live peers are contacted before any unreachable member
/// can burn `PEER_TIMEOUT`.
///
/// THE RULE THIS ENFORCES: *selection misses alone must never be able to
/// carry a reachable peer past `offline_threshold`.* The previous selection
/// shuffled ALL members together and truncated to `FANOUT`, making a live
/// peer's per-round contact chance `FANOUT / members` — while
/// `DEFAULT_OFFLINE_THRESHOLD` is sized at "roughly 6× the interval" on the
/// unstated assumption that a round *contacts* the peer. Random sampling
/// silently violated the assumption its own constant was chosen under.
///
/// Ordering by staleness converts that coin flip into a bound: with `n`
/// online peers a peer waits at most `ceil(n / FANOUT)` rounds, because
/// every round it goes unpicked it moves up the order. No RNG, no
/// per-round state, and it degrades gracefully — the mesh only needs
/// `ceil(n / FANOUT) * interval < offline_threshold`, which is a
/// computable condition rather than a silent probability
/// (`max_online_peers_before_false_offline`).
///
/// MEASURED, not theorised. Meshsonics 2026-07-29: 4 members, one live
/// peer (BeefyMac) + two long-dead ones, `FANOUT = 2`. BeefyMac was picked
/// ~2/3 of rounds while the dead peers each burned a ~3s iroh dial,
/// stretching rounds 10s → ~16s, so four misses cleared 60s. It flapped
/// Offline three times in fourteen minutes (staleness 68s / 63s / 62s)
/// with gossip reach at 65–600ms on either side of every lapse. Because
/// gossip-Online membership *is* the RPC-worker liveness signal, each flap
/// emptied the eligible-worker set; the third retired a healthy
/// distributed 122B eleven minutes into serving. Fourteen seconds after
/// that child was SIGKILLed: `gossip: reach ok reach_ms=548`.
///
/// A member that cannot contribute to a given workload is NOT the thing
/// being filtered here, and must never be: peers belong to a mesh for
/// their own reasons, and a run drawing on a subset of them is the normal
/// case, not a degraded one. The only axis this reads is reachability.
///
/// Resurrection is unaffected when the online set fills the fan-out: a
/// returning peer runs this same loop and dials US, and the receive-side
/// merge stamps `observe_peer_contact` — already the documented
/// offline→online path, not a new assumption.
fn select_round_peers<T>(
    mut online: Vec<(T, u64)>,
    mut offline: Vec<(T, u64)>,
    fanout: usize,
) -> Vec<T> {
    // Ascending `last_contact` == longest-unseen first.
    online.sort_by_key(|(_, last_contact)| *last_contact);
    offline.sort_by_key(|(_, last_contact)| *last_contact);
    let online_take = online.len().min(fanout);
    let mut out: Vec<T> = online.drain(..online_take).map(|(c, _)| c).collect();
    let offline_take = offline.len().min(fanout - out.len());
    out.extend(offline.drain(..offline_take).map(|(c, _)| c));
    out
}

/// How many online peers this mesh can hold before a reachable peer can be
/// carried past `offline_threshold` by selection pressure alone. Above
/// this, `FANOUT` (or the threshold, or the interval) has to grow — the
/// point of stating it as a function is that the ceiling is checkable
/// instead of being an emergent property of a shuffle.
fn max_online_peers_before_false_offline(
    fanout: usize,
    interval: Duration,
    offline_threshold: Duration,
) -> usize {
    if interval.is_zero() {
        return usize::MAX;
    }
    // A peer must be reached within `rounds` rounds; staleness ordering
    // reaches every online peer within ceil(n / fanout).
    let rounds = (offline_threshold.as_secs() / interval.as_secs()) as usize;
    fanout.saturating_mul(rounds)
}

/// One full gossip round. Touches own `last_seen`, decays stale
/// peers, then pair-gossips with up to `FANOUT` members — online ones
/// first (`select_round_peers`).
pub async fn run_one_round(
    app_state: &AppState,
    offline_threshold: Duration,
) -> Result<(), GossipError> {
    let self_id = *app_state.inner.self_node_id_swap.load_full().as_ref();
    let now = app_state.clock().now_unix_secs();
    let threshold = offline_threshold.as_secs();

    // Build a fresh snapshot of our own capabilities BEFORE we take
    // the mesh write lock — `installed_indexes()` awaits a directory
    // read, and we don't want to pin the lock across that. The
    // engine is optional: test daemons and the CLI run without one.
    let availability = *app_state.inner.local_inference_availability.read().await;
    // Pull the live embed model from the inference store. This is
    // what `daemon::start_daemon` publishes after the fast slot
    // probes the GGUF. `None` on fresh daemons / pure-storage nodes;
    // the planner treats that as "don't include me in distribution".
    let embed_model = app_state.inner.inference_store.get_local_embed_model();
    let fresh_caps = build_local_capabilities(
        app_state.inner.corpus_engine.as_ref(),
        now,
        availability,
        embed_model,
        Some(app_state),
    )
    .await;
    // Step 1: touch self + decay stale peers. One write-lock window.
    // Compare current vs. fresh hosted_corpora so we can log at
    // info only when the advertised set changed (new corpus
    // installed, one removed) — the every-10s heartbeat otherwise
    // logs at debug. Same gating policy as `mesh_state: rebuilt`.
    let candidates: Vec<(PeerContact, bool, u64)> = {
        let mut mesh = app_state.inner.mesh.write().await;
        let prior_corpora: std::collections::BTreeSet<String> = mesh
            .members
            .get(&self_id)
            .map(|m| {
                m.capabilities
                    .hosted_corpora
                    .iter()
                    .map(|c| c.corpus_id.clone())
                    .collect()
            })
            .unwrap_or_default();
        let fresh_corpora: std::collections::BTreeSet<String> = fresh_caps
            .hosted_corpora
            .iter()
            .map(|c| c.corpus_id.clone())
            .collect();
        if fresh_corpora != prior_corpora {
            tracing::info!(
                hosted_corpora = ?fresh_corpora,
                system_ram_gb = fresh_caps.hardware.system_ram_gb,
                "gossip: hosted_corpora set changed — re-publishing"
            );
        } else {
            tracing::debug!(
                hosted_corpora = ?fresh_corpora,
                "gossip: publishing (unchanged)"
            );
        }
        if let Some(me) = mesh.members.get_mut(&self_id) {
            me.last_seen = now;
            me.status = NodeStatus::Online;
            // Replace capabilities with the freshly-sampled version
            // every round. This is the mechanism by which a newly-
            // installed SEP corpus becomes visible to peers within
            // one gossip interval — without it, `hosted_corpora`
            // stays frozen at whatever it was when the daemon
            // started (typically empty, since the user hasn't yet
            // run the install).
            me.capabilities = fresh_caps;
            // Stamp our identity pubkey every round. This is how a
            // node that upgraded in place (mesh created/joined
            // before identity keys existed) publishes its key
            // without a rejoin — within one gossip interval the
            // whole mesh learns it.
            if let Some(pubkey) = app_state.self_node_pubkey() {
                me.node_pubkey = Some(pubkey);
            }
            // Stamp our LIVE iroh dial info every round (W2). Unlike
            // the immutable pubkey, relay + hole-punched addrs appear
            // and change after the endpoint binds, so we re-read the
            // provider each round — peers learn our current
            // reachability within one interval. With this + the
            // pubkey, "known member" == "dialable by key". A `None`
            // provider (iroh disabled) leaves these fields at their
            // default empty, so a non-iroh node publishes nothing here.
            if let Some(info) = app_state.self_iroh_dialinfo() {
                let changed =
                    me.relay_url != info.relay_url || me.iroh_direct_addrs != info.direct_addrs;
                me.relay_url = info.relay_url;
                me.iroh_direct_addrs = info.direct_addrs;
                // WS-D anti-downgrade: SIGN our dial info so peers can
                // verify only we changed it (a gossip-strip attacker past
                // the join-key gate can't force us unreachable / downgrade
                // us). Bump the monotonic version on a real content change
                // so a replayed older signed record loses the merge
                // version check. Only commit version + sig together when a
                // signer is installed (iroh on); else stay unsigned.
                if changed || me.dial_info_sig.is_none() {
                    let next_version = if changed {
                        me.dial_info_version.saturating_add(1).max(1)
                    } else {
                        me.dial_info_version.max(1)
                    };
                    if let Some(sig) = app_state.sign_dial_info(
                        next_version,
                        me.relay_url.as_deref(),
                        &me.iroh_direct_addrs,
                    ) {
                        me.dial_info_version = next_version;
                        me.dial_info_sig = Some(sig);
                    }
                }
            }
        }
        for (id, m) in mesh.members.iter_mut() {
            if *id == self_id {
                continue;
            }
            // Decay measures LOCAL-observation staleness — the local-clock
            // time at which we last saw this peer's record advance (set via
            // `observe_peer_contact` in the merge paths below + the receive
            // handler) — NOT the peer's own gossiped `last_seen`. Comparing a
            // remote clock against ours is what caused the "~9 min flap" (todo
            // `f152dfe7` #4): a clock-skewed-but-live peer looked stale.
            // `peer_contact_or_init` lazy-inits a freshly-seen peer to `now`, a
            // full grace window, so we never decay a peer we just learned of.
            let last_contact = app_state.peer_contact_or_init(*id, now);
            if now.saturating_sub(last_contact) > threshold && m.status != NodeStatus::Offline {
                m.status = NodeStatus::Offline;
                info!(
                    peer = %m.node_id,
                    name = %m.name,
                    staleness_secs = now.saturating_sub(last_contact),
                    threshold_secs = threshold,
                    last_contact_unix = last_contact,
                    addrs = ?m.addresses,
                    "gossip: peer marked Offline (no local contact within threshold)"
                );
            }
            // The symmetric offline→online transition is observed where we
            // merge a peer's heartbeat (below) — that refreshes `last_contact`
            // and flips status back to Online. The decay pass only moves
            // Online→Offline, so no online-transition log here.
        }
        mesh.members
            .values()
            .filter(|m| m.node_id != self_id)
            // The transport sorts candidates IPv4-first on
            // resolution and promotes the last-working address,
            // so the contact carries the raw gossiped list.
            //
            // Status AND local-contact staleness ride along, because the
            // round's SELECTION depends on both — see `select_round_peers`.
            // Read here, inside the same lock that just ran the offline-decay
            // pass and via the same `peer_contact_or_init` it used, so the
            // selection sees this round's numbers and not last round's.
            .map(|m| {
                (
                    peer_contact(m),
                    m.status != NodeStatus::Offline,
                    app_state.peer_contact_or_init(m.node_id, now),
                )
            })
            .collect()
    };

    if candidates.is_empty() {
        // Solo mesh — nothing to do. Still valuable to have fired
        // the round so self's `last_seen` stays current for the
        // moment a peer does arrive.
        return Ok(());
    }

    // Step 2: pick up to FANOUT peers — online ones first, most-stale
    // first within each group. Not a heuristic: see `select_round_peers`
    // for why random sampling here is what decays healthy peers to
    // Offline. No RNG is involved any more, which is also why nothing
    // needs scoping around the `.await`s below.
    let selection = {
        let (online, offline): (Vec<_>, Vec<_>) =
            candidates.into_iter().partition(|(_, up, _)| *up);
        select_round_peers(
            online.into_iter().map(|(c, _, s)| (c, s)).collect(),
            offline.into_iter().map(|(c, _, s)| (c, s)).collect(),
            FANOUT,
        )
    };

    // Step 3: snapshot our mesh once and POST it to each picked
    // peer. Using the same snapshot across the fan-out keeps rounds
    // cheap and means every peer sees the same view of us.
    let my_snapshot = { app_state.inner.mesh.read().await.clone() };
    let http = reqwest::Client::builder()
        .timeout(PEER_TIMEOUT)
        .build()
        .map_err(|e| GossipError::ClientBuild(e.to_string()))?;

    let transport = app_state.peer_transport();
    for contact in selection {
        let peer_id = contact.node_id;
        // The transport resolves and orders candidates: the address
        // that worked last round goes first. The common case is
        // "Tailscale 100.x stable, LAN 192.168.x stale because the
        // Mac is on a different subnet from linux-peer" — without
        // that hint, every round burns `PEER_TIMEOUT` (3s) on the
        // dead LAN address before falling through to Tailscale.
        // Best-effort: a stale hint just slows down THIS round, and
        // the next success rewrites it.
        let endpoints = transport.endpoints(&contact, TrafficClass::Gossip).await;
        if endpoints.is_empty() {
            debug!(peer = %peer_id, "gossip: no addresses on record, skipping");
            continue;
        }
        for ep in &endpoints {
            // Per-address timing so we can diagnose the Online↔Offline
            // flap (see todo `f152dfe7` #4). Each line is one address
            // attempt with elapsed ms and outcome, so offline decay can
            // be correlated with a run of failed reaches on a specific
            // address family (LAN vs Tailscale).
            let attempt_start = Instant::now();
            match gossip_with_peer(http, &ep.base_url, &my_snapshot).await {
                Ok(their_view) => {
                    let reach_ms = attempt_start.elapsed().as_millis() as u64;
                    info!(
                        peer = %peer_id,
                        peer_addr = %ep.label,
                        reach_ms,
                        "gossip: reach ok"
                    );
                    // Pin this endpoint as the preferred starting
                    // point for the next round's resolution.
                    transport.note_success(peer_id, TrafficClass::Gossip, ep);
                    let mut mesh = app_state.inner.mesh.write().await;
                    let report = mesh.merge_from(self_id, &their_view);
                    // Stamp local-observation time for every peer whose record
                    // advanced in this merge (incl. transitively-relayed ones),
                    // so offline-decay sees them as freshly-observed.
                    for observed_id in &report.observed {
                        app_state.observe_peer_contact(*observed_id, now);
                    }
                    if report.added > 0 {
                        info!(
                            peer = %peer_id,
                            peer_addr = %ep.label,
                            added = report.added,
                            updated = report.updated,
                            "gossip: member added from peer's view"
                        );
                    } else if report.updated > 0 {
                        tracing::debug!(
                            peer = %peer_id,
                            peer_addr = %ep.label,
                            updated = report.updated,
                            "gossip: merged peer's view (last_seen refresh)"
                        );
                    }
                    // Also bump THIS peer's last_seen in case their
                    // view of themselves lagged — we successfully
                    // reached them just now, so they're Online.
                    //
                    // Log the offline→online transition at INFO so
                    // the operator can see "B is back" without
                    // polling mesh_state() by hand. Symmetric to the
                    // offline-decay log in the pass above.
                    if let Some(peer) = mesh.members.get_mut(&peer_id) {
                        let was_offline = peer.status == NodeStatus::Offline;
                        peer.last_seen = app_state.clock().now_unix_secs();
                        peer.status = NodeStatus::Online;
                        if was_offline {
                            info!(
                                peer = %peer_id,
                                peer_addr = %ep.label,
                                name = %peer.name,
                                "gossip: peer back Online"
                            );
                        }
                    }
                    break; // one working address is enough
                }
                Err(e) => {
                    let reach_ms = attempt_start.elapsed().as_millis() as u64;
                    // Demoted to debug: a single failed address is
                    // expected on multi-homed peers (e.g. a stale LAN
                    // IP behind a working Tailscale address). The
                    // address-cache reorder above means this typically
                    // fires at most once per peer per process — after
                    // that, the working address goes first and the
                    // dead one is never tried again. If reachability
                    // truly breaks, every attempt fails and the peer
                    // decays to Offline via the `last_seen` threshold,
                    // which logs at INFO from the decay path.
                    debug!(
                        peer = %peer_id,
                        peer_addr = %ep.label,
                        reach_ms,
                        error = %e,
                        "gossip: reach failed, trying next address"
                    );
                    continue;
                }
            }
        }
    }

    // ── Step 4: mesh_store replication ──────────────────────────────
    //
    // The Mesh gossip above only syncs the member list. Entries in
    // `mesh_store` (queue-mode IngestionHandoffs, app-state blobs,
    // app manifests) need their own push — `/internal/app/state`
    // has been the receiver since before the work-queue work, but
    // nothing has ever been the *sender*. Without this step, a
    // coordinator-registered pull-based handoff stays invisible to
    // peers, their `discover_and_spawn_pull_loops` finds nothing to
    // scan, and the queue path silently does nothing despite both
    // nodes thinking they set it up.
    //
    // Payload: full snapshot (anti-entropy). LWW merge on the receiver
    // (`mesh_store::merge_entry`) makes duplicates cheap — the cost is
    // one POST per online peer per round, and at 10s cadence with a
    // handful of handoffs that's negligible.
    if let Ok(entries) = app_state.inner.mesh_store.all_entries_for_gossip() {
        if !entries.is_empty() {
            let wire_entries: Vec<serde_json::Value> = entries
                .iter()
                .map(|e| {
                    serde_json::json!({
                        "app_id": e.app_id,
                        "key": e.key,
                        // `/internal/app/state`'s base64_decode stub
                        // passes the value through as raw UTF-8. All
                        // current mesh_store entries are JSON blobs
                        // (handoffs, app manifests) that round-trip
                        // cleanly through UTF-8.
                        "value_b64": String::from_utf8_lossy(&e.value).into_owned(),
                        "timestamp": e.timestamp,
                        "origin_hex": hex::encode(e.origin.as_bytes()),
                    })
                })
                .collect();
            let store_body = serde_json::json!({ "entries": wire_entries });

            // Re-read the peer list — the earlier loop consumed `selection`.
            let store_targets: Vec<PeerContact> = {
                let mesh = app_state.inner.mesh.read().await;
                mesh.members
                    .values()
                    .filter(|m| m.node_id != self_id && m.status == NodeStatus::Online)
                    .map(peer_contact)
                    .collect()
            };

            for contact in store_targets {
                let peer_id = contact.node_id;
                let endpoints = transport.endpoints(&contact, TrafficClass::Gossip).await;
                for ep in &endpoints {
                    let url = format!("{}/internal/app/state", ep.base_url);
                    let push_start = Instant::now();
                    match http.post(&url).json(&store_body).send().await {
                        Ok(resp) if resp.status().is_success() => {
                            let push_ms = push_start.elapsed().as_millis() as u64;
                            tracing::debug!(
                                peer = %peer_id,
                                url = %url,
                                push_ms,
                                entries = entries.len(),
                                "gossip: mesh_store pushed to peer"
                            );
                            break; // one working address is enough
                        }
                        Ok(resp) => {
                            let push_ms = push_start.elapsed().as_millis() as u64;
                            tracing::debug!(
                                peer = %peer_id,
                                url = %url,
                                push_ms,
                                status = %resp.status(),
                                "gossip: mesh_store push rejected"
                            );
                            break;
                        }
                        Err(e) => {
                            let push_ms = push_start.elapsed().as_millis() as u64;
                            tracing::debug!(
                                peer = %peer_id,
                                url = %url,
                                push_ms,
                                error = %e,
                                "gossip: mesh_store push failed, trying next address"
                            );
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

/// Announce graceful departure: tombstone our own `MemberRecord` and push the
/// snapshot to every online peer once, so they remove us mesh-wide instead of
/// re-gossiping our stale live record forever (the immortal-ghost bug). The
/// event-time LWW in `Mesh::merge_from` makes the tombstone out-compete a peer's
/// live copy of us — our `removed_at`/`last_seen` are stamped at departure,
/// strictly later than any peer's last-seen-of-us — and peers that receive it
/// re-gossip it onward, so it converges even to peers we couldn't reach
/// directly. Best-effort; called from `EmbeddedDaemon::leave` before teardown.
pub async fn announce_departure(app_state: &AppState) {
    let self_id = *app_state.inner.self_node_id_swap.load_full().as_ref();
    let now = app_state.clock().now_unix_secs();
    let (snapshot, targets) = {
        let mut mesh = app_state.inner.mesh.write().await;
        if let Some(me) = mesh.members.get_mut(&self_id) {
            me.removed_at = Some(now);
            me.status = NodeStatus::Offline;
            me.last_seen = now; // event_time(self) = now, beating peers' stale copies
        }
        let targets: Vec<PeerContact> = mesh
            .members
            .values()
            .filter(|m| m.node_id != self_id && m.status == NodeStatus::Online && m.is_active())
            .map(peer_contact)
            .collect();
        (mesh.clone(), targets)
    };
    let http = match reqwest::Client::builder().timeout(PEER_TIMEOUT).build() {
        Ok(c) => c,
        Err(_) => return,
    };
    let transport = app_state.peer_transport();
    let mut announced = 0usize;
    for contact in &targets {
        let eps = transport.endpoints(contact, TrafficClass::Gossip).await;
        for ep in &eps {
            if gossip_with_peer(http, &ep.base_url, &snapshot)
                .await
                .is_ok()
            {
                announced += 1;
                break;
            }
        }
    }
    info!(
        self_id = %self_id,
        peers = targets.len(),
        announced,
        "gossip: announced departure (self-tombstone pushed to online peers)"
    );
}

/// Fire-and-forget broadcast of a single mesh_store entry to every
/// online peer. Used by latency-sensitive writers (e.g. the work
/// atlas's `declare_scope`) that need a claim visible across the
/// mesh in the same round-trip rather than waiting up to one full
/// `DEFAULT_GOSSIP_INTERVAL` for the next anti-entropy round.
///
/// Best-effort: unreachable peers are logged at `warn` (one line per
/// failure) and skipped. The next gossip round will pick the entry
/// up via the normal anti-entropy path anyway, so a transient peer
/// outage doesn't lose the write.
///
/// Privacy: the caller is responsible for ensuring `app_id` is not
/// in `GOSSIP_EXCLUDED_APP_IDS`. The store's own `set` already
/// permits writes to excluded namespaces (the exclusion happens at
/// the gossip-read boundary, not the write boundary), so a sloppy
/// caller could in principle broadcast a Private record. The work
/// atlas's typed facade only calls `broadcast_now` for Public claims
/// — Private claims skip this entirely.
pub async fn broadcast_now(app_state: &AppState, app_id: &str, key: &str) {
    if commonwealth_state::is_gossip_excluded(app_id) {
        // Defence-in-depth: even if a caller passed a private app_id,
        // refuse to broadcast it. This is the third privacy layer
        // for the work atlas — store-level mapping + gossip filter +
        // this guard.
        tracing::warn!(app_id, "work_atlas:broadcast_now refused private app_id");
        return;
    }

    let entry = match app_state.inner.mesh_store.get(app_id, key) {
        Ok(Some(e)) => e,
        Ok(None) => {
            tracing::debug!(app_id, key, "broadcast_now: no entry");
            return;
        }
        Err(e) => {
            tracing::warn!(app_id, key, error = %e, "broadcast_now: store read failed");
            return;
        }
    };

    let self_id = *app_state.inner.self_node_id_swap.load_full().as_ref();
    let wire = serde_json::json!({
        "entries": [{
            "app_id": entry.app_id,
            "key": entry.key,
            "value_b64": String::from_utf8_lossy(&entry.value).into_owned(),
            "timestamp": entry.timestamp,
            "origin_hex": hex::encode(entry.origin.as_bytes()),
        }]
    });

    let targets: Vec<PeerContact> = {
        let mesh = app_state.inner.mesh.read().await;
        mesh.members
            .values()
            .filter(|m| m.node_id != self_id && m.status == NodeStatus::Online)
            .map(peer_contact)
            .collect()
    };

    if targets.is_empty() {
        return;
    }

    let http = match reqwest::Client::builder().timeout(PEER_TIMEOUT).build() {
        Ok(c) => c,
        Err(e) => {
            tracing::warn!(error = %e, "broadcast_now: client build failed");
            return;
        }
    };

    // Fan out concurrently — claim writers shouldn't pay
    // serial latency for slow peers.
    let transport = app_state.peer_transport();
    let mut handles = Vec::with_capacity(targets.len());
    for contact in targets {
        let peer_id = contact.node_id;
        let http = http.clone();
        let body = wire.clone();
        let endpoints = transport.endpoints(&contact, TrafficClass::Gossip).await;
        handles.push(tokio::spawn(async move {
            for ep in endpoints {
                let url = format!("{}/internal/app/state", ep.base_url);
                match http.post(&url).json(&body).send().await {
                    Ok(resp) if resp.status().is_success() => return,
                    Ok(resp) => {
                        tracing::debug!(
                            peer = %peer_id,
                            url = %url,
                            status = %resp.status(),
                            "work_atlas:broadcast_now peer rejected"
                        );
                    }
                    Err(e) => {
                        tracing::debug!(
                            peer = %peer_id,
                            url = %url,
                            error = %e,
                            "work_atlas:broadcast_now peer unreachable, trying next addr"
                        );
                    }
                }
            }
            tracing::warn!(
                peer = %peer_id,
                "work_atlas:broadcast_now_failed (all addrs exhausted)"
            );
        }));
    }
    for h in handles {
        let _ = h.await;
    }
}

async fn gossip_with_peer(
    http: &reqwest::Client,
    base_url: &str,
    my_view: &Mesh,
) -> Result<Mesh, GossipError> {
    let body = GossipRequestWire {
        mesh: MeshWire::from(my_view),
    };
    let url = format!("{base_url}/internal/gossip");
    let response = http
        .post(&url)
        .json(&body)
        .send()
        .await
        .map_err(|e| GossipError::Transport(e.to_string()))?;

    if response.status() == reqwest::StatusCode::UNAUTHORIZED {
        return Err(GossipError::Rejected);
    }
    if !response.status().is_success() {
        return Err(GossipError::Transport(format!(
            "unexpected status {}",
            response.status()
        )));
    }

    let parsed: GossipResponseWire = response
        .json()
        .await
        .map_err(|e| GossipError::BadResponse(e.to_string()))?;
    Ok(parsed.mesh.into_mesh())
}

#[derive(Debug, thiserror::Error)]
pub enum GossipError {
    #[error("failed to build HTTP client: {0}")]
    ClientBuild(String),
    #[error("peer rejected gossip (wrong mesh or key)")]
    Rejected,
    #[error("transport error: {0}")]
    Transport(String),
    #[error("malformed peer response: {0}")]
    BadResponse(String),
}

// ── Wire types ───────────────────────────────────────────────
//
// Mirror of `commonwealth_api::routes_internal::{GossipRequest,
// GossipResponse, MeshWire}`. Duplicated here (like `join::MeshWire`)
// because the server-side type isn't re-exported and projecting
// HashMap<NodeId, MemberRecord> → Vec<MemberRecord> for serde is
// the whole reason MeshWire exists.

#[derive(Debug, Serialize)]
struct GossipRequestWire {
    mesh: MeshWire,
}

#[derive(Debug, Deserialize)]
struct GossipResponseWire {
    mesh: MeshWire,
}

#[derive(Debug, Serialize, Deserialize)]
struct MeshWire {
    id: MeshId,
    name: String,
    join_key_hash: [u8; 32],
    #[serde(default)]
    require_encryption: bool,
    members: Vec<MemberRecord>,
    peers: Vec<MeshPeering>,
}

impl From<&Mesh> for MeshWire {
    fn from(m: &Mesh) -> Self {
        Self {
            id: m.id,
            name: m.name.clone(),
            join_key_hash: m.join_key_hash,
            require_encryption: m.require_encryption,
            members: m.members.values().cloned().collect(),
            peers: m.peers.clone(),
        }
    }
}

impl MeshWire {
    fn into_mesh(self) -> Mesh {
        use std::collections::HashMap;
        let members = self
            .members
            .into_iter()
            .map(|m| (m.node_id, m))
            .collect::<HashMap<_, _>>();
        Mesh {
            id: self.id,
            name: self.name,
            join_key_hash: self.join_key_hash,
            require_encryption: self.require_encryption,
            members,
            peers: self.peers,
        }
    }
}

#[cfg(test)]
mod select_round_peers_tests {
    use super::{
        max_online_peers_before_false_offline, select_round_peers, DEFAULT_GOSSIP_INTERVAL,
        DEFAULT_OFFLINE_THRESHOLD, FANOUT,
    };

    /// Simulate `rounds` gossip rounds over a fixed member set and return, for
    /// each online peer, the WORST gap (in rounds) it ever went uncontacted.
    /// A peer contacted every round has a gap of 1.
    ///
    /// This is the only honest way to test the property at issue: the bug was
    /// never visible in a single round, only in a streak of them.
    fn worst_contact_gap(online: usize, offline: usize, fanout: usize, rounds: usize) -> usize {
        let mut last_contact: Vec<u64> = vec![0; online + offline];
        let mut worst = vec![0usize; online];
        for round in 1..=rounds {
            let up: Vec<(usize, u64)> = (0..online).map(|i| (i, last_contact[i])).collect();
            let down: Vec<(usize, u64)> = (online..online + offline)
                .map(|i| (i, last_contact[i]))
                .collect();
            for id in select_round_peers(up, down, fanout) {
                if id < online {
                    worst[id] = worst[id].max(round - last_contact[id] as usize);
                }
                // Contact stamps the round number, exactly as
                // `observe_peer_contact` stamps the clock in the real loop.
                last_contact[id] = round as u64;
            }
        }
        // Count the TRAILING gap too. Without this a peer that is never
        // selected at all keeps a worst-gap of 0 and the assertion passes
        // vacuously — the exact shape of the bug being tested for.
        for (id, w) in worst.iter_mut().enumerate() {
            *w = (*w).max(rounds - last_contact[id] as usize);
        }
        worst.into_iter().max().unwrap_or(0)
    }

    /// How many rounds fit inside the offline threshold — the budget a peer
    /// has to be contacted within, and the number the threshold's own
    /// "roughly 6× the interval" doc comment is reasoning about.
    fn rounds_before_decay() -> usize {
        (DEFAULT_OFFLINE_THRESHOLD.as_secs() / DEFAULT_GOSSIP_INTERVAL.as_secs()) as usize
    }

    /// The live Meshsonics shape that retired a healthy distributed 122B: one
    /// online peer, two long-dead members, `FANOUT = 2`. The online peer must
    /// be contacted EVERY round — the threshold is counted in rounds, and a
    /// miss streak is what decayed it.
    #[test]
    fn the_only_online_peer_is_contacted_every_round_when_corpses_outnumber_it() {
        assert_eq!(worst_contact_gap(1, 2, FANOUT, 200), 1);
        let picked = select_round_peers(vec![("BeefyMac", 10)], vec![("LittleMac", 0)], FANOUT);
        assert_eq!(
            picked[0], "BeefyMac",
            "the live peer must be dialed FIRST — before an unreachable member burns PEER_TIMEOUT — \
             even though it is the FRESHER of the two"
        );
    }

    /// The generalised rule, and the one a growing mesh actually needs: a
    /// reachable peer must never be carried past the offline threshold by
    /// selection pressure alone. Asserted across every mesh size the
    /// configured fan-out is supposed to cover, with corpses mixed in.
    ///
    /// The old shuffle-and-truncate fails this at EVERY size, corpses or not
    /// — simulated over 5000 rounds at `FANOUT = 2` against a 6-round budget,
    /// worst gap in rounds: 1 online + 2 offline → 8; **3 online + 0 offline
    /// → 12**; 6 online → 26; 6 online + 2 offline → 32; 12 online → 59. The
    /// dead members on Meshsonics made it fire sooner, but three healthy
    /// peers and no corpses at all is already past the threshold. Random
    /// sampling was never sound here; the corpses only set the rate.
    #[test]
    fn no_reachable_peer_is_ever_carried_past_the_offline_threshold() {
        let budget = rounds_before_decay();
        let ceiling = max_online_peers_before_false_offline(
            FANOUT,
            DEFAULT_GOSSIP_INTERVAL,
            DEFAULT_OFFLINE_THRESHOLD,
        );
        assert!(ceiling >= 2, "fan-out must cover at least a pair");
        for online in 1..=ceiling {
            for corpses in 0..4 {
                let gap = worst_contact_gap(online, corpses, FANOUT, 300);
                assert!(
                    gap <= budget,
                    "{online} online + {corpses} offline: a healthy peer went {gap} rounds \
                     uncontacted, past the {budget}-round offline budget"
                );
            }
        }
    }

    /// Staleness ordering is what produces that bound: the longest-unseen
    /// peer goes first, so a peer that misses a round is promoted, not
    /// re-entered into a fresh lottery.
    #[test]
    fn the_longest_unseen_peer_is_selected_first() {
        let picked = select_round_peers(
            vec![("fresh", 100), ("stalest", 5), ("middling", 50)],
            Vec::new(),
            2,
        );
        assert_eq!(picked, vec!["stalest", "middling"]);
    }

    /// Reachability is the ONLY axis. A peer that is online but useless for
    /// the workload at hand is still gossiped with every round like any
    /// other — members belong to a mesh for their own reasons, and a run
    /// drawing on a subset of them is normal, not degraded.
    #[test]
    fn selection_reads_reachability_only_never_capability() {
        // Same shape, twice: the function has no input by which "can this
        // peer serve a 122B shard" could possibly influence the outcome.
        let a = select_round_peers(vec![("tiny-laptop", 1), ("big-gpu-box", 2)], Vec::new(), 2);
        assert_eq!(a, vec!["tiny-laptop", "big-gpu-box"]);
    }

    /// Every online peer we have room for is taken before any offline one.
    #[test]
    fn online_peers_fill_the_fanout_before_offline_peers_get_a_slot() {
        let picked = select_round_peers(
            vec![("a", 1), ("b", 2), ("c", 3)],
            vec![("dead", 0)],
            2,
        );
        assert_eq!(picked, vec!["a", "b"]);
    }

    /// A fully-partitioned node — nothing online — must still probe, or it
    /// could never rejoin.
    #[test]
    fn a_node_with_no_online_peers_still_probes_the_offline_ones() {
        let picked = select_round_peers(
            Vec::<(&str, u64)>::new(),
            vec![("dead-a", 1), ("dead-b", 2), ("dead-c", 3)],
            2,
        );
        assert_eq!(picked, vec!["dead-a", "dead-b"]);
    }

    /// Fewer candidates than the fan-out is not an error, and a solo mesh
    /// selects nothing rather than panicking on the `fanout - out.len()` math.
    #[test]
    fn short_candidate_lists_and_an_empty_mesh_are_handled() {
        assert_eq!(
            select_round_peers(vec![("a", 0)], Vec::new(), 2),
            vec!["a"]
        );
        assert!(select_round_peers(Vec::<(&str, u64)>::new(), Vec::new(), 2).is_empty());
        assert!(select_round_peers(vec![("a", 0)], vec![("b", 0)], 0).is_empty());
    }

    /// The ceiling is a real number the operator could act on, not a
    /// formality: at the shipped constants it must cover a mesh comfortably
    /// larger than the current one.
    #[test]
    fn the_documented_ceiling_matches_the_shipped_constants() {
        assert_eq!(
            max_online_peers_before_false_offline(
                FANOUT,
                DEFAULT_GOSSIP_INTERVAL,
                DEFAULT_OFFLINE_THRESHOLD
            ),
            12,
            "FANOUT=2 × (60s / 10s) = 12 online peers"
        );
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later
//! `svrn mesh bench` — measure how fast the configuration you are **running**
//! actually decodes, and file the number under the key `svrn mesh plan` looks
//! up.
//!
//! # The one rule
//!
//! **This command measures what is loaded. It never loads what it wants to
//! measure.** There is no slot argument, no model argument that selects
//! anything, and no `--distributed` flag. It reads the daemon's own report of
//! which model occupies the primary slot and how that model is placed, fires
//! real completions at the real HTTP surface, and times the frames coming back.
//!
//! That is not a convenience — it is the mechanism that satisfies
//! `SCHEDULER_QUALITY.md` §4.5's "probe the model being scored". A benchmark
//! that installs its own configuration measures the benchmark. The optional
//! `<model.gguf>` argument is therefore an **assertion**, not a selection: it is
//! fingerprinted from its header and compared against the resident primary, and
//! a mismatch is exit 3 naming the config line to fix.
//!
//! # Why the guards are the interesting part
//!
//! Getting a tokens-per-second number is easy. Getting one that is *about the
//! thing you think it is about* is the whole problem, and every guard below was
//! earned by a specific observed false result — see the header of
//! `scripts/measure-distributed-decode.sh`, which this command replaces.
//!
//! The worst of them is the Fast-slot trap. This repo runs a small always-hot
//! `fast` model beside the big `primary` one. A request that gets hijacked to
//! the fast slot returns quickly and successfully and proves *nothing* — the
//! small model is 100% local, so a "distributed decode" measurement taken that
//! way is a local decode of a different model.
//!
//! The shell script guarded this by asserting the SSE `model` field names the
//! primary. **That check cannot work**, and this command's first live run
//! proved it: the field is a verbatim echo of the string the client requested,
//! so it says `commonwealth/primary` no matter what answered. With the 122B's
//! compute child still starting, requests came back at ~100 tok/s — impossible
//! for that model — with the check passing cleanly. See [`primary_is_serving`]
//! for what replaced it, and for the second trap hiding behind the first.
//!
//! A run that trips any guard is still **written to the store**. Discarding a
//! failure teaches nobody anything, and silently dropping it turns the tool into
//! retry-until-lucky. It is simply recorded [`Verdict::Invalid`] and
//! `mesh_measurements::lookup` never returns it.
//!
//! # The seam
//!
//! Everything below the `cmd_bench` shell is pure: [`parse_trial`],
//! [`evaluate_guards`], [`aggregate`] and [`shards_from_placement`] take
//! observations and return verdicts, with no HTTP, no clock, and no filesystem.
//! That is what makes nine guards testable without a GPU, a peer, or a
//! 100-gigabyte model. Keep the seam: if a guard needs a new fact, add it to
//! [`GuardInput`] and have the shell go get it.

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use futures::StreamExt;
use sovereign_core::mesh_measurements as mm;

// ---------------------------------------------------------------------------
// The probe
//
// These three constants ARE the probe protocol. `PROBE_VERSION` in
// `mesh_measurements` exists to make numbers taken under different values
// incomparable rather than silently mixed, so:
//
//   CHANGING ANYTHING IN THIS BLOCK REQUIRES BUMPING mm::PROBE_VERSION.
//
// This is also why there is no `--max-tokens` flag. A knob whose adjustment
// invalidates comparison against every prior record, while looking like a
// harmless tuning option, is a trap. `--trials` is safe by contrast: it changes
// how many samples are drawn, not what is being sampled.
// ---------------------------------------------------------------------------

/// The prompt every timed trial sends. Deterministic and long enough to stream
/// well past the 32-frame floor, with no dependence on the model's knowledge.
const PROBE_PROMPT: &str = "Count from 1 to 60, one number per line.";

/// Token budget for a timed trial.
const PROBE_MAX_TOKENS: u32 = 192;

/// Token budget for the canary. Small on purpose: its job is to prove tokens
/// flow at all (and to absorb a cold load) before the timed window is spent.
const CANARY_MAX_TOKENS: u32 = 8;

/// Minimum content frames a trial must produce to be called a decode rate.
/// Below this the measurement is dominated by scheduler jitter.
const MIN_CONTENT_FRAMES: u32 = 32;

/// Maximum permitted disagreement between the fastest and slowest trial, as a
/// fraction of the fastest. Above this the machine was not in a steady state.
const MAX_TRIAL_SPREAD: f64 = 0.25;

/// The alias every request uses. Resolves to the primary slot server-side.
const PRIMARY_ALIAS: &str = "commonwealth/primary";

/// How many times the canary will re-fire while the slot is still loading.
/// With [`CANARY_RETRY`] this is a ~10 minute ceiling — long enough for a cold
/// load of a model measured in tens of gigabytes, short enough to give up.
const CANARY_ATTEMPTS: u32 = 20;

/// Wait between canary attempts.
const CANARY_RETRY: Duration = Duration::from_secs(30);

/// Whether an error from the canary says "the slot is coming up", as opposed to
/// "the slot is broken". Matched on prose because that is what the wire carries;
/// a false negative here just means the canary gives up early and the guards
/// report an honest failure, which is the safe direction.
fn slot_still_starting(err: &str) -> bool {
    let e = err.to_ascii_lowercase();
    e.contains("not serving")
        || e.contains("starting")
        || e.contains("slot unavailable")
        || e.contains("loading")
}

// ---------------------------------------------------------------------------
// Observations — what one streamed completion produced
// ---------------------------------------------------------------------------

/// One line of the SSE response, stamped at the moment it arrived.
///
/// Non-`data:` lines are kept rather than dropped: when the server returns an
/// error body instead of a stream, that body is the only evidence of what went
/// wrong, and a reader that skips it reports "0 frames" for a request that was
/// actually rejected with a reason.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Frame {
    /// Seconds since the request was sent — so time-to-first-token (prefill
    /// plus tunnel setup) separates from the steady-state inter-token rate.
    /// Wall-clock over total tokens smears the two together, which is how a
    /// slow link can be made to look like a slow model.
    pub(crate) t_s: f64,
    /// Body after `data:`, when this was an SSE data line.
    pub(crate) data: Option<String>,
    /// The raw line, when it was not.
    pub(crate) raw: Option<String>,
}

impl Frame {
    /// Classify a single received line.
    pub(crate) fn from_line(t_s: f64, line: &str) -> Self {
        if let Some(rest) = line.strip_prefix("data:") {
            Self {
                t_s,
                data: Some(rest.trim().to_string()),
                raw: None,
            }
        } else {
            Self {
                t_s,
                data: None,
                raw: Some(line.to_string()),
            }
        }
    }
}

/// What one timed streaming completion produced, after parsing.
#[derive(Debug, Clone, Default, PartialEq)]
pub(crate) struct Trial {
    /// The `model` field the server put on its frames. `None` when no frame
    /// carried one — which is itself a guard failure, because an unattributed
    /// run cannot be filed against a configuration.
    pub(crate) served_model: Option<String>,
    /// Frames that carried actual content. The timing basis.
    pub(crate) content_frames: u32,
    /// Seconds to the first content frame.
    pub(crate) ttft_s: Option<f64>,
    /// Seconds between the first and last content frame.
    pub(crate) decode_span_s: f64,
    /// `(content_frames - 1) / decode_span_s` — steady state, TTFT excluded.
    /// Zero when there is no span to divide by; the frame-count guard is what
    /// catches that, not this number.
    pub(crate) decode_tok_s: f64,
    /// Every inter-frame gap in milliseconds. Pooled across trials for the
    /// latency percentiles, where link jitter shows up as a p95 far above p50.
    pub(crate) itl_ms: Vec<f64>,
    /// The terminal `finish_reason`, when the server sent one.
    pub(crate) finish_reason: Option<String>,
    /// `usage.prompt_tokens` from the terminal frame. The **only** admissible
    /// source of a prefill rate — never `text.len() / 4`.
    pub(crate) prompt_tokens: Option<u32>,
    /// Lines that were not SSE data frames, for glassbox triage.
    pub(crate) non_sse_lines: Vec<String>,
    /// First 200 characters of the generated text, so a reader can see that a
    /// plausible-looking rate came from plausible-looking output.
    pub(crate) text_head: String,
}

/// Turn stamped lines into one trial's numbers. Pure.
pub(crate) fn parse_trial(frames: &[Frame]) -> Trial {
    let mut out = Trial::default();
    let mut text = String::new();
    let mut stamps: Vec<f64> = Vec::new();
    let no_choices: Vec<serde_json::Value> = Vec::new();

    for f in frames {
        let Some(data) = &f.data else {
            if let Some(raw) = &f.raw {
                out.non_sse_lines.push(raw.clone());
            }
            continue;
        };
        if data == "[DONE]" {
            continue;
        }
        let Ok(v) = serde_json::from_str::<serde_json::Value>(data) else {
            out.non_sse_lines.push(data.clone());
            continue;
        };
        if let Some(m) = v.get("model").and_then(|m| m.as_str()) {
            out.served_model = Some(m.to_string());
        }
        if let Some(p) = v
            .get("usage")
            .and_then(|u| u.get("prompt_tokens"))
            .and_then(|p| p.as_u64())
        {
            out.prompt_tokens = Some(p as u32);
        }
        let mut got_content = false;
        for ch in v
            .get("choices")
            .and_then(|c| c.as_array())
            .unwrap_or(&no_choices)
        {
            if let Some(piece) = ch
                .get("delta")
                .and_then(|d| d.get("content"))
                .and_then(|c| c.as_str())
            {
                if !piece.is_empty() {
                    text.push_str(piece);
                    got_content = true;
                }
            }
            if let Some(r) = ch.get("finish_reason").and_then(|r| r.as_str()) {
                out.finish_reason = Some(r.to_string());
            }
        }
        if got_content {
            stamps.push(f.t_s);
        }
    }

    out.content_frames = stamps.len() as u32;
    out.ttft_s = stamps.first().copied();
    if stamps.len() > 1 {
        out.decode_span_s = stamps[stamps.len() - 1] - stamps[0];
        if out.decode_span_s > 0.0 {
            out.decode_tok_s = (stamps.len() - 1) as f64 / out.decode_span_s;
        }
        out.itl_ms = stamps.windows(2).map(|w| (w[1] - w[0]) * 1000.0).collect();
    }
    out.text_head = text.chars().take(200).collect();
    out
}

// ---------------------------------------------------------------------------
// Placement
// ---------------------------------------------------------------------------

/// The daemon's report of where the primary's weights are, as `/status` states
/// it. Compared before and after the timed run: a mid-run revert to local turns
/// the tail of the measurement into local decode, which is exactly the false
/// result that looks most like a success.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub(crate) struct PlacementSnapshot {
    /// The daemon's own word: `local` | `distributed` | `child-distributed` |
    /// `stream-split` | `forming`.
    pub(crate) mode: String,
    /// Blocks the plan apportions. `0` for a plain local load, which computes
    /// no block plan.
    pub(crate) total_blocks: u32,
    /// Blocks on this node's own GPU.
    pub(crate) local_blocks: u32,
    /// Remote workers holding a share.
    pub(crate) workers: Vec<WorkerSnapshot>,
}

/// One remote worker's share, as `/status` states it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct WorkerSnapshot {
    /// Raw-TCP rpc-server endpoint, `host:port`.
    pub(crate) endpoint: String,
    /// Blocks pinned onto this worker.
    pub(crate) blocks: u32,
    /// Whether it holds the output head.
    pub(crate) holds_output: bool,
}

/// Turn a live placement into the shard list the measurement key hashes.
///
/// Two properties make this worth its own function:
///
/// **It must agree with `mesh plan`.** The plan side builds its shards from a
/// `DeviceRow` list; this side builds them from what the daemon reports. If the
/// two disagree about node naming or block ranges, every record filed here is
/// unfindable — a store that grows and never answers. The agreement is:
/// contiguous ascending block ranges in the daemon's device order (remote
/// workers first, host last, which is the order `plan_shards_weighted` is
/// called with), a mesh member *name* as the node key, and only the devices
/// that actually hold something.
///
/// **A local load reports no block plan.** `total_blocks` is `0` for a plain
/// local load, so the range comes from the GGUF's own layer count instead —
/// which is what `mesh plan` hashes for the same configuration.
///
/// `resolve` maps an RPC endpoint to a mesh member name. Where it returns
/// `None` the endpoint's host (port dropped — ports churn across restarts and
/// would make every lookup a miss) is used, matching
/// [`mm::PlacementShard::node_key`]'s documented fallback.
pub(crate) fn shards_from_placement(
    placement: &PlacementSnapshot,
    host: &NodeIdentity,
    n_layer: u32,
    resolve: &dyn Fn(&str) -> Option<NodeIdentity>,
) -> Result<Vec<mm::PlacementShard>, String> {
    if n_layer == 0 {
        return Err("the model reports zero transformer blocks".to_string());
    }
    if placement.workers.is_empty() {
        return Ok(vec![mm::PlacementShard {
            node_key: host_name.to_string(),
            blocks: Some((0, n_layer - 1)),
            holds_output: true,
        }]);
    }

    let worker_total: u32 = placement.workers.iter().map(|w| w.blocks).sum();
    let total = if placement.total_blocks > 0 {
        placement.total_blocks
    } else {
        n_layer
    };
    if worker_total + placement.local_blocks != total {
        return Err(format!(
            "placement does not add up: {} worker block(s) + {} local != {total} total",
            worker_total, placement.local_blocks
        ));
    }
    if total != n_layer {
        return Err(format!(
            "placement apportions {total} blocks but the GGUF has {n_layer} — \
             the resident model is not the one whose header was read"
        ));
    }

    let mut shards = Vec::with_capacity(placement.workers.len() + 1);
    let mut next = 0u32;
    for w in &placement.workers {
        let blocks = if w.blocks == 0 {
            None
        } else {
            let range = (next, next + w.blocks - 1);
            next += w.blocks;
            Some(range)
        };
        // A worker holding nothing is not part of the placement. Dropping it
        // keeps the digest describing the machines that carry the model, which
        // is what makes it stable across an idle peer joining or leaving.
        if blocks.is_none() && !w.holds_output {
            continue;
        }
        shards.push(mm::PlacementShard {
            node_key: resolve(&w.endpoint).unwrap_or_else(|| endpoint_host(&w.endpoint)),
            blocks,
            holds_output: w.holds_output,
        });
    }
    let host_holds_output = !placement.workers.iter().any(|w| w.holds_output);
    if placement.local_blocks > 0 || host_holds_output {
        shards.push(mm::PlacementShard {
            node_key: host_name.to_string(),
            blocks: (placement.local_blocks > 0).then_some((next, total - 1)),
            holds_output: host_holds_output,
        });
    }
    Ok(shards)
}

/// `host:port` → `host`. Ports churn across restarts; a digest that included
/// one would miss on every lookup after a worker bounce.
///
/// The colon is not enough to find the port. `fd7a:115c::1` is a bare IPv6
/// address whose final segment is all digits, so a naive `rsplit_once(':')`
/// truncates the address and calls the result a host. Only two forms are
/// unambiguous, and both are left alone otherwise:
///
/// - `[<ipv6>]:port` — the bracketed form, which is what mesh addresses use.
/// - `<host>:port` with exactly one colon — IPv4 or a name.
fn endpoint_host(endpoint: &str) -> String {
    if endpoint.starts_with('[') {
        if let Some(close) = endpoint.rfind(']') {
            return endpoint[..=close].to_string();
        }
        return endpoint.to_string();
    }
    match endpoint.rsplit_once(':') {
        Some((host, port))
            if !host.contains(':') && !port.is_empty() && port.chars().all(|c| c.is_ascii_digit()) =>
        {
            host.to_string()
        }
        _ => endpoint.to_string(),
    }
}

/// The digest's `mode`, derived from topology rather than from the daemon's
/// mode string.
///
/// The daemon distinguishes `local`, `distributed`, `child-distributed`,
/// `stream-split` and `forming`; `mesh plan` — which has no daemon to ask —
/// only ever produces `local` or `distributed`. Deriving from shard count keeps
/// the two vocabularies in agreement, which is the property that makes a record
/// findable. The daemon's own word is preserved verbatim in the record's
/// `placement_human`, so nothing is hidden from a reader.
pub(crate) fn digest_mode(shards: &[mm::PlacementShard]) -> &'static str {
    if shards.len() <= 1 {
        "local"
    } else {
        "distributed"
    }
}

/// Render a placement the way an operator says it out loud.
pub(crate) fn placement_human(
    shards: &[mm::PlacementShard],
    host_name: &str,
    daemon_mode: &str,
) -> String {
    let blocks_of = |s: &mm::PlacementShard| s.blocks.map_or(0, |(a, b)| b - a + 1);
    let mut parts: Vec<String> = Vec::new();
    if let Some(host) = shards.iter().find(|s| s.node_key == host_name) {
        parts.push(format!("{} local", blocks_of(host)));
    }
    for s in shards.iter().filter(|s| s.node_key != host_name) {
        parts.push(format!("{} @{}", blocks_of(s), s.node_key));
    }
    let body = if parts.is_empty() {
        "unplaced".to_string()
    } else {
        parts.join(" + ")
    };
    // Surface the daemon's own word when it is not the plain one the digest
    // uses, so `child-distributed` never silently reads as `distributed`.
    if daemon_mode != digest_mode(shards) && !daemon_mode.is_empty() {
        format!("{body} ({daemon_mode})")
    } else {
        body
    }
}

// ---------------------------------------------------------------------------
// The guards
// ---------------------------------------------------------------------------

/// Whether the host daemon survived the run.
///
/// Detected from `/status`'s own uptime rather than from `pgrep`: a bare
/// process match hits bash wrappers whose command line merely *contains* the
/// daemon path, and a daemon running on a deleted inode after a rebuild must
/// not count either. Uptime going backwards is unambiguous.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum HostLiveness {
    /// Same process throughout.
    Alive,
    /// Uptime went backwards — the daemon died and something restarted it. A
    /// worker's `GGML_ABORT` kills the host process, and this is what that
    /// looks like from outside.
    Restarted,
    /// `/status` stopped answering.
    Gone,
}

/// Everything the validity guards judge.
///
/// Assembled by the shell from real observations, judged here. Every field is
/// data, not a handle — which is what lets all nine guards be exercised in a
/// unit test with no daemon, no peer and no GPU.
pub(crate) struct GuardInput<'a> {
    /// Timed trials, in order.
    pub(crate) trials: &'a [Trial],
    /// The model id occupying the primary slot, per `/status`.
    pub(crate) primary_model_id: &'a str,
    /// Whether `/status` reported the primary slot **resident** immediately
    /// before the timed trials, and again after.
    ///
    /// This is the load-bearing half of the served-slot guard. See
    /// [`evaluate_guards`] for why the SSE `model` field cannot do the job.
    pub(crate) primary_serving_before: bool,
    /// The same reading, after the timed trials.
    pub(crate) primary_serving_after: Option<bool>,
    /// Tokens the canary produced.
    pub(crate) canary_tokens: u32,
    /// Placement read after the canary and before the timed trials.
    pub(crate) placement_before: &'a PlacementSnapshot,
    /// Placement read after the timed trials. `None` when it could not be
    /// re-read at all, which is itself a failure.
    pub(crate) placement_after: Option<&'a PlacementSnapshot>,
    /// `(peer name, online)` for every peer holding a shard, before the run.
    pub(crate) peers_before: &'a [(String, bool)],
    /// The same peers, after.
    pub(crate) peers_after: &'a [(String, bool)],
    /// Whether the daemon survived.
    pub(crate) host_alive_after: HostLiveness,
}

/// Judge a run. Empty means every guard passed.
///
/// Ordered so the most explanatory failure comes first: a dead daemon accounts
/// for every downstream symptom, and an operator reading the list top-down
/// should meet the cause before the consequences.
pub(crate) fn evaluate_guards(g: &GuardInput) -> Vec<String> {
    let mut problems = Vec::new();

    // ── ported guard 6: host alive ──────────────────────────────────────────
    match g.host_alive_after {
        HostLiveness::Alive => {}
        HostLiveness::Restarted => problems.push(
            "the host daemon DIED during the run and was restarted — a worker's GGML_ABORT \
             kills the host process. Everything below describes a broken run, not this \
             configuration."
                .to_string(),
        ),
        HostLiveness::Gone => problems.push(
            "the host daemon stopped answering /status during the run — it died and was not \
             restarted. Everything below describes a broken run, not this configuration."
                .to_string(),
        ),
    }

    // ── ported guard 5: canary first ────────────────────────────────────────
    if g.canary_tokens == 0 {
        problems.push(
            "the canary produced zero tokens — this path is not generating output, so the \
             timed run had nothing to measure."
                .to_string(),
        );
    }

    // ── ported guard 1: which slot served it (the Fast-slot trap) ───────────
    //
    // TWO checks, and the second is the one that works.
    //
    // The SSE `model` field is what the shell script this replaces asserted on,
    // and on this server it is a **verbatim echo of the string the client
    // requested** — every frame of every response says `commonwealth/primary`
    // because that is what was asked for, whatever actually served it. Asserting
    // on it therefore proves only that the request was addressed correctly. It
    // is kept because a client that requests the wrong model IS a real mistake
    // worth catching, but it cannot see a hijack and must never be mistaken for
    // the guard that can. (Measured 2026-07-28: a run against a primary whose
    // compute child was not serving returned ~100 tok/s from a 122B model with
    // this check passing cleanly.)
    //
    // Residency is the signal that attributes. If `/status` says the primary
    // slot was not resident, then whatever produced these tokens was not the
    // model this record names — no matter what the frames claim.
    let served: Vec<&str> = g
        .trials
        .iter()
        .filter_map(|t| t.served_model.as_deref())
        .collect();
    if served.is_empty() {
        problems.push(
            "no `model` field on any SSE frame — the run cannot be attributed to a slot, and \
             an unattributed number cannot be filed against a configuration."
                .to_string(),
        );
    } else if let Some(wrong) = served.iter().find(|m| !names_primary(m, g.primary_model_id)) {
        problems.push(format!(
            "WRONG MODEL REQUESTED: frames name `{wrong}`, but the primary is `{}`.",
            g.primary_model_id
        ));
    }
    if !g.primary_serving_before || g.primary_serving_after == Some(false) {
        problems.push(format!(
            "WRONG SLOT: /status reports the primary (`{}`) was NOT resident during the run, \
             so these tokens came from some other slot — the small always-hot model, or a \
             fallback. A hijacked request returns quickly and successfully and proves nothing; \
             the SSE `model` field cannot see this, because it only echoes what was requested.",
            g.primary_model_id
        ));
    }
    if g.primary_serving_after.is_none() {
        problems.push(
            "could not re-read the primary slot's residency after the run, so there is no \
             evidence the model that answered was still the one this record names."
                .to_string(),
        );
    }

    // ── ported guard 3: placement re-read after ─────────────────────────────
    match g.placement_after {
        None => problems.push(
            "could not re-read the placement after the run, so there is no evidence every \
             timed token crossed the same boundary."
                .to_string(),
        ),
        Some(after) if after != g.placement_before => problems.push(format!(
            "placement changed during the run: {} → {}. Not every timed token was decoded by \
             the configuration this record would be filed under.",
            describe_placement(g.placement_before),
            describe_placement(after)
        )),
        Some(_) => {}
    }

    // ── ported guard 4: peer liveness before and after ──────────────────────
    for (name, online) in g.peers_before {
        if !online {
            problems.push(format!(
                "peer `{name}` holds a shard but was not online when the run started — the \
                 bridge cache can re-mint a known worker with no probe, so discovery keeps \
                 reporting a peer that is already gone."
            ));
        }
    }
    for (name, online) in g.peers_after {
        if !online {
            problems.push(format!(
                "peer `{name}` went offline during the run — the tail of the measurement did \
                 not cross the boundary it claims to."
            ));
        }
    }

    // ── ported guard 2 / new guard 1: enough frames to be a rate ────────────
    if g.trials.is_empty() {
        problems.push("no timed trials completed.".to_string());
    }
    for (i, t) in g.trials.iter().enumerate() {
        if t.content_frames < 2 || t.decode_span_s <= 0.0 {
            problems.push(format!(
                "trial {} produced {} content frame(s) over {:.3}s — a decode rate needs at \
                 least two timestamps to sit between.",
                i + 1,
                t.content_frames,
                t.decode_span_s
            ));
        } else if t.content_frames < MIN_CONTENT_FRAMES {
            problems.push(format!(
                "trial {} produced only {} content frames (floor {MIN_CONTENT_FRAMES}) — too \
                 short to average out scheduler jitter.",
                i + 1,
                t.content_frames
            ));
        }
    }

    // ── new guard 3: the generation actually completed ───────────────────────
    for (i, t) in g.trials.iter().enumerate() {
        match t.finish_reason.as_deref() {
            Some("length") | Some("stop") => {}
            Some(other) => problems.push(format!(
                "trial {} finished with reason `{other}` — only `stop` and `length` are \
                 complete generations; anything else timed a truncated or errored run.",
                i + 1
            )),
            None => problems.push(format!(
                "trial {} never sent a terminal `finish_reason` — the stream ended without \
                 saying it was done, so the last frame may not be the last token.",
                i + 1
            )),
        }
    }

    // ── new guard 2: the machine was in a steady state ──────────────────────
    if let Some(spread) = trial_spread(g.trials) {
        if spread > MAX_TRIAL_SPREAD {
            problems.push(format!(
                "trials disagree by {:.0}% (limit {:.0}%) — this machine was not in a steady \
                 state. Something else was using the GPU, or the model was still warming.",
                spread * 100.0,
                MAX_TRIAL_SPREAD * 100.0
            ));
        }
    }

    problems
}

/// Whether a served model name identifies the primary slot.
///
/// Accepts the alias the request was made under (the server resolves it), the
/// bare `primary`, and any name that contains or is contained by the primary's
/// model id — GGUF stems get suffixed and truncated on the way through the API
/// surface, and a substring match in either direction is what survives that
/// without waving through a *different* model.
fn names_primary(served: &str, primary_model_id: &str) -> bool {
    if served == PRIMARY_ALIAS || served == "primary" {
        return true;
    }
    if primary_model_id.is_empty() {
        return false;
    }
    served.contains(primary_model_id) || primary_model_id.contains(served)
}

/// Relative disagreement between the fastest and slowest trial. `None` with
/// fewer than two trials — one sample cannot disagree with itself, and
/// reporting `0%` there would claim a steadiness that was never tested.
pub(crate) fn trial_spread(trials: &[Trial]) -> Option<f64> {
    if trials.len() < 2 {
        return None;
    }
    let rates: Vec<f64> = trials
        .iter()
        .map(|t| t.decode_tok_s)
        .filter(|r| *r > 0.0)
        .collect();
    if rates.len() < 2 {
        return None;
    }
    let min = rates.iter().copied().fold(f64::INFINITY, f64::min);
    let max = rates.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    (min > 0.0).then(|| (max - min) / min)
}

/// One-line placement description for a guard message.
fn describe_placement(p: &PlacementSnapshot) -> String {
    if p.workers.is_empty() {
        format!("{} ({} local)", p.mode, p.local_blocks)
    } else {
        let w: Vec<String> = p
            .workers
            .iter()
            .map(|w| format!("{}×{}", w.blocks, w.endpoint))
            .collect();
        format!("{} ({} local + {})", p.mode, p.local_blocks, w.join(" + "))
    }
}

// ---------------------------------------------------------------------------
// Aggregation
// ---------------------------------------------------------------------------

/// The numbers a run reports, across its trials.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Aggregate {
    /// Median trial rate — the headline.
    pub(crate) decode_tok_s: f64,
    /// Slowest trial.
    pub(crate) decode_tok_s_min: f64,
    /// Fastest trial.
    pub(crate) decode_tok_s_max: f64,
    /// Median time to first content token.
    pub(crate) ttft_ms: f64,
    /// Median inter-token latency, pooled across trials.
    pub(crate) itl_p50_ms: f64,
    /// 95th percentile of the same, where link jitter shows up.
    pub(crate) itl_p95_ms: f64,
    /// Prefill rate. `Some` only where the server reported real prompt tokens.
    pub(crate) prefill_tok_s: Option<f64>,
    /// Content frames summed across trials.
    pub(crate) content_frames: u32,
    /// Trials contributing.
    pub(crate) trials: u32,
}

/// Reduce trials to the reported numbers. `None` when nothing timed.
///
/// The median, not the mean: a single trial that hit a garbage-collection pause
/// or a background compile should not drag the headline, and with three trials
/// the median is the honest middle. The min and max travel alongside it so the
/// spread is never hidden behind the middle.
pub(crate) fn aggregate(trials: &[Trial]) -> Option<Aggregate> {
    let rates: Vec<f64> = trials
        .iter()
        .map(|t| t.decode_tok_s)
        .filter(|r| *r > 0.0)
        .collect();
    if rates.is_empty() {
        return None;
    }
    let ttfts: Vec<f64> = trials.iter().filter_map(|t| t.ttft_s).collect();
    let itls: Vec<f64> = trials.iter().flat_map(|t| t.itl_ms.iter().copied()).collect();

    // Prefill is a rate only where the SERVER counted the prompt. `None` renders
    // as "n/a", never as an estimate from string length — the exact mistake the
    // deleted `run_baseline_benchmark` made.
    let prefill = {
        let per_trial: Vec<f64> = trials
            .iter()
            .filter_map(|t| match (t.prompt_tokens, t.ttft_s) {
                (Some(p), Some(ttft)) if ttft > 0.0 && p > 0 => Some(p as f64 / ttft),
                _ => None,
            })
            .collect();
        median(&per_trial)
    };

    Some(Aggregate {
        decode_tok_s: median(&rates).unwrap_or(0.0),
        decode_tok_s_min: rates.iter().copied().fold(f64::INFINITY, f64::min),
        decode_tok_s_max: rates.iter().copied().fold(f64::NEG_INFINITY, f64::max),
        ttft_ms: median(&ttfts).map(|s| s * 1000.0).unwrap_or(0.0),
        itl_p50_ms: percentile(&itls, 0.50).unwrap_or(0.0),
        itl_p95_ms: percentile(&itls, 0.95).unwrap_or(0.0),
        prefill_tok_s: prefill,
        content_frames: trials.iter().map(|t| t.content_frames).sum(),
        trials: trials.len() as u32,
    })
}

/// Median of a sample. `None` when empty.
fn median(xs: &[f64]) -> Option<f64> {
    percentile(xs, 0.50)
}

/// Nearest-rank percentile. `None` when empty.
fn percentile(xs: &[f64], q: f64) -> Option<f64> {
    if xs.is_empty() {
        return None;
    }
    let mut v = xs.to_vec();
    v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let idx = ((v.len() as f64 - 1.0) * q).round() as usize;
    v.get(idx).copied()
}

